fn observed_online_rate(healthy_minutes: usize, observed_minutes: usize) -> f64 {
    if observed_minutes == 0 {
        0.0
    } else {
        (healthy_minutes as f64 / observed_minutes as f64 * 100.0).clamp(0.0, 100.0)
    }
}

fn observation_coverage(observed_minutes: usize) -> f64 {
    (observed_minutes as f64 / ONLINE_WINDOW_MINUTES as f64 * 100.0).clamp(0.0, 100.0)
}

fn dashboard_route_state(snapshot: Option<&RouteAvailabilitySnapshot>) -> (String, Option<String>) {
    snapshot
        .map(|snapshot| {
            (
                snapshot.state.as_str().to_string(),
                Some(snapshot.since.to_rfc3339()),
            )
        })
        .unwrap_or_else(|| ("offline".to_string(), None))
}

fn operational_reason(
    code: &str,
    severity: &str,
    started_at: Option<String>,
    entity_type: Option<&str>,
    entity_id: Option<&str>,
    current_value: Option<String>,
    threshold: Option<String>,
) -> OperationalReason {
    OperationalReason {
        code: code.to_string(),
        severity: severity.to_string(),
        started_at,
        entity_type: entity_type.map(str::to_string),
        entity_id: entity_id.map(str::to_string),
        current_value,
        threshold,
    }
}

fn operational_summary(state: &str, reasons: Vec<OperationalReason>) -> OperationalSummary {
    let changed_at = reasons.first().and_then(|reason| reason.started_at.clone());
    OperationalSummary {
        state: state.to_string(),
        primary_reason: reasons.first().cloned(),
        additional_reason_count: reasons.len().saturating_sub(1),
        changed_at,
    }
}

fn unix_timestamp_rfc3339(value: i64) -> Option<String> {
    Utc.timestamp_opt(value, 0)
        .single()
        .map(|timestamp| timestamp.to_rfc3339())
}

fn share_model_health_failed(share: &ShareView) -> bool {
    let entries = match share.app_type.trim().to_ascii_lowercase().as_str() {
        "claude" => &share.model_health.claude,
        "codex" => &share.model_health.codex,
        "gemini" => &share.model_health.gemini,
        _ => return false,
    };
    !entries.is_empty()
        && entries.iter().all(|entry| {
            let recent = entry
                .recent_results
                .iter()
                .rev()
                .take(3)
                .collect::<Vec<_>>();
            (!recent.is_empty() && recent.iter().all(|result| result.as_str() == "failed"))
                || matches!(entry.status.as_str(), "failed" | "unavailable" | "blocked")
        })
}

fn representative_recent_latency(
    requests: &[ShareRequestLogEntry],
) -> Option<(u64, Option<String>)> {
    let mut samples = requests
        .iter()
        .filter(|request| !request.is_health_check && request.status_code < 400)
        .filter_map(|request| {
            let latency = if request.is_streaming {
                request.first_token_ms
            } else {
                Some(request.latency_ms)
            }?;
            (latency > 0).then_some((latency, request.created_at))
        })
        .take(10)
        .collect::<Vec<_>>();
    if samples.len() < DASHBOARD_LATENCY_MIN_SAMPLES {
        return None;
    }
    let latest_at = samples
        .iter()
        .map(|(_, created_at)| *created_at)
        .max()
        .and_then(unix_timestamp_rfc3339);
    samples.sort_unstable_by_key(|(latency, _)| *latency);
    let middle = samples.len() / 2;
    let median = if samples.len() % 2 == 0 {
        ((samples[middle - 1].0 as u128 + samples[middle].0 as u128) / 2) as u64
    } else {
        samples[middle].0
    };
    Some((median, latest_at))
}

fn share_operational_summary(share: &ShareView, now: DateTime<Utc>) -> OperationalSummary {
    let status = share.share_status.trim().to_ascii_lowercase();
    if status != "active" {
        let (code, severity) = if status == "expired" {
            ("expired", "critical")
        } else {
            ("manually_disabled", "info")
        };
        return operational_summary(
            "disabled",
            vec![operational_reason(
                code,
                severity,
                (status == "expired").then(|| share.expires_at.clone()),
                Some("share"),
                Some(&share.share_id),
                Some(status),
                None,
            )],
        );
    }

    if share.route_state == "reconnecting" {
        return operational_summary(
            "reconnecting",
            vec![operational_reason(
                "route_reconnecting",
                "info",
                share.route_state_since.clone(),
                Some("share"),
                Some(&share.share_id),
                None,
                None,
            )],
        );
    }

    let mut reasons = Vec::new();
    if share.route_state == "offline" {
        reasons.push(operational_reason(
            "route_offline",
            "critical",
            None,
            Some("share"),
            Some(&share.share_id),
            None,
            None,
        ));
    }
    if let Some(edit) = &share.active_edit {
        if edit.status == "rejected" {
            reasons.push(operational_reason(
                "edit_failed",
                "critical",
                Some(edit.updated_at.to_rfc3339()),
                Some("share"),
                Some(&share.share_id),
                edit.error_message.clone(),
                None,
            ));
        } else if edit.status == "pending" {
            reasons.push(operational_reason(
                "edit_pending",
                "warning",
                Some(edit.updated_at.to_rfc3339()),
                Some("share"),
                Some(&share.share_id),
                None,
                None,
            ));
        }
    }

    if let Ok(expires_at) = DateTime::parse_from_rfc3339(&share.expires_at) {
        let remaining = expires_at.with_timezone(&Utc) - now;
        if expires_at.year() < 2099 {
            if remaining.num_seconds() <= 0 {
                reasons.push(operational_reason(
                    "expired",
                    "critical",
                    Some(share.expires_at.clone()),
                    Some("share"),
                    Some(&share.share_id),
                    Some("0".to_string()),
                    None,
                ));
            } else if remaining <= Duration::days(DASHBOARD_EXPIRY_WARNING_DAYS) {
                reasons.push(operational_reason(
                    "expires_soon",
                    "warning",
                    Some(
                        (expires_at.with_timezone(&Utc)
                            - Duration::days(DASHBOARD_EXPIRY_WARNING_DAYS))
                        .to_rfc3339(),
                    ),
                    Some("share"),
                    Some(&share.share_id),
                    Some(remaining.num_seconds().to_string()),
                    Some((Duration::days(DASHBOARD_EXPIRY_WARNING_DAYS).num_seconds()).to_string()),
                ));
            }
        }
    }

    if share_model_health_failed(share) {
        let checked_at = share
            .recent_model_health_checks
            .iter()
            .map(|entry| entry.checked_at)
            .max()
            .and_then(unix_timestamp_rfc3339);
        reasons.push(operational_reason(
            "provider_unavailable",
            "critical",
            checked_at,
            Some("provider"),
            share.provider_id.as_deref(),
            None,
            None,
        ));
    }

    let app_key = share.app_type.trim().to_ascii_lowercase();
    let parallel_limit = share.parallel_limit;
    let token_limit = share.token_limit;
    let active_requests = share
        .active_requests_by_app
        .get(&app_key)
        .copied()
        .unwrap_or(share.active_requests);
    let tokens_used = share
        .tokens_used_by_app
        .get(&app_key)
        .copied()
        .unwrap_or(share.tokens_used);
    if parallel_limit > 0 && active_requests as i64 >= parallel_limit {
        reasons.push(operational_reason(
            "parallel_capacity_full",
            "critical",
            None,
            Some("share"),
            Some(&share.share_id),
            Some(active_requests.to_string()),
            Some(parallel_limit.to_string()),
        ));
    }
    if token_limit > 0
        && tokens_used >= 0
        && tokens_used as f64 / token_limit as f64 >= DASHBOARD_CAPACITY_WARNING_RATIO
    {
        reasons.push(operational_reason(
            "usage_limit_warning",
            "warning",
            None,
            Some("share"),
            Some(&share.share_id),
            Some(tokens_used.to_string()),
            Some(token_limit.to_string()),
        ));
    }
    if let Some(health) = share.health_checks.last().filter(|entry| !entry.is_healthy) {
        reasons.push(operational_reason(
            "health_check_failed",
            "warning",
            unix_timestamp_rfc3339(health.checked_at),
            Some("share"),
            Some(&share.share_id),
            None,
            None,
        ));
    }
    if let Some((latency, latest_at)) = representative_recent_latency(&share.recent_requests) {
        if latency >= DASHBOARD_HIGH_LATENCY_MS {
            reasons.push(operational_reason(
                "high_latency",
                "warning",
                latest_at,
                Some("share"),
                Some(&share.share_id),
                Some(latency.to_string()),
                Some(DASHBOARD_HIGH_LATENCY_MS.to_string()),
            ));
        } else if latency >= DASHBOARD_MEDIUM_LATENCY_MS {
            reasons.push(operational_reason(
                "medium_latency",
                "warning",
                latest_at,
                Some("share"),
                Some(&share.share_id),
                Some(latency.to_string()),
                Some(DASHBOARD_MEDIUM_LATENCY_MS.to_string()),
            ));
        }
    }

    if !share.is_online {
        operational_summary("offline", reasons)
    } else if reasons.is_empty() {
        OperationalSummary::healthy("online")
    } else {
        operational_summary("degraded", reasons)
    }
}

fn client_operational_summary(client: &DashboardClientView) -> OperationalSummary {
    if let Some(tunnel) = client
        .client_tunnel
        .as_ref()
        .filter(|tunnel| tunnel.enabled && tunnel.route_state == "reconnecting")
    {
        return operational_summary(
            "reconnecting",
            vec![operational_reason(
                "route_reconnecting",
                "info",
                tunnel.route_state_since.clone(),
                Some("client"),
                Some(&client.installation.id),
                None,
                None,
            )],
        );
    }
    let mut reasons = Vec::new();
    let tunnel_offline = client
        .client_tunnel
        .as_ref()
        .is_none_or(|tunnel| !tunnel.enabled || !tunnel.online);

    if tunnel_offline {
        reasons.push(operational_reason(
            "route_offline",
            "critical",
            None,
            Some("client"),
            Some(&client.installation.id),
            None,
            None,
        ));
    }

    if let Some(health) = client
        .health_checks
        .last()
        .filter(|entry| !entry.is_healthy)
    {
        reasons.push(operational_reason(
            "health_check_failed",
            "warning",
            unix_timestamp_rfc3339(health.checked_at),
            Some("client"),
            Some(&client.installation.id),
            None,
            None,
        ));
    }

    if reasons
        .first()
        .is_some_and(|reason| reason.severity == "critical" && reason.code == "route_offline")
    {
        operational_summary("offline", reasons)
    } else if reasons.is_empty() {
        OperationalSummary::healthy("online")
    } else {
        operational_summary("degraded", reasons)
    }
}

