#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NotificationLane {
    Offline,
    Registration,
}

impl NotificationLane {
    const ORDERED: [Self; 2] = [Self::Offline, Self::Registration];

    fn as_str(self) -> &'static str {
        match self {
            Self::Offline => "offline",
            Self::Registration => "registration",
        }
    }

    fn from_db(value: &str) -> Result<Self, AppError> {
        match value {
            "offline" => Ok(Self::Offline),
            "registration" => Ok(Self::Registration),
            _ => Err(AppError::Internal(format!(
                "invalid notification lane stored in database: {value}"
            ))),
        }
    }

    fn event_sql_predicate(self) -> &'static str {
        match self {
            Self::Offline => "e.kind = 'client_offline'",
            Self::Registration => "e.kind IN ('client_registered', 'client_registration_overflow')",
        }
    }

    fn storm_event_kind(self) -> &'static str {
        match self {
            Self::Offline => "client_offline",
            Self::Registration => "client_registered",
        }
    }

    /// Whether a lane may leave the mailbox.
    ///
    /// Registration mail carries the Client's setup password hint — a
    /// credential the account owner proved control of by verifying the address.
    /// A Telegram chat is bound with a deep link, which is a weaker proof, so
    /// the hint never leaves email. Everything the offline lane says is already
    /// visible on the dashboard to anyone holding the session.
    fn allows_telegram(self) -> bool {
        match self {
            Self::Offline => true,
            Self::Registration => false,
        }
    }
}

