    async fn request_email_code_for_source(
        &self,
        config: &Config,
        resend: Option<&Resend>,
        raw_email: &str,
        source_kind: &str,
        source_id: &str,
        timestamp_ms: i64,
        nonce: &str,
        signature: &str,
        metadata: ClientMetadata,
    ) -> Result<RequestEmailCodeResponse, AppError> {
        let email = normalize_email(raw_email)?;
        let send_lock = self
            .auth_email_send_lock(&email, &format!("{source_kind}:{source_id}"))
            .await;
        let _send_guard = send_lock.lock().await;
        let request_at = Utc::now();
        {
            let conn = self.conn.lock().await;
            let public_key = auth_source_public_key(&conn, source_kind, source_id)?;
            verify_signed_payload(
                &public_key,
                source_id,
                "auth_request_code",
                &serde_json::json!({ "email": email, "purpose": AUTH_PURPOSE_LOGIN }),
                timestamp_ms,
                nonce,
                signature,
            )?;
            consume_auth_source_nonce(&conn, source_kind, source_id, nonce, request_at)?;
            enforce_auth_send_limits(
                &conn,
                config,
                &email,
                source_kind,
                source_id,
                &metadata,
                request_at,
            )?;
        }

        let code = generate_numeric_code(AUTH_CODE_DIGITS);
        let resend = resend.ok_or_else(|| AppError::Internal("resend is not configured".into()))?;
        let provider_message_id =
            send_login_code_email(resend, config, &email, &code, config.auth_code_ttl_secs).await?;

        let issued_at = Utc::now();
        let code_hash = hash_token(&format!("{email}:{code}"));
        let mut conn = self.conn.lock().await;
        persist_sent_login_challenge(
            &mut conn,
            config,
            &email,
            source_kind,
            source_id,
            &code_hash,
            provider_message_id.as_deref(),
            &metadata,
            issued_at,
        )?;

        Ok(RequestEmailCodeResponse {
            ok: true,
            cooldown_secs: config.auth_code_cooldown_secs,
            masked_destination: mask_email(&email),
        })
    }

    async fn auth_email_send_lock(&self, email: &str, source: &str) -> Arc<Mutex<()>> {
        let key = (email.to_string(), source.to_string());
        let mut locks = self.auth_email_send_locks.lock().await;
        locks.retain(|_, lock| lock.strong_count() > 0);
        if let Some(lock) = locks.get(&key).and_then(Weak::upgrade) {
            return lock;
        }
        let lock = Arc::new(Mutex::new(()));
        locks.insert(key, Arc::downgrade(&lock));
        lock
    }

