    async fn verify_email_code_for_source(
        &self,
        config: &Config,
        raw_email: &str,
        raw_code: &str,
        source_kind: &str,
        source_id: &str,
    ) -> Result<VerifyEmailCodeResponse, AppError> {
        let email = normalize_email(raw_email)?;
        let code = raw_code.trim();
        if code.len() != AUTH_CODE_DIGITS || !code.chars().all(|ch| ch.is_ascii_digit()) {
            log_email_verification_rejection(EmailVerificationRejectionReason::InvalidCode);
            return Err(AppError::Unauthorized("invalid verification code".into()));
        }

        let now = Utc::now();
        let conn = self.conn.lock().await;
        let tx = conn
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .map_err(|e| AppError::Internal(format!("begin email verification failed: {e}")))?;
        if auth_source_public_key(&tx, source_kind, source_id).is_err() {
            log_email_verification_rejection(EmailVerificationRejectionReason::NotFound);
            return Err(AppError::Unauthorized(
                "authentication source not found".into(),
            ));
        }

        let challenge = get_latest_active_email_challenge(
            &tx,
            &email,
            source_kind,
            source_id,
            AUTH_PURPOSE_LOGIN,
            now,
        )?;
        let Some(challenge) = challenge else {
            let reason = classify_missing_email_challenge(
                &tx,
                &email,
                source_kind,
                source_id,
                AUTH_PURPOSE_LOGIN,
                now,
            )?;
            log_email_verification_rejection(reason);
            return Err(AppError::Unauthorized(
                "verification code expired or not found".into(),
            ));
        };

        if challenge.attempt_count >= config.auth_max_verify_attempts {
            log_email_verification_rejection(EmailVerificationRejectionReason::AttemptLimit);
            return Err(AppError::TooManyRequests(
                "too many invalid verification attempts".into(),
            ));
        }

        let expected_hash = hash_token(&format!("{email}:{code}"));
        if expected_hash != challenge.code_hash {
            tx.execute(
                "UPDATE email_login_challenges
                 SET attempt_count = attempt_count + 1
                 WHERE id = ?1",
                params![challenge.id],
            )
            .map_err(|e| AppError::Internal(format!("update auth attempts failed: {e}")))?;
            tx.commit().map_err(|e| {
                AppError::Internal(format!("commit auth attempt update failed: {e}"))
            })?;
            log_email_verification_rejection(EmailVerificationRejectionReason::InvalidCode);
            return Err(AppError::Unauthorized("invalid verification code".into()));
        }

        let consumed = tx
            .execute(
                "UPDATE email_login_challenges
             SET consumed_at = ?2
             WHERE id = ?1 AND consumed_at IS NULL AND expires_at >= ?2",
                params![challenge.id, now.to_rfc3339()],
            )
            .map_err(|e| AppError::Internal(format!("consume auth challenge failed: {e}")))?;
        if consumed != 1 {
            let reason = classify_missing_email_challenge(
                &tx,
                &email,
                source_kind,
                source_id,
                AUTH_PURPOSE_LOGIN,
                now,
            )?;
            log_email_verification_rejection(reason);
            return Err(AppError::Unauthorized(
                "verification code expired or not found".into(),
            ));
        }

        let user = upsert_user_by_email(&tx, &email, now)?;
        let access_token = generate_secret(48);
        let refresh_token = generate_secret(64);
        let access_expires_at = now + Duration::seconds(config.auth_session_ttl_secs);
        let refresh_expires_at = now + Duration::seconds(config.auth_refresh_ttl_secs);
        let session = AuthSession {
            session_id: Uuid::new_v4().to_string(),
            user_id: user.id.clone(),
            email: user.email.clone(),
            auth_source_kind: source_kind.to_string(),
            auth_source_id: source_id.to_string(),
            access_token_hash: hash_token(&access_token),
            refresh_token_hash: hash_token(&refresh_token),
            access_expires_at,
            refresh_expires_at,
            created_at: now,
            last_used_at: now,
        };
        persist_session(&tx, &session)?;
        let (api_token, api_token_status) = ensure_default_user_api_token(&tx, &user.id, now)?;
        tx.commit()
            .map_err(|e| AppError::Internal(format!("commit email verification failed: {e}")))?;

        Ok(VerifyEmailCodeResponse {
            user,
            access_token,
            refresh_token,
            expires_at: access_expires_at,
            refresh_expires_at,
            api_token,
            api_token_prefix: Some(api_token_status.prefix),
        })
    }

    pub async fn refresh_session(
        &self,
        config: &Config,
        input: RefreshSessionRequest,
    ) -> Result<VerifyEmailCodeResponse, AppError> {
        let now = Utc::now();
        let refresh_hash = hash_token(input.refresh_token.trim());
        let conn = self.conn.lock().await;
        let tx = conn
            .unchecked_transaction()
            .map_err(|e| AppError::Internal(format!("begin refresh session failed: {e}")))?;
        let current = get_refreshable_session_by_refresh_hash(&tx, &refresh_hash, now)?
            .ok_or_else(|| AppError::Unauthorized("refresh session not found".into()))?;
        if current.refresh_expires_at < now {
            return Err(AppError::Unauthorized("refresh session expired".into()));
        }
        let user = get_user_by_id(&tx, &current.user_id)?
            .ok_or_else(|| AppError::Unauthorized("user not found".into()))?;
        let access_token = generate_secret(48);
        let refresh_token = generate_secret(64);
        let access_expires_at = now + Duration::seconds(config.auth_session_ttl_secs);
        let refresh_expires_at = now + Duration::seconds(config.auth_refresh_ttl_secs);
        let rotated = tx
            .execute(
                "UPDATE user_sessions
             SET revoked_at = COALESCE(revoked_at, ?2),
                 rotated_at = COALESCE(rotated_at, ?2),
                 last_used_at = ?2
             WHERE id = ?1
               AND (revoked_at IS NULL OR rotated_at >= ?3)",
                params![
                    current.session_id,
                    now.to_rfc3339(),
                    (now - Duration::seconds(SESSION_REFRESH_ROTATION_GRACE_SECS)).to_rfc3339(),
                ],
            )
            .map_err(|e| AppError::Internal(format!("refresh session failed: {e}")))?;
        if rotated != 1 {
            return Err(AppError::Unauthorized(
                "refresh session already rotated".into(),
            ));
        }

        let replacement = AuthSession {
            session_id: Uuid::new_v4().to_string(),
            user_id: current.user_id.clone(),
            email: user.email.clone(),
            auth_source_kind: current.auth_source_kind,
            auth_source_id: current.auth_source_id,
            access_token_hash: hash_token(&access_token),
            refresh_token_hash: hash_token(&refresh_token),
            access_expires_at,
            refresh_expires_at,
            created_at: now,
            last_used_at: now,
        };
        persist_session(&tx, &replacement)?;
        tx.commit()
            .map_err(|e| AppError::Internal(format!("commit refresh session failed: {e}")))?;

        Ok(VerifyEmailCodeResponse {
            user,
            access_token,
            refresh_token,
            expires_at: access_expires_at,
            refresh_expires_at,
            api_token: None,
            api_token_prefix: get_default_user_api_token(&conn, &current.user_id)?
                .map(|token| token.prefix),
        })
    }

    pub async fn session_status(
        &self,
        access_token: Option<&str>,
    ) -> Result<SessionStatusResponse, AppError> {
        let Some(access_token) = access_token.map(str::trim).filter(|v| !v.is_empty()) else {
            return Ok(SessionStatusResponse {
                authenticated: false,
                user: None,
                expires_at: None,
                is_admin: false,
            });
        };

        let session = self
            .resolve_session_by_access_token(access_token)
            .await?
            .ok_or_else(|| AppError::Unauthorized("session not found".into()))?;
        Ok(SessionStatusResponse {
            authenticated: true,
            user: Some(AuthUser {
                id: session.user_id,
                email: session.email,
            }),
            expires_at: Some(session.access_expires_at),
            is_admin: false,
        })
    }

    pub async fn revoke_session_by_access_token(&self, access_token: &str) -> Result<(), AppError> {
        let access_token = access_token.trim();
        if access_token.is_empty() {
            return Ok(());
        }
        let now = Utc::now();
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE user_sessions
             SET revoked_at = ?2,
                 last_used_at = ?2
             WHERE access_token_hash = ?1 AND revoked_at IS NULL",
            params![hash_token(access_token), now.to_rfc3339()],
        )
        .map_err(|e| AppError::Internal(format!("revoke session failed: {e}")))?;
        Ok(())
    }

