    pub async fn prune_image_generation_request_logs_for_share(
        &self,
        share_id: &str,
        keep: usize,
    ) -> Result<Vec<String>, AppError> {
        let conn = self.conn.lock().await;
        let stale = {
            let mut stmt = conn
                .prepare(
                    "SELECT request_id, result_storage_key
                     FROM image_generation_request_logs
                     WHERE share_id = ?1
                     ORDER BY created_at DESC, request_id DESC
                     LIMIT -1 OFFSET ?2",
                )
                .map_err(|e| {
                    AppError::Internal(format!("prepare stale image request logs failed: {e}"))
                })?;
            let rows = stmt
                .query_map(params![share_id, keep as i64], |row| {
                    Ok((row.get::<_, String>(0)?, row.get::<_, Option<String>>(1)?))
                })
                .map_err(|e| {
                    AppError::Internal(format!("query stale image request logs failed: {e}"))
                })?;
            collect_rows(rows)?
        };
        if stale.is_empty() {
            return Ok(Vec::new());
        }
        let request_ids = stale
            .iter()
            .map(|(request_id, _)| request_id.clone())
            .collect::<Vec<_>>();
        let placeholders = repeat_vars(request_ids.len());
        conn.execute(
            &format!(
                "DELETE FROM image_generation_request_logs WHERE request_id IN ({placeholders})"
            ),
            params_from_iter(request_ids.iter()),
        )
        .map_err(|e| AppError::Internal(format!("delete stale image request logs failed: {e}")))?;
        Ok(stale
            .into_iter()
            .filter_map(|(_, storage_key)| storage_key)
            .collect())
    }

    pub async fn list_user_shares(
        &self,
        config: &Config,
        current_user_email: &str,
        active_subdomains: &HashSet<String>,
        inflight_by_share: &HashMap<String, usize>,
    ) -> Result<UserSharesResponse, AppError> {
        let email = normalize_email(current_user_email)?;
        let conn = self.conn.lock().await;
        let active_edits = list_active_share_edits(&conn)?;
        let mut shares = Vec::new();
        for (_, share) in list_shares(&conn)? {
            let owner = share
                .owner_email
                .as_deref()
                .is_some_and(|owner| owner.eq_ignore_ascii_case(&email));
            let shared = !owner && share_visible_to_email(&share, Some(&email));
            if !owner && !shared {
                continue;
            }
            let role = if owner { "owner" } else { "shared" }.to_string();
            let active_requests = inflight_by_share
                .get(&share.share_id)
                .copied()
                .unwrap_or_default();
            let user_grants = if owner {
                share.user_grants.clone()
            } else {
                share
                    .user_grants
                    .get(&email)
                    .map(|grant| BTreeMap::from([(email.clone(), grant.clone())]))
                    .unwrap_or_default()
            };
            shares.push(UserShareView {
                router_id: "main".to_string(),
                share_id: share.share_id.clone(),
                share_name: share.share_name.clone(),
                owner_email: share.owner_email.clone(),
                role,
                can_invoke: true,
                can_manage: owner,
                description: share.description.clone(),
                free_access: share.free_access,
                subdomain: share.subdomain.clone(),
                tunnel_url: config.tunnel_url(&share.subdomain),
                app_type: share.app_type.clone(),
                provider_id: share.provider_id.clone(),
                token_limit: share.token_limit,
                parallel_limit: share.parallel_limit,
                tokens_used: share.tokens_used,
                requests_count: share.requests_count,
                share_status: share.share_status.clone(),
                created_at: share.created_at.clone(),
                expires_at: share.expires_at.clone(),
                is_online: active_subdomains.contains(&share.subdomain),
                active_requests,
                active_edit: owner
                    .then(|| active_edits.get(&share.share_id).cloned())
                    .flatten(),
                user_grants,
                supported_user_token_periods: share.supported_user_token_periods.clone(),
                config_revision: share.config_revision,
            });
        }
        Ok(UserSharesResponse { shares })
    }

    pub async fn share_view_for_share_url(
        &self,
        share_id: &str,
        active_subdomains: &HashSet<String>,
        inflight_by_share: &HashMap<String, usize>,
        viewer_email: Option<&str>,
    ) -> Result<ShareView, AppError> {
        let conn = self.conn.lock().await;
        let (_, share) = list_shares(&conn)?
            .into_iter()
            .find(|(_, share)| share.share_id == share_id)
            .ok_or_else(|| AppError::NotFound("share not found".into()))?;
        let active_edit = get_active_share_edit(&conn, share_id)?;
        let can_manage = can_manage_share(&share, viewer_email);
        let can_edit_settings = can_manage
            && active_edit
                .as_ref()
                .map(|edit| edit.status != "pending")
                .unwrap_or(true);
        let is_online =
            share.share_status == "active" && active_subdomains.contains(&share.subdomain);
        let active_requests = inflight_by_share.get(&share.share_id).copied().unwrap_or(0);
        let visible_user_grants = if can_manage {
            share.user_grants.clone()
        } else {
            viewer_email
                .and_then(|email| normalize_email(email).ok())
                .and_then(|email| {
                    share
                        .user_grants
                        .get(&email)
                        .map(|grant| BTreeMap::from([(email, grant.clone())]))
                })
                .unwrap_or_default()
        };
        let (tokens_used_by_app, requests_count_by_app) = authoritative_share_usage_by_app(&share);
        let mut view = ShareView {
            router_id: "main".to_string(),
            share_id: share.share_id,
            capacity_pool_id: share.capacity_pool_id,
            share_name: share.share_name,
            owner_email: share.owner_email,
            description: share.description,
            free_access: share.free_access,
            subdomain: share.subdomain,
            can_view_secret: false,
            can_manage,
            can_edit_settings,
            active_edit: can_manage.then_some(active_edit).flatten(),
            app_type: share.app_type,
            provider_id: share.provider_id,
            bindings: share.bindings,
            token_limit: share.token_limit,
            parallel_limit: share.parallel_limit,
            tokens_used: share.tokens_used,
            requests_count: share.requests_count,
            share_status: share.share_status,
            created_at: share.created_at,
            expires_at: share.expires_at,
            support: share.support,
            upstream_provider: None,
            app_runtimes: share.app_runtimes,
            app_providers: share.app_providers,
            installation_id: String::new(),
            is_online,
            route_state: if is_online { "active" } else { "offline" }.to_string(),
            route_state_since: None,
            cleanup_at: None,
            active_requests,
            active_requests_by_app: BTreeMap::new(),
            active_requests_by_user: BTreeMap::new(),
            tokens_used_by_app,
            requests_count_by_app,
            online_minutes_24h: 0,
            online_rate_24h: 0.0,
            observed_minutes_24h: 0,
            observation_coverage_24h: 0.0,
            recent_requests: Vec::new(),
            health_checks: Vec::new(),
            health_timeline: Vec::new(),
            recent_model_health_checks: Vec::new(),
            model_health: ShareModelHealthSummary::default(),
            operational_summary: OperationalSummary::healthy("online"),
            user_grants: visible_user_grants,
            supported_user_token_periods: share.supported_user_token_periods,
            config_revision: share.config_revision,
            auto_start: share.auto_start,
            allow_personal_credits: share.allow_personal_credits,
            auto_consume_banked_reset: share.auto_consume_banked_reset,
            banked_reset_expiry_lead_minutes: share.banked_reset_expiry_lead_minutes,
            previous_response_cache_enabled: share.previous_response_cache_enabled,
        };
        view.operational_summary = share_operational_summary(&view, Utc::now());
        Ok(view)
    }

    pub async fn user_can_invoke_share(
        &self,
        user_email: &str,
        share_id: &str,
        app_type: Option<&str>,
    ) -> Result<bool, AppError> {
        let email = normalize_email(user_email)?;
        let Some(app_type) = app_type else {
            return Ok(false);
        };
        let app_type = normalize_share_app(app_type)?;
        let conn = self.conn.lock().await;
        let Some((
            owner_email,
            user_grants_json,
            free_access,
            enabled_claude,
            enabled_codex,
            enabled_gemini,
        )): Option<(
            Option<String>,
            String,
            bool,
            i64,
            i64,
            i64,
        )> = conn
            .query_row(
                "SELECT owner_email, COALESCE(user_grants_json, '{}'), COALESCE(free_access, 0),
                        COALESCE(enabled_claude, 0), COALESCE(enabled_codex, 0), COALESCE(enabled_gemini, 0)
                 FROM shares
                 WHERE share_id = ?1
                   AND EXISTS (
                       SELECT 1 FROM share_bindings
                       WHERE share_id = ?1 AND app_type = ?2
                   )",
                params![share_id, app_type],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get::<_, i64>(2)? != 0,
                        row.get::<_, i64>(3)?,
                        row.get::<_, i64>(4)?,
                        row.get::<_, i64>(5)?,
                    ))
                },
            )
            .optional()
            .map_err(|e| AppError::Internal(format!("query share invoke acl failed: {e}")))?
        else {
            return Ok(false);
        };
        let app_enabled = match app_type.as_str() {
            "claude" => enabled_claude != 0,
            "codex" => enabled_codex != 0,
            "gemini" => enabled_gemini != 0,
            _ => false,
        };
        if !app_enabled {
            return Ok(false);
        }
        if free_access {
            return Ok(true);
        }
        if owner_email
            .as_deref()
            .is_some_and(|owner| owner.eq_ignore_ascii_case(&email))
        {
            return Ok(true);
        }
        let user_grants: BTreeMap<String, ShareUserGrant> = serde_json::from_str(&user_grants_json)
            .map_err(|error| {
                AppError::Internal(format!("parse canonical Share user grants failed: {error}"))
            })?;
        Ok(user_grants.iter().any(|(key, grant)| {
            grant.active
                && grant.role == "shareto"
                && (key.eq_ignore_ascii_case(&email) || grant.email.eq_ignore_ascii_case(&email))
        }))
    }

    pub async fn share_usage_by_email(
        &self,
        share_id: &str,
        period: &str,
    ) -> Result<ShareUsageByEmailResponse, AppError> {
        let window = normalize_usage_period(period)?;
        let period = window.period.clone();
        let bucket_granularity = window.bucket_granularity.clone();
        let days = window.days;
        let conn = self.conn.lock().await;
        let Some((owner_email, user_grants_json)): Option<(Option<String>, String)> = conn
            .query_row(
                "SELECT owner_email, COALESCE(user_grants_json, '{}')
                 FROM shares
                 WHERE share_id = ?1",
                params![share_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()
            .map_err(|e| AppError::Internal(format!("query share usage acl failed: {e}")))?
        else {
            return Err(AppError::NotFound("share not found".into()));
        };

        let user_grants = parse_share_user_grants(Some(user_grants_json))
            .map_err(|e| AppError::Internal(format!("parse share usage grants failed: {e}")))?;
        let deprecated_shareto_emails = user_grants
            .iter()
            .filter_map(|(key, grant)| {
                if grant.active || !grant.role.eq_ignore_ascii_case("shareto") {
                    return None;
                }
                let email = if grant.email.trim().is_empty() {
                    key.as_str()
                } else {
                    grant.email.as_str()
                };
                normalize_usage_email(email)
            })
            .collect::<HashSet<_>>();

        let mut roles = BTreeMap::<String, String>::new();
        if let Some(owner) = owner_email.as_deref().and_then(normalize_usage_email) {
            roles.insert(owner, "owner".to_string());
        }
        let shareto_emails = user_grants.iter().filter_map(|(key, grant)| {
            if !grant.active || !grant.role.eq_ignore_ascii_case("shareto") {
                return None;
            }
            Some(if grant.email.trim().is_empty() {
                key.clone()
            } else {
                grant.email.clone()
            })
        });
        for email in shareto_emails {
            if let Some(email) = normalize_usage_email(&email) {
                roles.entry(email).or_insert_with(|| "shareto".to_string());
            }
        }

        let start_dt = window.start_at;
        let start_ts = start_dt.timestamp();
        let start_rfc3339 = start_dt.to_rfc3339();
        let bucket_keys = window.bucket_keys;
        let make_usage_row = |email: &str, role: &str| ShareUsageEmailRow {
            email: email.to_string(),
            role: role.to_string(),
            input_tokens: 0,
            output_tokens: 0,
            cache_read_tokens: 0,
            cache_creation_tokens: 0,
            total_tokens: 0,
            percent: 0.0,
            daily: bucket_keys
                .iter()
                .map(|bucket| ShareUsageDailyBucket {
                    date: bucket.clone(),
                    input_tokens: 0,
                    output_tokens: 0,
                    cache_read_tokens: 0,
                    cache_creation_tokens: 0,
                    total_tokens: 0,
                })
                .collect(),
        };
        let unlisted_usage_role = |email: &str| {
            if deprecated_shareto_emails.contains(email) {
                "deprecated"
            } else {
                "gateway"
            }
        };
        let mut rows_by_email = roles
            .iter()
            .map(|(email, role)| (email.clone(), make_usage_row(email, role)))
            .collect::<BTreeMap<_, _>>();
        let bucket_index = bucket_keys
            .iter()
            .enumerate()
            .map(|(idx, bucket)| (bucket.clone(), idx))
            .collect::<BTreeMap<_, _>>();

        let capacity_bucket_expr = if bucket_granularity == "hour" {
            "strftime('%Y-%m-%dT%H:00:00Z', ml.created_at)"
        } else {
            "date(ml.created_at)"
        };
        let capacity_input_expr = capacity_log_input_tokens_expr("ml");
        let capacity_total_expr = capacity_log_total_tokens_expr("ml");
        let capacity_usage_sql = format!(
            "SELECT lower(trim(ml.user_email)),
                    {capacity_bucket_expr} AS usage_bucket,
                    COALESCE(SUM(CASE WHEN ({capacity_total_expr}) > 0 OR sl.request_id IS NULL THEN {capacity_input_expr} ELSE COALESCE(sl.input_tokens, 0) END), 0),
                    COALESCE(SUM(CASE WHEN ({capacity_total_expr}) > 0 OR sl.request_id IS NULL THEN COALESCE(ml.output_tokens, 0) ELSE COALESCE(sl.output_tokens, 0) END), 0),
                    COALESCE(SUM(CASE WHEN ({capacity_total_expr}) > 0 OR sl.request_id IS NULL THEN COALESCE(ml.cache_read_tokens, 0) ELSE COALESCE(sl.cache_read_tokens, 0) END), 0),
                    COALESCE(SUM(CASE WHEN ({capacity_total_expr}) > 0 OR sl.request_id IS NULL THEN COALESCE(ml.cache_creation_tokens, 0) ELSE COALESCE(sl.cache_creation_tokens, 0) END), 0)
             FROM capacity_request_observations ml
             LEFT JOIN share_request_logs sl
               ON sl.request_id = ml.request_id
              AND sl.share_id = ml.share_id
              AND sl.is_health_check = 0
              AND lower(CASE WHEN COALESCE(sl.request_agent, '') != '' THEN sl.request_agent ELSE sl.app_type END) = lower(ml.request_agent)
             WHERE ml.share_id = ?1
               AND ml.created_at >= ?2
               AND ml.user_email IS NOT NULL
               AND trim(ml.user_email) != ''
             GROUP BY lower(trim(ml.user_email)), usage_bucket"
        );
        let mut capacity_stmt = conn.prepare(&capacity_usage_sql).map_err(|e| {
            AppError::Internal(format!("prepare capacity share usage query failed: {e}"))
        })?;
        let capacity_rows = capacity_stmt
            .query_map(params![share_id, start_rfc3339], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, i64>(2)?.max(0) as u64,
                    row.get::<_, i64>(3)?.max(0) as u64,
                    row.get::<_, i64>(4)?.max(0) as u64,
                    row.get::<_, i64>(5)?.max(0) as u64,
                ))
            })
            .map_err(|e| AppError::Internal(format!("query capacity share usage failed: {e}")))?;
        for row in capacity_rows {
            let (email, bucket, input, output, cache_read, cache_creation) = row.map_err(|e| {
                AppError::Internal(format!("read capacity share usage row failed: {e}"))
            })?;
            let role = unlisted_usage_role(&email);
            rows_by_email
                .entry(email.clone())
                .or_insert_with(|| make_usage_row(&email, role));
            let Some(row) = rows_by_email.get_mut(&email) else {
                continue;
            };
            let total = input + output + cache_read + cache_creation;
            row.input_tokens += input;
            row.output_tokens += output;
            row.cache_read_tokens += cache_read;
            row.cache_creation_tokens += cache_creation;
            row.total_tokens += total;
            if let Some(idx) = bucket_index.get(&bucket).copied() {
                if let Some(bucket) = row.daily.get_mut(idx) {
                    bucket.input_tokens += input;
                    bucket.output_tokens += output;
                    bucket.cache_read_tokens += cache_read;
                    bucket.cache_creation_tokens += cache_creation;
                    bucket.total_tokens += total;
                }
            }
        }

        let share_bucket_expr = if bucket_granularity == "hour" {
            "strftime('%Y-%m-%dT%H:00:00Z', created_at, 'unixepoch')"
        } else {
            "date(created_at, 'unixepoch')"
        };
        let share_usage_sql = format!(
            "SELECT lower(trim(user_email)),
                    {share_bucket_expr} AS usage_bucket,
                    COALESCE(SUM(input_tokens), 0),
                    COALESCE(SUM(output_tokens), 0),
                    COALESCE(SUM(cache_read_tokens), 0),
                    COALESCE(SUM(cache_creation_tokens), 0)
             FROM share_request_logs
             WHERE share_id = ?1
               AND created_at >= ?2
               AND is_health_check = 0
               AND user_email IS NOT NULL
               AND trim(user_email) != ''
               AND NOT EXISTS (
                    SELECT 1
                    FROM capacity_request_observations ml
                    WHERE ml.request_id = share_request_logs.request_id
                      AND COALESCE(ml.share_id, '') = share_request_logs.share_id
               )
             GROUP BY lower(trim(user_email)), usage_bucket"
        );
        let mut stmt = conn
            .prepare(&share_usage_sql)
            .map_err(|e| AppError::Internal(format!("prepare share usage query failed: {e}")))?;
        let rows = stmt
            .query_map(params![share_id, start_ts], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, i64>(2)?.max(0) as u64,
                    row.get::<_, i64>(3)?.max(0) as u64,
                    row.get::<_, i64>(4)?.max(0) as u64,
                    row.get::<_, i64>(5)?.max(0) as u64,
                ))
            })
            .map_err(|e| AppError::Internal(format!("query share usage failed: {e}")))?;
        for row in rows {
            let (email, bucket, input, output, cache_read, cache_creation) =
                row.map_err(|e| AppError::Internal(format!("read share usage row failed: {e}")))?;
            let role = unlisted_usage_role(&email);
            rows_by_email
                .entry(email.clone())
                .or_insert_with(|| make_usage_row(&email, role));
            let Some(row) = rows_by_email.get_mut(&email) else {
                continue;
            };
            let total = input + output + cache_read + cache_creation;
            row.input_tokens += input;
            row.output_tokens += output;
            row.cache_read_tokens += cache_read;
            row.cache_creation_tokens += cache_creation;
            row.total_tokens += total;
            if let Some(idx) = bucket_index.get(&bucket).copied() {
                if let Some(bucket) = row.daily.get_mut(idx) {
                    bucket.input_tokens += input;
                    bucket.output_tokens += output;
                    bucket.cache_read_tokens += cache_read;
                    bucket.cache_creation_tokens += cache_creation;
                    bucket.total_tokens += total;
                }
            }
        }

        let total_tokens = rows_by_email
            .values()
            .map(|row| row.total_tokens)
            .sum::<u64>();
        let mut rows = rows_by_email.into_values().collect::<Vec<_>>();
        for row in &mut rows {
            row.percent = if total_tokens > 0 {
                (row.total_tokens as f64 / total_tokens as f64) * 100.0
            } else {
                0.0
            };
        }
        rows.sort_by(|a, b| {
            b.total_tokens
                .cmp(&a.total_tokens)
                .then_with(|| a.role.cmp(&b.role))
                .then_with(|| a.email.cmp(&b.email))
        });

        Ok(ShareUsageByEmailResponse {
            share_id: share_id.to_string(),
            period,
            bucket_granularity,
            days,
            total_tokens,
            rows,
        })
    }

    pub async fn share_user_limit_status(
        &self,
        share_id: &str,
    ) -> Result<ShareUserLimitStatusResponse, AppError> {
        let conn = self.conn.lock().await;
        let Some(user_grants_json): Option<String> = conn
            .query_row(
                "SELECT COALESCE(user_grants_json, '{}')
                 FROM shares
                 WHERE share_id = ?1",
                params![share_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|e| {
                AppError::Internal(format!("query share user limit status failed: {e}"))
            })?
        else {
            return Err(AppError::NotFound("share not found".into()));
        };

        let user_grants = parse_share_user_grants(Some(user_grants_json))
            .map_err(|e| AppError::Internal(format!("parse share user grants failed: {e}")))?;

        let mut grants: Vec<ShareUserGrant> = user_grants
            .into_values()
            .filter(|grant| grant.active)
            .collect();
        grants.sort_by(|left, right| {
            let left_owner = left.role.eq_ignore_ascii_case("owner");
            let right_owner = right.role.eq_ignore_ascii_case("owner");
            match (left_owner, right_owner) {
                (true, false) => Ordering::Less,
                (false, true) => Ordering::Greater,
                _ => left
                    .email
                    .to_ascii_lowercase()
                    .cmp(&right.email.to_ascii_lowercase()),
            }
        });

        let now = Utc::now();
        let mut grant_windows = Vec::with_capacity(grants.len());
        let mut unique_windows = BTreeMap::<String, UserQuotaWindow>::new();
        for grant in &grants {
            let (start, end) = token_period_window(&grant.policy, now)?;
            let key = quota_window_key(start, end);
            unique_windows
                .entry(key.clone())
                .or_insert(UserQuotaWindow {
                    key: key.clone(),
                    start,
                    end,
                });
            grant_windows.push((key, start, end));
        }
        let usage_by_window = query_share_email_token_totals_for_windows(
            &conn,
            share_id,
            &unique_windows.into_values().collect::<Vec<_>>(),
        )?;

        let rows = grants
            .into_iter()
            .zip(grant_windows)
            .map(|(grant, (window_key, window_start, resets_at))| {
                let email = normalize_usage_email(&grant.email)
                    .unwrap_or_else(|| grant.email.trim().to_ascii_lowercase());
                let period = grant.policy.token_period;
                let logged_tokens = usage_by_window
                    .get(&window_key)
                    .and_then(|map| map.get(&email))
                    .copied()
                    .unwrap_or(0);
                let tokens_used = effective_share_user_tokens(
                    &grant,
                    window_start.as_ref(),
                    logged_tokens,
                );
                let percent = grant
                    .policy
                    .token_limit
                    .filter(|limit| *limit > 0)
                    .map(|limit| ((tokens_used as f64 / limit as f64) * 100.0).clamp(0.0, 9999.0));
                ShareUserLimitStatusRow {
                    email: grant.email,
                    role: if grant.role.eq_ignore_ascii_case("owner") {
                        "owner".into()
                    } else {
                        "shareto".into()
                    },
                    parallel_limit: grant.policy.parallel_limit,
                    token_limit: grant.policy.token_limit,
                    token_period: period,
                    token_period_anchor_at_ms: grant.policy.token_period_anchor_at_ms,
                    expires_at: grant.policy.expires_at,
                    tokens_used,
                    window_starts_at: window_start.map(|ts| ts.to_rfc3339()),
                    percent,
                    resets_at: resets_at.map(|ts| ts.to_rfc3339()),
                }
            })
            .collect();

        Ok(ShareUserLimitStatusResponse {
            share_id: share_id.to_string(),
            rows,
        })
    }

    pub async fn issue_lease(
        &self,
        config: &Config,
        proxy: &ProxyRegistry,
        input: IssueLeaseRequest,
        metadata: ClientMetadata,
        _current_user_email: Option<&str>,
    ) -> Result<IssueLeaseResponse, AppError> {
        let now = Utc::now();
        ensure_tunnel_protocol_epoch(&input.protocol_epoch)?;
        ensure_tunnel_router_id(config, &input.router_id)?;
        let tunnel_type = input.tunnel_type.to_ascii_lowercase();
        let is_client_web_tunnel = tunnel_type == "client-web-http";
        if tunnel_type != "http" && !is_client_web_tunnel {
            return Err(AppError::BadRequest(
                "only http tunnels are supported".into(),
            ));
        }
        if is_client_web_tunnel && input.share.is_some() {
            return Err(AppError::BadRequest(
                "client web tunnels cannot include share metadata".into(),
            ));
        }

        let requested_subdomain = normalize_subdomain(&input.requested_subdomain)?;
        ensure_subdomain_allowed(&requested_subdomain)?;
        let route_id = validate_tunnel_route_id(&input.route_id)?;
        if Uuid::parse_str(input.rotation_id.trim()).is_err() {
            return Err(AppError::BadRequest("rotationId must be a UUID".into()));
        }
        if input.generation == 0 || input.generation <= input.expected_generation {
            return Err(AppError::BadRequest(
                "generation must be greater than expectedGeneration".into(),
            ));
        }
        let installation = {
            let conn = self.conn.lock().await;
            let installation = get_installation(&conn, &input.installation_id)?
                .ok_or_else(|| AppError::Unauthorized("installation not found".into()))?;
            verify_issue_lease_request(&conn, &installation.public_key, &input, now)?;
            let should_refresh_geo =
                should_refresh_installation_geo(&installation, metadata.ip.as_deref());
            touch_installation_activity(&conn, &input.installation_id, &metadata, now)?;
            (installation, should_refresh_geo)
        };
        if installation.1 {
            self.refresh_installation_geo(&input.installation_id, &metadata.ip, false)
                .await?;
        }
        let installation = installation.0;

        let subdomain = if let Some(share) = input.share.as_ref() {
            let conn = self.conn.lock().await;
            if get_client_tunnel_by_subdomain(&conn, &requested_subdomain)?.is_some() {
                return Err(AppError::Conflict(
                    "subdomain already claimed by client tunnel".into(),
                ));
            }
            let owned_subdomain =
                get_share_owned_subdomain(&conn, &input.installation_id, &share.share_id)?
                    .ok_or_else(|| AppError::Conflict("share subdomain is not claimed".into()))?;
            if owned_subdomain != requested_subdomain {
                return Err(AppError::Conflict(
                    "requested subdomain does not match claimed subdomain".into(),
                ));
            }
            owned_subdomain
        } else if is_client_web_tunnel {
            let conn = self.conn.lock().await;
            ensure_subdomain_not_claimed_by_share(&conn, &requested_subdomain)?;
            let tunnel = get_client_tunnel_by_installation(&conn, &input.installation_id)?
                .ok_or_else(|| AppError::Conflict("client tunnel is not claimed".into()))?;
            if !tunnel.enabled {
                return Err(AppError::Conflict("client tunnel is disabled".into()));
            }
            if tunnel.subdomain != requested_subdomain {
                return Err(AppError::Conflict(
                    "requested subdomain does not match claimed client tunnel".into(),
                ));
            }
            requested_subdomain
        } else {
            let conn = self.conn.lock().await;
            if get_client_tunnel_by_subdomain(&conn, &requested_subdomain)?.is_some() {
                return Err(AppError::Conflict(
                    "subdomain already claimed by client tunnel".into(),
                ));
            }
            requested_subdomain
        };
        {
            let conn = self.conn.lock().await;
            let host = crate::public_hosts::get_by_label(&conn, &subdomain)
                .map_err(map_public_host_error)?
                .ok_or_else(|| AppError::Conflict("public host is not claimed".into()))?;
            if host.lifecycle != crate::public_hosts::PublicHostLifecycle::Active {
                return Err(AppError::Conflict("public host is not active".into()));
            }
            if host.route_id != route_id {
                return Err(AppError::Conflict(
                    "public host belongs to another route".into(),
                ));
            }
            let identity_matches = if let Some(share) = input.share.as_ref() {
                host.kind == PublicHostKind::Share
                    && host.subject_id == share.share_id
                    && host.installation_id.as_deref() == Some(input.installation_id.as_str())
            } else {
                host.kind == PublicHostKind::Client
                    && host.subject_id == input.installation_id
                    && host.installation_id.as_deref() == Some(input.installation_id.as_str())
            };
            if !identity_matches {
                return Err(AppError::Conflict(
                    "public host identity does not match the lease".into(),
                ));
            }
        }
        let requested_share_id = input.share.as_ref().map(|share| share.share_id.as_str());
        let persisted_head = {
            let conn = self.conn.lock().await;
            conn.query_row(
                "SELECT subdomain, active_generation
                 FROM tunnel_route_heads WHERE router_id = ?1 AND route_id = ?2",
                params![input.router_id, route_id],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)? as u64)),
            )
            .optional()
            .map_err(|e| AppError::Internal(format!("read route generation head failed: {e}")))?
        };
        let persisted_generation = persisted_head
            .as_ref()
            .map(|(_, generation)| *generation)
            .unwrap_or(0);
        if persisted_generation != input.expected_generation {
            return Err(AppError::Conflict(format!(
                "route generation changed: expected {}, active {}",
                input.expected_generation, persisted_generation
            )));
        }
        let runtime_generation = proxy.active_generation(&subdomain).await;
        if runtime_generation != 0 && runtime_generation != persisted_generation {
            return Err(AppError::Conflict(format!(
                "runtime route generation {runtime_generation} differs from persisted head {persisted_generation}"
            )));
        }
        if let Some(route) = proxy
            .backend_for_host(
                &format!("{subdomain}.{}", config.tunnel_domain),
                &config.tunnel_domain,
            )
            .await
        {
            let is_same_share_route =
                requested_share_id.is_some() && route.share_id() == requested_share_id;
            let is_same_client_web_route = is_client_web_tunnel
                && route.is_client_web()
                && route.installation_id() == Some(input.installation_id.as_str());
            if !is_same_share_route {
                if !is_same_client_web_route {
                    return Err(AppError::Conflict("subdomain already in use".into()));
                }
            }
        }

        let normalized_share = if let Some(mut share) = input.share.clone() {
            {
                let conn = self.conn.lock().await;
                ensure_share_id_writable_by_installation(
                    &conn,
                    &share.share_id,
                    &input.installation_id,
                )?;
            }
            let installation_owner = installation
                .owner_email
                .as_deref()
                .ok_or_else(|| {
                    AppError::Conflict("installation owner email is not configured".into())
                })
                .and_then(normalize_email)?;
            normalize_self_reported_share_owner(&mut share, &installation_owner)?;
            Some(share)
        } else {
            None
        };

        if let Some(share) = normalized_share.clone() {
            self.upsert_share(&input.installation_id, share).await?;
        }
        if is_client_web_tunnel {
            let conn = self.conn.lock().await;
            conn.execute(
                "UPDATE installation_client_tunnels
                 SET last_seen_at = ?2, updated_at = ?2
                 WHERE installation_id = ?1",
                params![input.installation_id, Utc::now().to_rfc3339()],
            )
            .map_err(|e| AppError::Internal(format!("touch client tunnel failed: {e}")))?;
        }

        let existing_rotation = {
            let conn = self.conn.lock().await;
            conn.query_row(
                "SELECT protocol_epoch, router_id, id, installation_id, connection_id,
                        route_id, rotation_id, generation, expected_generation, subdomain,
                        tunnel_type, ssh_username, ssh_password, issued_at, expires_at,
                        used_at, share_json, state
                 FROM leases
                 WHERE router_id = ?1 AND route_id = ?2 AND rotation_id = ?3",
                params![input.router_id, route_id, input.rotation_id],
                |row| Ok((map_lease_row(row)?, row.get::<_, String>(17)?)),
            )
            .optional()
            .map_err(|e| AppError::Internal(format!("query existing rotation failed: {e}")))?
        };
        if let Some((existing, state)) = existing_rotation {
            let same_share = serde_json::to_value(&existing.share).ok()
                == serde_json::to_value(&normalized_share).ok();
            let same_claim = existing.protocol_epoch == input.protocol_epoch
                && existing.router_id == input.router_id
                && existing.installation_id == input.installation_id
                && existing.route_id == route_id
                && existing.rotation_id == input.rotation_id
                && existing.generation == input.generation
                && existing.expected_generation == input.expected_generation
                && existing.subdomain == subdomain
                && existing.tunnel_type == tunnel_type
                && same_share;
            if !same_claim {
                return Err(AppError::Conflict(
                    "rotationId is already bound to different lease semantics".into(),
                ));
            }
            if existing.expires_at <= Utc::now() || state == "retired" {
                return Err(AppError::Conflict(
                    "rotationId belongs to an expired or retired lease".into(),
                ));
            }
            if state != "active" && state != "draining" {
                proxy
                    .mark_route_pending(
                        subdomain,
                        StdDuration::from_secs(ROUTE_REGISTRATION_PENDING_GRACE_SECS),
                    )
                    .await;
            }
            return Ok(issue_lease_response(config, &existing));
        }

        let issued_at = Utc::now();
        let expires_at = issued_at + Duration::seconds(config.lease_ttl_secs);
        let connection_id = Uuid::new_v4().to_string();
        let ssh_password = Alphanumeric.sample_string(&mut rand::thread_rng(), 24);
        let lease = TunnelLease {
            protocol_epoch: input.protocol_epoch.clone(),
            router_id: input.router_id.clone(),
            id: Uuid::new_v4().to_string(),
            installation_id: installation.id.clone(),
            connection_id: connection_id.clone(),
            route_id: route_id.clone(),
            rotation_id: input.rotation_id.clone(),
            generation: input.generation,
            expected_generation: input.expected_generation,
            subdomain: subdomain.clone(),
            tunnel_type,
            ssh_username: connection_id.clone(),
            ssh_password: ssh_password.clone(),
            issued_at,
            expires_at,
            used_at: None,
            share: normalized_share,
        };

        let conn = self.conn.lock().await;
        retire_reclaimable_route_candidates_tx(
            &conn,
            &lease.router_id,
            &lease.route_id,
            &lease.installation_id,
            lease.generation,
            issued_at,
        )?;
        let max_generation = conn
            .query_row(
                "SELECT COALESCE(MAX(generation), 0) FROM leases
                 WHERE router_id = ?1 AND route_id = ?2",
                params![lease.router_id, lease.route_id],
                |row| row.get::<_, i64>(0),
            )
            .map_err(|e| AppError::Internal(format!("read latest route generation failed: {e}")))?
            as u64;
        if lease.generation <= max_generation {
            return Err(AppError::Conflict(format!(
                "generation must be newer than persisted generation {max_generation}"
            )));
        }
        let rotation_exists: bool = conn
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM leases
                 WHERE router_id = ?1 AND route_id = ?2 AND rotation_id = ?3)",
                params![lease.router_id, lease.route_id, lease.rotation_id],
                |row| row.get(0),
            )
            .map_err(|e| AppError::Internal(format!("check rotation id failed: {e}")))?;
        if rotation_exists {
            return Err(AppError::Conflict(
                "rotationId has already been used".into(),
            ));
        }
        let live_candidate_exists: bool = conn
            .query_row(
                "SELECT EXISTS(
                    SELECT 1 FROM leases
                    WHERE router_id = ?1 AND route_id = ?2 AND expires_at > ?3
                      AND state IN ('issued', 'authenticated', 'ready')
                )",
                params![lease.router_id, lease.route_id, issued_at.to_rfc3339()],
                |row| row.get(0),
            )
            .map_err(|e| AppError::Internal(format!("check live route candidate failed: {e}")))?;
        if live_candidate_exists {
            return Err(AppError::Conflict(
                "route already has a non-expired candidate rotation".into(),
            ));
        }
        conn.execute(
            "INSERT INTO leases (
                protocol_epoch, router_id, id, installation_id, connection_id, route_id,
                rotation_id, generation, expected_generation, state, subdomain, tunnel_type,
                ssh_username, ssh_password, issued_at, expires_at, used_at, share_json
            ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, 'issued', ?10, ?11,
                      ?12, ?13, ?14, ?15, ?16, ?17)",
            params![
                lease.protocol_epoch,
                lease.router_id,
                lease.id,
                lease.installation_id,
                lease.connection_id,
                lease.route_id,
                lease.rotation_id,
                lease.generation as i64,
                lease.expected_generation as i64,
                lease.subdomain,
                lease.tunnel_type,
                lease.ssh_username,
                lease.ssh_password,
                lease.issued_at.to_rfc3339(),
                lease.expires_at.to_rfc3339(),
                Option::<String>::None,
                lease
                    .share
                    .as_ref()
                    .map(serde_json::to_string)
                    .transpose()
                    .map_err(|e| AppError::Internal(format!("serialize share failed: {e}")))?,
            ],
        )
        .map_err(|e| AppError::Internal(format!("insert lease failed: {e}")))?;
        drop(conn);

        proxy
            .mark_route_pending(
                subdomain.clone(),
                StdDuration::from_secs(ROUTE_REGISTRATION_PENDING_GRACE_SECS),
            )
            .await;

        Ok(IssueLeaseResponse {
            protocol_epoch: lease.protocol_epoch,
            router_id: lease.router_id,
            lease_id: lease.id,
            connection_id: lease.connection_id,
            route_id: lease.route_id,
            rotation_id: lease.rotation_id,
            generation: lease.generation,
            expected_generation: lease.expected_generation,
            ssh_username: lease.ssh_username,
            ssh_password,
            ssh_addr: config.effective_ssh_public_addr(),
            expires_at,
            tunnel_url: config.tunnel_url(&subdomain),
            subdomain,
            ssh_host_fingerprint: None,
        })
    }

    pub async fn consume_lease(
        &self,
        username: &str,
        password: &str,
    ) -> Result<TunnelLease, AppError> {
        let now = Utc::now();
        let conn = self.conn.lock().await;
        let mut lease = get_lease_by_connection_id(&conn, username)?
            .ok_or_else(|| AppError::Unauthorized("lease not found".into()))?;
        if lease.expires_at < now {
            return Err(AppError::Unauthorized("lease expired".into()));
        }
        if !crate::ctl_client::constant_time_eq(lease.ssh_password.as_bytes(), password.as_bytes())
        {
            return Err(AppError::Unauthorized("invalid ssh credentials".into()));
        }
        ensure_tunnel_protocol_epoch(&lease.protocol_epoch)?;
        let updated = conn
            .execute(
                "UPDATE leases
             SET used_at = ?2,
                 state = 'authenticated'
             WHERE connection_id = ?1 AND used_at IS NULL AND state = 'issued'",
                params![username, now.to_rfc3339()],
            )
            .map_err(|e| AppError::Internal(format!("update lease use failed: {e}")))?;
        if updated != 1 {
            return Err(AppError::Unauthorized("lease already used".into()));
        }
        lease.used_at = Some(now);
        Ok(lease)
    }

    pub async fn consume_control_request_nonce(
        &self,
        installation_id: &str,
        nonce: &str,
    ) -> Result<(), AppError> {
        validate_request_nonce(nonce)?;
        let conn = self.conn.lock().await;
        consume_request_nonce(
            &conn,
            installation_id,
            "ctl_control_request",
            nonce,
            Utc::now(),
        )
    }

    pub async fn mark_lease_ready(
        &self,
        connection_id: &str,
        route_id: &str,
        generation: u64,
    ) -> Result<(), AppError> {
        let now = Utc::now().to_rfc3339();
        let conn = self.conn.lock().await;
        let updated = conn
            .execute(
                "UPDATE leases
                 SET state = CASE WHEN state = 'active' THEN 'active' ELSE 'ready' END,
                     ready_at = COALESCE(ready_at, ?4)
                 WHERE connection_id = ?1 AND route_id = ?2 AND generation = ?3
                   AND used_at IS NOT NULL AND state IN ('authenticated', 'ready', 'active')",
                params![connection_id, route_id, generation as i64, now],
            )
            .map_err(|e| AppError::Internal(format!("mark tunnel lease ready failed: {e}")))?;
        if updated != 1 {
            return Err(AppError::Conflict(
                "tunnel lease changed before candidate became ready".into(),
            ));
        }
        Ok(())
    }

    pub async fn renew_lease(
        &self,
        config: &Config,
        proxy: &ProxyRegistry,
        input: RenewLeaseRequest,
        metadata: ClientMetadata,
    ) -> Result<RenewLeaseResponse, AppError> {
        let now = Utc::now();
        ensure_tunnel_protocol_epoch(&input.renewal.protocol_epoch)?;
        ensure_tunnel_router_id(config, &input.renewal.router_id)?;
        validate_tunnel_route_id(&input.renewal.route_id)?;
        let (subdomain, tunnel_type) = {
            let conn = self.conn.lock().await;
            let installation = get_installation(&conn, &input.installation_id)?
                .ok_or_else(|| AppError::Unauthorized("installation not found".into()))?;
            verify_signed_tunnel_request(
                &conn,
                &installation.public_key,
                &input.installation_id,
                "tunnel_lease_renew",
                &input.renewal,
                input.timestamp_ms,
                &input.nonce,
                &input.signature,
            )?;
            let lease = conn
                .query_row(
                    "SELECT subdomain, tunnel_type, used_at, state
                     FROM leases
                     WHERE id = ?1 AND installation_id = ?2 AND connection_id = ?3
                       AND protocol_epoch = ?4 AND router_id = ?5 AND route_id = ?6
                       AND rotation_id = ?7 AND generation = ?8 AND expected_generation = ?9",
                    params![
                        input.renewal.lease_id,
                        input.installation_id,
                        input.renewal.connection_id,
                        input.renewal.protocol_epoch,
                        input.renewal.router_id,
                        input.renewal.route_id,
                        input.renewal.rotation_id,
                        input.renewal.generation as i64,
                        input.renewal.expected_generation as i64,
                    ],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, String>(1)?,
                            row.get::<_, Option<String>>(2)?,
                            row.get::<_, String>(3)?,
                        ))
                    },
                )
                .optional()
                .map_err(|error| {
                    AppError::Internal(format!("query tunnel lease for renewal failed: {error}"))
                })?
                .ok_or_else(|| AppError::Conflict("tunnel lease is no longer renewable".into()))?;
            if lease.2.is_none() {
                return Err(AppError::Conflict(
                    "tunnel lease has not established an SSH session".into(),
                ));
            }
            if lease.3 != "active" {
                return Err(AppError::Conflict("tunnel generation is not active".into()));
            }
            let head_generation = conn
                .query_row(
                    "SELECT active_generation FROM tunnel_route_heads
                     WHERE router_id = ?1 AND route_id = ?2 AND subdomain = ?3",
                    params![input.renewal.router_id, input.renewal.route_id, lease.0],
                    |row| row.get::<_, i64>(0),
                )
                .optional()
                .map_err(|error| {
                    AppError::Internal(format!(
                        "query tunnel route head for renewal failed: {error}"
                    ))
                })?
                .ok_or_else(|| AppError::Conflict("tunnel route head is missing".into()))?;
            if head_generation as u64 != input.renewal.generation {
                return Err(AppError::Conflict(
                    "tunnel route head belongs to another generation".into(),
                ));
            }
            touch_installation_activity(&conn, &input.installation_id, &metadata, now)?;
            (lease.0, lease.1)
        };

        let route = proxy
            .backend_for_host(
                &format!("{subdomain}.{}", config.tunnel_domain),
                &config.tunnel_domain,
            )
            .await
            .ok_or_else(|| AppError::Conflict("tunnel route is not active".into()))?;
        if route.connection_id() != Some(input.renewal.connection_id.as_str())
            || route.installation_id() != Some(input.installation_id.as_str())
            || route.generation() != input.renewal.generation
            || route.rotation_id() != input.renewal.rotation_id
        {
            return Err(AppError::Conflict(
                "tunnel route belongs to a different connection".into(),
            ));
        }

        let expires_at = Utc::now() + Duration::seconds(config.lease_ttl_secs);
        let conn = self.conn.lock().await;
        let updated = conn
            .execute(
                "UPDATE leases
                 SET expires_at = ?4
                 WHERE id = ?1 AND installation_id = ?2 AND connection_id = ?3",
                params![
                    input.renewal.lease_id,
                    input.installation_id,
                    input.renewal.connection_id,
                    expires_at.to_rfc3339()
                ],
            )
            .map_err(|error| AppError::Internal(format!("renew tunnel lease failed: {error}")))?;
        if updated != 1 {
            return Err(AppError::Conflict(
                "tunnel lease changed during renewal".into(),
            ));
        }
        if tunnel_type == "client-web-http" {
            conn.execute(
                "UPDATE installation_client_tunnels
                 SET last_seen_at = ?2, updated_at = ?2
                 WHERE installation_id = ?1",
                params![input.installation_id, Utc::now().to_rfc3339()],
            )
            .map_err(|error| {
                AppError::Internal(format!("touch renewed client tunnel failed: {error}"))
            })?;
        }
        Ok(RenewLeaseResponse {
            protocol_epoch: input.renewal.protocol_epoch,
            router_id: input.renewal.router_id,
            route_id: input.renewal.route_id,
            rotation_id: input.renewal.rotation_id,
            generation: input.renewal.generation,
            expires_at,
        })
    }

    pub async fn activate_tunnel(
        &self,
        config: &Config,
        proxy: &ProxyRegistry,
        probe_http: &reqwest::Client,
        input: TunnelActivateRequest,
    ) -> Result<TunnelStateResponse, AppError> {
        ensure_tunnel_protocol_epoch(&input.activation.protocol_epoch)?;
        ensure_tunnel_router_id(config, &input.activation.router_id)?;
        let route_id = validate_tunnel_route_id(&input.activation.route_id)?;
        let (lease_state, subdomain, persisted_generation) = {
            let conn = self.conn.lock().await;
            let installation = get_installation(&conn, &input.installation_id)?
                .ok_or_else(|| AppError::Unauthorized("installation not found".into()))?;
            verify_signed_tunnel_request(
                &conn,
                &installation.public_key,
                &input.installation_id,
                "tunnel_activate",
                &input.activation,
                input.timestamp_ms,
                &input.nonce,
                &input.signature,
            )?;
            let (lease_state, subdomain) = conn
                .query_row(
                    "SELECT state, subdomain FROM leases
                     WHERE id = ?1 AND installation_id = ?2 AND connection_id = ?3
                       AND protocol_epoch = ?4 AND router_id = ?5 AND route_id = ?6
                       AND rotation_id = ?7 AND generation = ?8 AND expected_generation = ?9",
                    params![
                        input.activation.lease_id,
                        input.installation_id,
                        input.activation.connection_id,
                        input.activation.protocol_epoch,
                        input.activation.router_id,
                        input.activation.route_id,
                        input.activation.rotation_id,
                        input.activation.generation as i64,
                        input.activation.expected_generation as i64,
                    ],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
                )
                .optional()
                .map_err(|e| AppError::Internal(format!("query activation lease failed: {e}")))?
                .ok_or_else(|| AppError::Conflict("tunnel lease identity does not match".into()))?;
            if lease_state != "ready" && lease_state != "active" {
                return Err(AppError::Conflict(format!(
                    "tunnel lease is not ready: {lease_state}"
                )));
            }
            let persisted_generation = conn
                .query_row(
                    "SELECT active_generation FROM tunnel_route_heads
                     WHERE router_id = ?1 AND route_id = ?2 AND subdomain = ?3",
                    params![input.activation.router_id, route_id, subdomain],
                    |row| row.get::<_, i64>(0),
                )
                .optional()
                .map_err(|e| AppError::Internal(format!("read activation route head failed: {e}")))?
                .unwrap_or(0) as u64;
            (lease_state, subdomain, persisted_generation)
        };

        if lease_state == "active" && persisted_generation == input.activation.generation {
            let mut runtime = proxy.route_state(&subdomain).await;
            if runtime.as_ref().and_then(|state| state.active_generation)
                != Some(input.activation.generation)
            {
                runtime = Some(
                    proxy
                        .promote_candidate(
                            &subdomain,
                            &input.activation.connection_id,
                            &input.activation.rotation_id,
                            input.activation.generation,
                            input.activation.expected_generation,
                        )
                        .await
                        .map_err(|error| AppError::Conflict(error.to_string()))?,
                );
            }
            return Ok(TunnelStateResponse {
                protocol_epoch: input.activation.protocol_epoch,
                router_id: input.activation.router_id,
                route_id,
                rotation_id: input.activation.rotation_id,
                generation: input.activation.generation,
                expected_generation: input.activation.expected_generation,
                state: "active".into(),
                active_generation: Some(input.activation.generation),
                candidate_generations: runtime
                    .as_ref()
                    .map(|state| state.candidate_generations.clone())
                    .unwrap_or_default(),
                draining_generations: runtime
                    .as_ref()
                    .map(|state| state.draining_generations.clone())
                    .unwrap_or_default(),
            });
        }
        if persisted_generation != input.activation.expected_generation {
            return Err(AppError::Conflict(format!(
                "route generation changed: expected {}, active {}",
                input.activation.expected_generation, persisted_generation
            )));
        }

        let candidate = proxy
            .candidate_for_activation(
                &subdomain,
                &input.activation.connection_id,
                &input.activation.rotation_id,
                input.activation.generation,
            )
            .await
            .ok_or_else(|| AppError::Conflict("tunnel candidate is not ready".into()))?;
        if candidate.installation_id() != Some(input.installation_id.as_str()) {
            return Err(AppError::Conflict(
                "tunnel candidate belongs to another installation".into(),
            ));
        }
        let control_secret = self
            .installation_control_secret(&input.installation_id)
            .await?
            .filter(|secret| !secret.trim().is_empty())
            .ok_or_else(|| {
                AppError::ServiceUnavailable(
                    "candidate probe unavailable: installation control secret is missing".into(),
                )
            })?;
        const PROBE_PATH: &str = "/_share-router/health";
        let probe_url = format!("http://{}{PROBE_PATH}", candidate.route_target());
        let probe = crate::ctl_client::authorize_control_request(
            probe_http
                .get(&probe_url)
                .header("X-Share-Router-Probe", "1"),
            "GET",
            PROBE_PATH,
            &input.installation_id,
            &control_secret,
            &[],
        );
        let probe_response = tokio::time::timeout(StdDuration::from_secs(5), probe.send())
            .await
            .map_err(|_| AppError::ServiceUnavailable("candidate health probe timed out".into()))?
            .map_err(|error| {
                AppError::ServiceUnavailable(format!("candidate health probe failed: {error}"))
            })?;
        if !probe_response.status().is_success() {
            return Err(AppError::ServiceUnavailable(format!(
                "candidate health probe returned {}",
                probe_response.status()
            )));
        }

        let runtime = proxy
            .promote_candidate(
                &subdomain,
                &input.activation.connection_id,
                &input.activation.rotation_id,
                input.activation.generation,
                input.activation.expected_generation,
            )
            .await
            .map_err(|error| AppError::Conflict(error.to_string()))?;

        let now = Utc::now().to_rfc3339();
        let persistence_result = {
            let conn = self.conn.lock().await;
            (|| -> Result<(), AppError> {
                let tx = conn
                    .transaction_with_behavior(TransactionBehavior::Immediate)
                    .map_err(|e| {
                        AppError::Internal(format!("begin tunnel activation tx failed: {e}"))
                    })?;
                let head_updated = tx
                    .execute(
                        "INSERT INTO tunnel_route_heads (
                        router_id, route_id, subdomain, active_generation,
                        active_connection_id, active_rotation_id, updated_at
                     ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)
                     ON CONFLICT(router_id, route_id) DO UPDATE SET
                        subdomain = excluded.subdomain,
                        active_generation = excluded.active_generation,
                        active_connection_id = excluded.active_connection_id,
                        active_rotation_id = excluded.active_rotation_id,
                        updated_at = excluded.updated_at
                     WHERE tunnel_route_heads.active_generation = ?8",
                        params![
                            input.activation.router_id,
                            route_id,
                            subdomain,
                            input.activation.generation as i64,
                            input.activation.connection_id,
                            input.activation.rotation_id,
                            now,
                            input.activation.expected_generation as i64,
                        ],
                    )
                    .map_err(|e| {
                        AppError::Internal(format!("advance tunnel route head failed: {e}"))
                    })?;
                if head_updated != 1 {
                    return Err(AppError::Conflict(
                        "persisted tunnel route head changed during activation".into(),
                    ));
                }
                tx.execute(
                    "UPDATE leases
                 SET state = 'draining', retired_at = NULL
                 WHERE router_id = ?1 AND route_id = ?2 AND state = 'active' AND generation != ?3",
                    params![
                        input.activation.router_id,
                        route_id,
                        input.activation.generation as i64
                    ],
                )
                .map_err(|e| {
                    AppError::Internal(format!("mark old tunnel generation draining failed: {e}"))
                })?;
                let updated = tx
                .execute(
                    "UPDATE leases
                     SET state = 'active', activated_at = COALESCE(activated_at, ?2), retired_at = NULL
                     WHERE id = ?1 AND state IN ('ready', 'active')",
                    params![input.activation.lease_id, now],
                )
                .map_err(|e| {
                    AppError::Internal(format!("mark tunnel generation active failed: {e}"))
                })?;
                if updated != 1 {
                    return Err(AppError::Conflict(
                        "tunnel lease changed during activation".into(),
                    ));
                }
                tx.commit().map_err(|e| {
                    AppError::Internal(format!("commit tunnel activation failed: {e}"))
                })?;
                Ok(())
            })()
        };
        if let Err(error) = persistence_result {
            proxy
                .rollback_candidate_promotion(
                    &subdomain,
                    &input.activation.connection_id,
                    &input.activation.rotation_id,
                    input.activation.generation,
                    input.activation.expected_generation,
                )
                .await;
            return Err(error);
        }

        Ok(TunnelStateResponse {
            protocol_epoch: input.activation.protocol_epoch,
            router_id: input.activation.router_id,
            route_id,
            rotation_id: input.activation.rotation_id,
            generation: input.activation.generation,
            expected_generation: input.activation.expected_generation,
            state: "active".into(),
            active_generation: runtime.active_generation,
            candidate_generations: runtime.candidate_generations,
            draining_generations: runtime.draining_generations,
        })
    }

    pub async fn tunnel_state(
        &self,
        config: &Config,
        proxy: &ProxyRegistry,
        input: TunnelStateRequest,
    ) -> Result<TunnelStateResponse, AppError> {
        ensure_tunnel_protocol_epoch(&input.query.protocol_epoch)?;
        ensure_tunnel_router_id(config, &input.query.router_id)?;
        let route_id = validate_tunnel_route_id(&input.query.route_id)?;
        let (persisted_state, subdomain, persisted_active_generation) = {
            let conn = self.conn.lock().await;
            let installation = get_installation(&conn, &input.installation_id)?
                .ok_or_else(|| AppError::Unauthorized("installation not found".into()))?;
            verify_signed_tunnel_request(
                &conn,
                &installation.public_key,
                &input.installation_id,
                "tunnel_state",
                &input.query,
                input.timestamp_ms,
                &input.nonce,
                &input.signature,
            )?;
            let (persisted_state, subdomain) = conn
                .query_row(
                    "SELECT state, subdomain FROM leases
                 WHERE id = ?1 AND installation_id = ?2 AND connection_id = ?3
                   AND protocol_epoch = ?4 AND router_id = ?5 AND route_id = ?6
                   AND rotation_id = ?7 AND generation = ?8 AND expected_generation = ?9",
                    params![
                        input.query.lease_id,
                        input.installation_id,
                        input.query.connection_id,
                        input.query.protocol_epoch,
                        input.query.router_id,
                        input.query.route_id,
                        input.query.rotation_id,
                        input.query.generation as i64,
                        input.query.expected_generation as i64,
                    ],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
                )
                .optional()
                .map_err(|e| AppError::Internal(format!("query tunnel state failed: {e}")))?
                .ok_or_else(|| AppError::NotFound("tunnel lease not found".into()))?;
            let persisted_active_generation = conn
                .query_row(
                    "SELECT active_generation FROM tunnel_route_heads
                     WHERE router_id = ?1 AND route_id = ?2 AND subdomain = ?3",
                    params![input.query.router_id, route_id, subdomain],
                    |row| row.get::<_, i64>(0),
                )
                .optional()
                .map_err(|e| AppError::Internal(format!("read tunnel state head failed: {e}")))?
                .map(|generation| generation as u64);
            (persisted_state, subdomain, persisted_active_generation)
        };
        let runtime = proxy.route_state(&subdomain).await;
        let active_generation = runtime
            .as_ref()
            .and_then(|state| state.active_generation)
            .or(persisted_active_generation);
        let candidate_generations = runtime
            .as_ref()
            .map(|state| state.candidate_generations.clone())
            .unwrap_or_default();
        let draining_generations = runtime
            .as_ref()
            .map(|state| state.draining_generations.clone())
            .unwrap_or_default();
        let state = if active_generation == Some(input.query.generation) {
            "active".to_string()
        } else if candidate_generations.contains(&input.query.generation) {
            "ready".to_string()
        } else if draining_generations.contains(&input.query.generation) {
            "draining".to_string()
        } else {
            persisted_state
        };
        Ok(TunnelStateResponse {
            protocol_epoch: input.query.protocol_epoch,
            router_id: input.query.router_id,
            route_id,
            rotation_id: input.query.rotation_id,
            generation: input.query.generation,
            expected_generation: input.query.expected_generation,
            state,
            active_generation,
            candidate_generations,
            draining_generations,
        })
    }

    pub async fn sync_share(
        &self,
        input: ShareSyncRequest,
        metadata: ClientMetadata,
        _current_user_email: &str,
    ) -> Result<(), AppError> {
        let installation_owner = {
            let conn = self.conn.lock().await;
            let installation = get_installation(&conn, &input.installation_id)?;
            let Some(installation) = installation else {
                return Err(AppError::Unauthorized("installation not found".into()));
            };
            let owner = installation
                .owner_email
                .as_deref()
                .ok_or_else(|| {
                    AppError::Conflict("installation owner email is not configured".into())
                })
                .and_then(normalize_email)?;
            verify_signed_share_request(
                &conn,
                &installation.public_key,
                &input.installation_id,
                "share_sync",
                &input.share,
                input.timestamp_ms,
                &input.nonce,
                &input.signature,
            )?;
            let should_refresh_geo =
                should_refresh_installation_geo(&installation, metadata.ip.as_deref());
            touch_installation_activity(&conn, &input.installation_id, &metadata, Utc::now())?;
            drop(conn);
            if should_refresh_geo {
                self.refresh_installation_geo(&input.installation_id, &metadata.ip, false)
                    .await?;
            }
            owner
        };
        let mut share = input.share;
        {
            let conn = self.conn.lock().await;
            ensure_share_id_writable_by_installation(
                &conn,
                &share.share_id,
                &input.installation_id,
            )?;
        }
        normalize_self_reported_share_owner(&mut share, &installation_owner)?;
        {
            let conn = self.conn.lock().await;
            validate_share_namespace_for_installation(
                &conn,
                &input.installation_id,
                &share.subdomain,
            )?;
        }
        self.upsert_share(&input.installation_id, share).await
    }

    pub async fn claim_share_subdomain(
        &self,
        _config: &Config,
        input: ShareClaimSubdomainRequest,
        metadata: ClientMetadata,
        _current_user_email: &str,
    ) -> Result<(), AppError> {
        let subdomain = normalize_subdomain(&input.share.subdomain)?;
        ensure_subdomain_allowed(&subdomain)?;
        let conn = self.conn.lock().await;
        if get_client_tunnel_by_subdomain(&conn, &subdomain)?.is_some() {
            return Err(AppError::Conflict(
                "subdomain already claimed by client tunnel".into(),
            ));
        }
        let installation = get_installation(&conn, &input.installation_id)?;
        let Some(installation) = installation else {
            return Err(AppError::Unauthorized("installation not found".into()));
        };
        let installation_owner = installation
            .owner_email
            .as_deref()
            .ok_or_else(|| AppError::Conflict("installation owner email is not configured".into()))
            .and_then(normalize_email)?;
        verify_share_claim_request(
            &conn,
            &installation.public_key,
            &input.installation_id,
            &input.share,
            input.claim.as_ref(),
            input.timestamp_ms,
            &input.nonce,
            &input.signature,
        )?;
        let parsed = parse_share_label(&subdomain)
            .map_err(|message| AppError::BadRequest(message.into()))?;
        let client_tunnel = get_client_tunnel_by_installation(&conn, &input.installation_id)?
            .ok_or_else(|| AppError::Conflict("client tunnel must be claimed first".into()))?;
        if parsed.client_subdomain != client_tunnel.subdomain {
            return Err(AppError::Conflict(
                "share host client subdomain does not belong to this installation".into(),
            ));
        }
        let should_refresh_geo =
            should_refresh_installation_geo(&installation, metadata.ip.as_deref());
        touch_installation_activity(&conn, &input.installation_id, &metadata, Utc::now())?;
        drop(conn);
        if should_refresh_geo {
            self.refresh_installation_geo(&input.installation_id, &metadata.ip, false)
                .await?;
        }

        let conn = self.conn.lock().await;
        let tx = conn
            .unchecked_transaction()
            .map_err(|e| AppError::Internal(format!("begin share claim tx failed: {e}")))?;
        let mut share = input.share;
        ensure_share_id_writable_by_installation(&tx, &share.share_id, &input.installation_id)?;
        normalize_self_reported_share_owner(&mut share, &installation_owner)?;
        share.subdomain = subdomain;
        release_reclaimable_subdomain_claim(
            &tx,
            &input.installation_id,
            &share.share_id,
            share.owner_email.as_deref(),
            &share.subdomain,
        )?;
        let route_id = format!("share:{}", share.share_id);
        let host_claim = crate::public_hosts::NewPublicHost {
            label: &share.subdomain,
            route_id: &route_id,
            kind: PublicHostKind::Share,
            subject_id: &share.share_id,
            installation_id: Some(&input.installation_id),
            target_lane_id: &input.installation_id,
        };
        crate::public_hosts::reconcile_share_claim_in_transaction(&tx, host_claim)
            .map_err(map_public_host_error)?;
        upsert_share_tx(&tx, &input.installation_id, share)?;
        tx.commit().map_err(map_share_constraint_error)?;
        Ok(())
    }

    pub async fn delete_share(
        &self,
        input: ShareDeleteRequest,
        _current_user_email: &str,
    ) -> Result<(), AppError> {
        let conn = self.conn.lock().await;
        let installation = get_installation(&conn, &input.installation_id)?;
        let Some(installation) = installation else {
            return Err(AppError::Unauthorized("installation not found".into()));
        };
        let delete_payload = serde_json::json!({ "shareId": &input.share_id });
        verify_signed_share_request(
            &conn,
            &installation.public_key,
            &input.installation_id,
            "share_delete",
            &delete_payload,
            input.timestamp_ms,
            &input.nonce,
            &input.signature,
        )?;
        let tx = conn
            .unchecked_transaction()
            .map_err(|e| AppError::Internal(format!("begin share delete tx failed: {e}")))?;
        retire_share_tx(&tx, &input.share_id, &input.installation_id)?;
        tx.commit()
            .map_err(|e| AppError::Internal(format!("commit share delete failed: {e}")))?;
        Ok(())
    }

    pub async fn prune_shares(
        &self,
        input: SharePruneRequest,
        metadata: ClientMetadata,
    ) -> Result<usize, AppError> {
        let retained_share_ids = validate_share_prune_ids(&input.share_ids)?;
        let conn = self.conn.lock().await;
        let installation = get_installation(&conn, &input.installation_id)?;
        let Some(installation) = installation else {
            return Err(AppError::Unauthorized("installation not found".into()));
        };
        verify_signed_share_request(
            &conn,
            &installation.public_key,
            &input.installation_id,
            "share_prune_v1",
            &input.share_ids,
            input.timestamp_ms,
            &input.nonce,
            &input.signature,
        )?;
        let should_refresh_geo =
            should_refresh_installation_geo(&installation, metadata.ip.as_deref());
        touch_installation_activity(&conn, &input.installation_id, &metadata, Utc::now())?;
        drop(conn);
        if should_refresh_geo {
            self.refresh_installation_geo(&input.installation_id, &metadata.ip, false)
                .await?;
        }

        let conn = self.conn.lock().await;
        let tx = conn
            .unchecked_transaction()
            .map_err(|e| AppError::Internal(format!("begin share prune tx failed: {e}")))?;
        let pruned = delete_all_shares_for_installation_tx(
            &tx,
            &input.installation_id,
            &retained_share_ids,
        )?;
        tx.commit()
            .map_err(|e| AppError::Internal(format!("commit share prune failed: {e}")))?;
        Ok(pruned)
    }

