    /// Rebuilds the in-memory routing namespace from authoritative entities.
    /// Persisted public-host rows enforce ownership but are not sufficient for
    /// startup hydration because a retired entity may leave historical rows.
    pub async fn list_route_intents(&self) -> Result<Vec<RouteIntent>, AppError> {
        let conn = self.conn.lock().await;
        let mut stmt = conn
            .prepare(
                "SELECT subdomain, kind, subject_id
                 FROM (
                     SELECT subdomain, 'share' AS kind, share_id AS subject_id
                     FROM shares
                     WHERE share_status = 'active'
                       AND subdomain IS NOT NULL
                       AND subdomain != ''
                       AND subdomain != '-'
                     UNION ALL
                     SELECT subdomain, 'client' AS kind, installation_id AS subject_id
                     FROM installation_client_tunnels
                     WHERE enabled = 1
                       AND subdomain IS NOT NULL
                       AND subdomain != ''
                 )
                 ORDER BY subdomain ASC, kind ASC",
            )
            .map_err(|error| {
                AppError::Internal(format!("prepare startup route intents failed: {error}"))
            })?;
        let rows = stmt
            .query_map([], |row| {
                let kind = match row.get::<_, String>(1)?.as_str() {
                    "share" => RouteIntentKind::Share,
                    "client" => RouteIntentKind::Client,
                    _ => unreachable!("route intent query returns fixed kinds"),
                };
                Ok(RouteIntent {
                    subdomain: row.get(0)?,
                    kind,
                    subject_id: row.get(2)?,
                })
            })
            .map_err(|error| {
                AppError::Internal(format!("query startup route intents failed: {error}"))
            })?;
        let intents = collect_rows(rows)?;
        let mut owners = HashMap::<String, (RouteIntentKind, String)>::new();
        for intent in &intents {
            let subdomain = intent.subdomain.trim().to_ascii_lowercase();
            if let Some((kind, subject_id)) =
                owners.insert(subdomain.clone(), (intent.kind, intent.subject_id.clone()))
            {
                return Err(AppError::Internal(format!(
                    "public route {subdomain} is assigned to both {kind:?} {subject_id} and {:?} {}",
                    intent.kind, intent.subject_id
                )));
            }
        }
        Ok(intents)
    }

    pub async fn register_gateway(
        &self,
        input: RegisterGatewayRequest,
    ) -> Result<RegisterGatewayResponse, AppError> {
        let owner_email = normalize_email(&input.owner_email)?;
        let display_name = input.display_name.trim();
        if display_name.is_empty() || display_name.len() > 80 {
            return Err(AppError::BadRequest("invalid gateway display name".into()));
        }
        validate_ed25519_public_key(&input.public_key)?;
        let public_base_url = input
            .public_base_url
            .as_ref()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty());
        if let Some(url) = public_base_url
            && !url.starts_with("http://")
            && !url.starts_with("https://")
        {
            return Err(AppError::BadRequest(
                "invalid gateway public base url".into(),
            ));
        }
        let app_version = input
            .app_version
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned);
        let scopes_json = serde_json::to_string(GATEWAY_DEFAULT_SCOPES)
            .map_err(|e| AppError::Internal(format!("serialize gateway scopes failed: {e}")))?;
        let now = Utc::now().to_rfc3339();
        let conn = self.conn.lock().await;
        let existing = get_gateway_by_public_key(&conn, &input.public_key)?;
        let id = existing
            .as_ref()
            .map(|gateway| gateway.id.clone())
            .unwrap_or_else(|| Uuid::new_v4().to_string());
        let created_at = if let Some(gateway) = existing.as_ref() {
            gateway_created_at(&conn, &gateway.id)?.unwrap_or_else(|| now.clone())
        } else {
            now.clone()
        };
        conn.execute(
            "INSERT INTO router_gateways (
                id, owner_email, display_name, public_key, public_base_url,
                app_version, scopes_json, status, created_at, updated_at, last_seen_at
             ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 'active', ?8, ?9, ?9)
             ON CONFLICT(public_key) DO UPDATE SET
                owner_email = excluded.owner_email,
                display_name = excluded.display_name,
                public_base_url = excluded.public_base_url,
                app_version = excluded.app_version,
                scopes_json = excluded.scopes_json,
                status = 'active',
                updated_at = excluded.updated_at,
                last_seen_at = excluded.last_seen_at",
            params![
                id,
                owner_email,
                display_name,
                input.public_key,
                public_base_url.map(ToOwned::to_owned),
                app_version,
                scopes_json.clone(),
                created_at,
                now,
            ],
        )
        .map_err(|e| AppError::Internal(format!("register gateway failed: {e}")))?;

        Ok(RegisterGatewayResponse {
            gateway_id: id,
            owner_email,
            display_name: display_name.to_string(),
            status: "active".to_string(),
            scopes: GATEWAY_DEFAULT_SCOPES
                .iter()
                .map(|scope| scope.to_string())
                .collect(),
            created_at,
            last_seen_at: now,
        })
    }

    pub async fn authenticate_gateway_signed_request(
        &self,
        gateway_id: &str,
        required_scope: &str,
        action: &str,
        body_sha256_hex: &str,
        timestamp_ms: i64,
        nonce: &str,
        signature: &str,
    ) -> Result<GatewayRegistryRecord, AppError> {
        if gateway_id.trim().is_empty() || nonce.trim().is_empty() || signature.trim().is_empty() {
            return Err(AppError::Unauthorized(
                "missing gateway signature fields".into(),
            ));
        }
        let conn = self.conn.lock().await;
        let gateway = get_gateway_by_id(&conn, gateway_id)?
            .ok_or_else(|| AppError::Unauthorized("gateway is not registered".into()))?;
        if !gateway.has_scope(required_scope) {
            return Err(AppError::Unauthorized(
                "gateway scope is not allowed".into(),
            ));
        }
        verify_signed_gateway_request(
            &conn,
            &gateway.public_key,
            &gateway.id,
            action,
            body_sha256_hex,
            timestamp_ms,
            nonce,
            signature,
        )?;
        conn.execute(
            "UPDATE router_gateways SET last_seen_at = ?1 WHERE id = ?2",
            params![Utc::now().to_rfc3339(), gateway.id],
        )
        .map_err(|e| AppError::Internal(format!("touch gateway failed: {e}")))?;
        Ok(gateway)
    }

