const INSTALLATION_SELECT_COLUMNS: &str = "id, public_key, platform, app_version, owner_email, owner_verified_at, last_seen_ip, country_code, country, region, city, latitude, longitude,
                geo_candidate_country_code, geo_candidate_country, geo_candidate_region, geo_candidate_city,
                geo_candidate_latitude, geo_candidate_longitude, geo_candidate_hits, geo_candidate_first_seen_at,
                geo_last_changed_at, created_at, last_seen_at, client_activated_at,
                delegate_upgrade_to_router_owner, app_commit_id, update_available, upgrade_capable, status_reported_at, public_ip, provision_source,
                log_collection_enabled, log_collection_reported_at";

fn map_installation_row(row: &crate::db::Row<'_>) -> crate::db::Result<Installation> {
    Ok(Installation {
        id: row.get(0)?,
        public_key: row.get(1)?,
        platform: row.get(2)?,
        app_version: row.get(3)?,
        owner_email: row.get(4)?,
        owner_verified_at: row
            .get::<_, Option<String>>(5)?
            .map(|value| parse_dt_sql(&value))
            .transpose()
            .map_err(|error| {
                crate::db::Error::FromSqlConversionFailure(
                    5,
                    crate::db::types::Type::Text,
                    Box::new(error),
                )
            })?,
        last_seen_ip: row.get(6)?,
        country_code: row.get(7)?,
        country: row.get(8)?,
        region: row.get(9)?,
        city: row.get(10)?,
        latitude: row.get(11)?,
        longitude: row.get(12)?,
        geo_candidate_country_code: row.get(13)?,
        geo_candidate_country: row.get(14)?,
        geo_candidate_region: row.get(15)?,
        geo_candidate_city: row.get(16)?,
        geo_candidate_latitude: row.get(17)?,
        geo_candidate_longitude: row.get(18)?,
        geo_candidate_hits: row.get(19)?,
        geo_candidate_first_seen_at: row
            .get::<_, Option<String>>(20)?
            .map(|value| parse_dt_sql(&value))
            .transpose()
            .map_err(|error| {
                crate::db::Error::FromSqlConversionFailure(
                    20,
                    crate::db::types::Type::Text,
                    Box::new(error),
                )
            })?,
        geo_last_changed_at: row
            .get::<_, Option<String>>(21)?
            .map(|value| parse_dt_sql(&value))
            .transpose()
            .map_err(|error| {
                crate::db::Error::FromSqlConversionFailure(
                    21,
                    crate::db::types::Type::Text,
                    Box::new(error),
                )
            })?,
        created_at: parse_dt_sql(&row.get::<_, String>(22)?).map_err(|error| {
            crate::db::Error::FromSqlConversionFailure(
                22,
                crate::db::types::Type::Text,
                Box::new(error),
            )
        })?,
        last_seen_at: parse_dt_sql(&row.get::<_, String>(23)?).map_err(|error| {
            crate::db::Error::FromSqlConversionFailure(
                23,
                crate::db::types::Type::Text,
                Box::new(error),
            )
        })?,
        client_activated_at: row
            .get::<_, Option<String>>(24)?
            .map(|value| parse_dt_sql(&value))
            .transpose()
            .map_err(|error| {
                crate::db::Error::FromSqlConversionFailure(
                    24,
                    crate::db::types::Type::Text,
                    Box::new(error),
                )
            })?,
        delegate_upgrade_to_router_owner: row.get::<_, Option<i64>>(25)?.map(|value| value != 0),
        app_commit_id: row.get(26)?,
        update_available: row.get::<_, Option<i64>>(27)?.map(|value| value != 0),
        upgrade_capable: row.get::<_, Option<i64>>(28)?.map(|value| value != 0),
        status_reported_at: row
            .get::<_, Option<String>>(29)?
            .map(|value| parse_dt_sql(&value))
            .transpose()
            .map_err(|error| {
                crate::db::Error::FromSqlConversionFailure(
                    29,
                    crate::db::types::Type::Text,
                    Box::new(error),
                )
            })?,
        public_ip: row.get(30)?,
        provision_source: row.get(31)?,
        log_collection_enabled: row.get::<_, i64>(32)? != 0,
        log_collection_reported_at: row
            .get::<_, Option<String>>(33)?
            .map(|value| parse_dt_sql(&value))
            .transpose()
            .map_err(|error| {
                crate::db::Error::FromSqlConversionFailure(
                    33,
                    crate::db::types::Type::Text,
                    Box::new(error),
                )
            })?,
    })
}

fn installation_upgrade_view(installation: &Installation) -> Option<InstallationUpgradeView> {
    if installation.status_reported_at.is_none()
        && installation.delegate_upgrade_to_router_owner.is_none()
        && installation.app_commit_id.is_none()
    {
        return None;
    }
    Some(InstallationUpgradeView {
        delegate_upgrade_to_router_owner: installation
            .delegate_upgrade_to_router_owner
            .unwrap_or(true),
        update_available: installation.update_available.unwrap_or(false),
        upgrade_capable: installation.upgrade_capable.unwrap_or(false),
        commit_id: installation.app_commit_id.clone(),
    })
}

fn validate_installation_upgrade_task_report(
    payload: &InstallationUpgradeTaskReportPayload,
) -> Result<(), AppError> {
    let task_id = payload.task_id.trim();
    if task_id.is_empty() || task_id.len() > 128 {
        return Err(AppError::BadRequest(
            "installation upgrade taskId must be 1-128 characters".into(),
        ));
    }
    if !matches!(payload.status.as_str(), "running" | "success" | "failed") {
        return Err(AppError::BadRequest(
            "installation upgrade status is invalid".into(),
        ));
    }
    if payload
        .target_commit_id
        .as_deref()
        .is_some_and(|value| value.trim().is_empty() || value.len() > 128)
    {
        return Err(AppError::BadRequest(
            "installation upgrade target commit is invalid".into(),
        ));
    }
    if payload.updated_at.trim().is_empty()
        || payload.updated_at.len() > 128
        || DateTime::parse_from_rfc3339(payload.updated_at.trim()).is_err()
    {
        return Err(AppError::BadRequest(
            "installation upgrade updatedAt must be an RFC3339 timestamp".into(),
        ));
    }
    if payload.logs.len() > INSTALLATION_UPGRADE_TASK_MAX_LOGS {
        return Err(AppError::BadRequest(
            "installation upgrade task has too many log entries".into(),
        ));
    }
    for log in &payload.logs {
        if log.task_id != task_id
            || log.message.len() > 4_096
            || log.at.len() > 128
            || !matches!(
                log.level.as_str(),
                "info" | "progress" | "success" | "warn" | "error"
            )
        {
            return Err(AppError::BadRequest(
                "installation upgrade task contains an invalid log entry".into(),
            ));
        }
    }
    let encoded = serde_json::to_vec(payload).map_err(|error| {
        AppError::Internal(format!(
            "encode installation upgrade task report failed: {error}"
        ))
    })?;
    if encoded.len() > INSTALLATION_UPGRADE_TASK_MAX_JSON_BYTES {
        return Err(AppError::BadRequest(
            "installation upgrade task report is too large".into(),
        ));
    }
    Ok(())
}

