fn validate_request_nonce(nonce: &str) -> Result<(), AppError> {
    if nonce.trim() != nonce
        || nonce.len() < 8
        || nonce.len() > 128
        || !nonce
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_'))
    {
        return Err(AppError::BadRequest(
            "nonce must be 8-128 ASCII letters, digits, hyphen, or underscore".into(),
        ));
    }
    Ok(())
}

fn validate_installation_setup_completed_payload(
    payload: &InstallationSetupCompletedPayload,
) -> Result<(), AppError> {
    if payload.protocol_version != 1 {
        return Err(AppError::BadRequest(
            "unsupported installation setup completion protocol version".into(),
        ));
    }

    let parsed_setup_id = Uuid::parse_str(&payload.setup_id)
        .map_err(|_| AppError::BadRequest("setup_id must be a canonical UUID".into()))?;
    if parsed_setup_id.get_version_num() != 4
        || parsed_setup_id.hyphenated().to_string() != payload.setup_id
    {
        return Err(AppError::BadRequest(
            "setup_id must be a canonical lowercase hyphenated UUID v4".into(),
        ));
    }

    let hint = payload.password_hint.as_bytes();
    let valid_edge = |byte: u8| byte.is_ascii_alphanumeric() || byte == b'*';
    if hint.len() != 8
        || !valid_edge(hint[0])
        || !hint[1..7].iter().all(|byte| *byte == b'*')
        || !valid_edge(hint[7])
    {
        return Err(AppError::BadRequest(
            "password_hint must match ^[A-Za-z0-9*]\\*{6}[A-Za-z0-9*]$".into(),
        ));
    }
    Ok(())
}

fn validate_registration_client_fields(platform: &str, app_version: &str) -> Result<(), AppError> {
    let normalized_platform = platform.trim();
    if normalized_platform.is_empty() {
        return Err(AppError::BadRequest("platform is required".into()));
    }
    if normalized_platform.len() > 32 {
        return Err(AppError::BadRequest(
            "platform must be at most 32 bytes".into(),
        ));
    }
    if platform.chars().any(char::is_control) {
        return Err(AppError::BadRequest(
            "platform must not contain control characters".into(),
        ));
    }
    if app_version.len() > 128 {
        return Err(AppError::BadRequest(
            "app_version must be at most 128 bytes".into(),
        ));
    }
    if app_version.chars().any(char::is_control) {
        return Err(AppError::BadRequest(
            "app_version must not contain control characters".into(),
        ));
    }
    Ok(())
}

fn consume_new_identity_admission(
    conn: &Connection,
    source_scope: &str,
    policy: RegistrationAdmissionPolicy,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    let now_ms = now.timestamp_millis();
    let day_ms =
        i64::try_from(StdDuration::from_secs(24 * 60 * 60).as_millis()).unwrap_or(86_400_000);
    conn.execute(
        "DELETE FROM registration_admission_events WHERE occurred_at_ms <= ?1",
        params![now_ms.saturating_sub(day_ms)],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "prune expired registration admission events failed: {error}"
        ))
    })?;

    let mut retry_after_secs = 0_u64;
    for quota in policy.source_new_identity_quotas() {
        retry_after_secs = retry_after_secs.max(registration_quota_retry_after(
            conn,
            "registration_admission_events",
            Some(source_scope),
            quota,
            now_ms,
        )?);
    }
    for quota in policy.global_new_identity_quotas() {
        retry_after_secs = retry_after_secs.max(registration_quota_retry_after(
            conn,
            "registration_admission_events",
            None,
            quota,
            now_ms,
        )?);
    }
    if retry_after_secs > 0 {
        return Err(AppError::RateLimited {
            message: "new installation registration quota exceeded".into(),
            retry_after_secs,
        });
    }

    let watermark = policy.unowned_installation_watermark.max(1);
    let watermark_reached = conn
        .query_row(
            "SELECT 1
             FROM installations i
             WHERE i.owner_verified_at IS NULL
               AND NOT EXISTS (
                   SELECT 1 FROM shares s
                   WHERE s.installation_id = i.id
                     AND s.share_status NOT IN ('deleted', 'expired')
               )
             LIMIT 1 OFFSET ?1",
            params![i64::from(watermark - 1)],
            |_| Ok(()),
        )
        .optional()
        .map_err(|error| {
            AppError::Internal(format!(
                "check unowned installation watermark for registration admission failed: {error}"
            ))
        })?
        .is_some();
    if watermark_reached {
        return Err(AppError::RateLimited {
            message: "new installation capacity reached".into(),
            retry_after_secs: 300,
        });
    }

    conn.execute(
        "INSERT INTO registration_admission_events (source_scope, occurred_at_ms)
         VALUES (?1, ?2)",
        params![source_scope, now_ms],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "record accepted registration identity failed: {error}"
        ))
    })?;
    Ok(())
}

fn consume_new_auth_device_admission(
    conn: &Connection,
    source_scope: &str,
    policy: RegistrationAdmissionPolicy,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    let now_ms = now.timestamp_millis();
    let day_ms =
        i64::try_from(StdDuration::from_secs(24 * 60 * 60).as_millis()).unwrap_or(86_400_000);
    conn.execute(
        "DELETE FROM auth_device_registration_events WHERE occurred_at_ms <= ?1",
        params![now_ms.saturating_sub(day_ms)],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "prune expired auth device admission events failed: {error}"
        ))
    })?;

    let mut retry_after_secs = 0_u64;
    for quota in policy.source_new_identity_quotas() {
        retry_after_secs = retry_after_secs.max(registration_quota_retry_after(
            conn,
            "auth_device_registration_events",
            Some(source_scope),
            quota,
            now_ms,
        )?);
    }
    for quota in policy.global_new_identity_quotas() {
        retry_after_secs = retry_after_secs.max(registration_quota_retry_after(
            conn,
            "auth_device_registration_events",
            None,
            quota,
            now_ms,
        )?);
    }
    if retry_after_secs > 0 {
        return Err(AppError::RateLimited {
            message: "new auth device registration quota exceeded".into(),
            retry_after_secs,
        });
    }
    conn.execute(
        "INSERT INTO auth_device_registration_events (source_scope, occurred_at_ms)
         VALUES (?1, ?2)",
        params![source_scope, now_ms],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "record accepted auth device registration failed: {error}"
        ))
    })?;
    Ok(())
}

fn registration_quota_retry_after(
    conn: &Connection,
    table_name: &str,
    source_scope: Option<&str>,
    quota: RegistrationQuotaWindow,
    now_ms: i64,
) -> Result<u64, AppError> {
    debug_assert!(matches!(
        table_name,
        "registration_admission_events" | "auth_device_registration_events"
    ));
    let window_ms = i64::try_from(quota.duration.as_millis()).unwrap_or(i64::MAX);
    let cutoff_ms = now_ms.saturating_sub(window_ms);
    let count = if let Some(source_scope) = source_scope {
        conn.query_row(
            &format!(
                "SELECT COUNT(*) FROM {table_name}
                 WHERE source_scope = ?1 AND occurred_at_ms > ?2"
            ),
            params![source_scope, cutoff_ms],
            |row| row.get::<_, i64>(0),
        )
    } else {
        conn.query_row(
            &format!("SELECT COUNT(*) FROM {table_name} WHERE occurred_at_ms > ?1"),
            params![cutoff_ms],
            |row| row.get::<_, i64>(0),
        )
    }
    .map_err(|error| {
        AppError::Internal(format!(
            "count rolling registration admission quota failed: {error}"
        ))
    })?;
    let limit = i64::from(quota.limit.max(1));
    if count < limit {
        return Ok(0);
    }

    let offset = count.saturating_sub(limit);
    let releases_at_ms = if let Some(source_scope) = source_scope {
        conn.query_row(
            &format!(
                "SELECT occurred_at_ms FROM {table_name}
                 WHERE source_scope = ?1 AND occurred_at_ms > ?2
                 ORDER BY occurred_at_ms, id
                 LIMIT 1 OFFSET ?3"
            ),
            params![source_scope, cutoff_ms, offset],
            |row| row.get::<_, i64>(0),
        )
    } else {
        conn.query_row(
            &format!(
                "SELECT occurred_at_ms FROM {table_name}
                 WHERE occurred_at_ms > ?1
                 ORDER BY occurred_at_ms, id
                 LIMIT 1 OFFSET ?2"
            ),
            params![cutoff_ms, offset],
            |row| row.get::<_, i64>(0),
        )
    }
    .map_err(|error| {
        AppError::Internal(format!(
            "read rolling registration quota release time failed: {error}"
        ))
    })?;
    let remaining_ms = releases_at_ms
        .saturating_add(window_ms)
        .saturating_sub(now_ms);
    Ok(u64::try_from(remaining_ms.saturating_add(999) / 1_000)
        .unwrap_or(u64::MAX)
        .max(1))
}

fn insert_installation_notification_baseline(
    conn: &Connection,
    installation_id: &str,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    let now = now.to_rfc3339();
    conn.execute(
        "INSERT OR IGNORE INTO installation_notification_state (
            installation_id, monitoring_enabled, presence_state,
            created_at, updated_at
         ) VALUES (?1, 0, 'unknown', ?2, ?2)",
        params![installation_id, now],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "insert installation notification baseline failed: {error}"
        ))
    })?;
    Ok(())
}

fn record_installation_heartbeat_presence(
    conn: &Connection,
    installation: &Installation,
    now: DateTime<Utc>,
    boot_id: Option<&str>,
) -> Result<(), AppError> {
    insert_installation_notification_baseline(conn, &installation.id, now)?;

    let timestamp = now.to_rfc3339();
    conn.execute(
        "UPDATE installation_notification_state
         SET monitoring_enabled = CASE WHEN ?3 = 1 THEN 1 ELSE monitoring_enabled END,
             presence_state = CASE
                 WHEN presence_state = 'offline' THEN 'recovering'
                 WHEN presence_state = 'unknown' THEN 'online'
                 ELSE presence_state
             END,
             last_heartbeat_at = ?2,
             last_boot_id = COALESCE(?4, last_boot_id),
             offline_candidate_since = NULL,
             recovery_candidate_since = CASE
                 WHEN presence_state = 'offline' THEN ?2
                 WHEN presence_state = 'recovering' THEN COALESCE(recovery_candidate_since, ?2)
                 ELSE recovery_candidate_since
             END,
             updated_at = ?2
         WHERE installation_id = ?1",
        params![
            installation.id,
            timestamp,
            i64::from(installation.client_activated_at.is_some()),
            boot_id
        ],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "update authenticated installation presence failed: {error}"
        ))
    })?;

    Ok(())
}

#[cfg(test)]
fn registration_overflow_should_capture_tx(
    conn: &Connection,
    now: DateTime<Utc>,
) -> Result<bool, AppError> {
    let active = conn
        .query_row(
            "SELECT registration_overflow_active
             FROM client_notification_runtime WHERE id = 1",
            [],
            |row| row.get::<_, i64>(0),
        )
        .optional()
        .map_err(|error| {
            AppError::Internal(format!(
                "read registration notification overflow state failed: {error}"
            ))
        })?
        .unwrap_or(0)
        != 0;
    let active_event_count = conn
        .query_row(
            "SELECT COUNT(*)
             FROM client_notification_events e
             WHERE e.kind IN ('client_registered', 'client_registration_overflow')
               AND (
                   e.status IN ('pending', 'awaiting_owner', 'awaiting_setup')
                   OR (e.status = 'batched' AND EXISTS (
                       SELECT 1
                       FROM notification_delivery_items bi
                       INNER JOIN notification_deliveries b ON b.id = bi.batch_id
                       WHERE bi.event_id = e.id
                         AND b.notification_lane = 'registration'
                         AND b.status IN ('pending', 'claimed', 'retry', 'blocked_config')
                   ))
               )",
            [],
            |row| row.get::<_, i64>(0),
        )
        .map_err(|error| {
            AppError::Internal(format!(
                "count active registration notification events failed: {error}"
            ))
        })?;
    let active_batch_count = conn
        .query_row(
            "SELECT COUNT(*) FROM notification_deliveries
             WHERE notification_lane = 'registration'
               AND status IN ('pending', 'claimed', 'retry', 'blocked_config')",
            [],
            |row| row.get::<_, i64>(0),
        )
        .map_err(|error| {
            AppError::Internal(format!(
                "count active registration notification batches failed: {error}"
            ))
        })?;
    let should_capture = if active {
        active_event_count >= CLIENT_NOTIFICATION_REGISTRATION_EVENT_LOW_WATERMARK
            || active_batch_count >= CLIENT_NOTIFICATION_REGISTRATION_BATCH_LOW_WATERMARK
    } else {
        active_event_count >= CLIENT_NOTIFICATION_REGISTRATION_EVENT_HIGH_WATERMARK
            || active_batch_count >= CLIENT_NOTIFICATION_REGISTRATION_BATCH_HIGH_WATERMARK
    };
    if should_capture != active {
        conn.execute(
            "UPDATE client_notification_runtime
             SET registration_overflow_active = ?1, updated_at = ?2
             WHERE id = 1",
            params![i64::from(should_capture), now.to_rfc3339()],
        )
        .map_err(|error| {
            AppError::Internal(format!(
                "update registration notification overflow state failed: {error}"
            ))
        })?;
    }
    Ok(should_capture)
}

#[cfg(test)]
fn record_registration_notification_overflow_tx(
    conn: &Connection,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    let window_start_seconds = now
        .timestamp()
        .div_euclid(CLIENT_NOTIFICATION_REGISTRATION_OVERFLOW_WINDOW_SECS)
        * CLIENT_NOTIFICATION_REGISTRATION_OVERFLOW_WINDOW_SECS;
    let window_start = Utc
        .timestamp_opt(window_start_seconds, 0)
        .single()
        .ok_or_else(|| {
            AppError::Internal("registration overflow window timestamp is invalid".into())
        })?;
    let window_end =
        window_start + Duration::seconds(CLIENT_NOTIFICATION_REGISTRATION_OVERFLOW_WINDOW_SECS);
    let occurred_at = now.to_rfc3339();
    let changed = conn
        .execute(
            "INSERT INTO client_registration_notification_overflow (
                window_start, window_end, event_count, first_occurred_at,
                last_occurred_at, status, created_at, updated_at
             ) VALUES (?1, ?2, 1, ?3, ?3, 'pending', ?3, ?3)
             ON CONFLICT(window_start) DO UPDATE SET
                event_count = client_registration_notification_overflow.event_count + 1,
                last_occurred_at = excluded.last_occurred_at,
                updated_at = excluded.updated_at
             WHERE client_registration_notification_overflow.status = 'pending'",
            params![
                window_start.to_rfc3339(),
                window_end.to_rfc3339(),
                occurred_at
            ],
        )
        .map_err(|error| {
            AppError::Internal(format!(
                "record registration notification overflow failed: {error}"
            ))
        })?;
    if changed != 1 {
        return Err(AppError::Internal(
            "registration notification overflow window was already materialized".into(),
        ));
    }
    Ok(())
}

fn verify_registration_signature(
    public_key: &str,
    input: &RegisterInstallationRequest,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    ensure_tunnel_protocol_epoch(&input.protocol_epoch)?;
    if signed_request_timestamp_is_stale(now, input.timestamp_ms) {
        return Err(AppError::Unauthorized("stale registration request".into()));
    }
    let payload = format!(
        "{PROTOCOL_EPOCH}\nregister_installation\n{}\n{}\n{}\n{}\n{}",
        input.public_key.trim(),
        input.platform.trim(),
        input.app_version,
        input.instance_nonce,
        input.timestamp_ms
    );
    verify_detached_signature(public_key, payload.as_bytes(), &input.signature)
}

fn verify_auth_device_registration_signature(
    public_key: &str,
    input: &RegisterAuthDeviceRequest,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    ensure_tunnel_protocol_epoch(&input.protocol_epoch)?;
    if signed_request_timestamp_is_stale(now, input.timestamp_ms) {
        return Err(AppError::Unauthorized(
            "stale auth device registration request".into(),
        ));
    }
    let payload = format!(
        "{PROTOCOL_EPOCH}\nregister_auth_device\n{}\n{}\n{}\n{}\n{}\n{}",
        input.public_key.trim(),
        input.kind.trim(),
        input.platform.trim(),
        input.app_version,
        input.instance_nonce,
        input.timestamp_ms
    );
    verify_detached_signature(public_key, payload.as_bytes(), &input.signature)
}

fn consume_identity_registration_nonce(
    conn: &Connection,
    identity_kind: &str,
    public_key: &str,
    nonce: &str,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    let public_key_hash = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .encode(Sha256::digest(public_key.trim().as_bytes()));
    conn.execute(
        "INSERT INTO identity_registration_nonces (
            identity_kind, public_key_hash, nonce, created_at
         ) VALUES (?1, ?2, ?3, ?4)",
        params![identity_kind, public_key_hash, nonce, now.to_rfc3339()],
    )
    .map_err(|error| {
        let text = error.to_string();
        if text.contains("UNIQUE constraint failed")
            || text.contains("identity_registration_nonces")
        {
            AppError::Unauthorized("registration nonce already used".into())
        } else {
            AppError::Internal(format!("store registration nonce failed: {text}"))
        }
    })?;
    Ok(())
}

fn signed_request_timestamp_is_stale(now: DateTime<Utc>, timestamp_ms: i64) -> bool {
    now.timestamp_millis().abs_diff(timestamp_ms) > SIGNED_REQUEST_MAX_SKEW_MS as u64
}

fn retire_reclaimable_route_candidates_tx(
    conn: &Connection,
    router_id: &str,
    route_id: &str,
    installation_id: &str,
    new_generation: u64,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    let now_text = now.to_rfc3339();
    conn.execute(
        "UPDATE leases
         SET state = 'retired', retired_at = ?5
         WHERE router_id = ?1 AND route_id = ?2 AND installation_id = ?3
           AND state IN ('issued', 'authenticated', 'ready')
           AND expires_at > ?5
           AND (
             generation < ?4
             OR (state = 'issued' AND used_at IS NULL)
           )",
        params![
            router_id,
            route_id,
            installation_id,
            i64::try_from(new_generation).unwrap_or(i64::MAX),
            now_text,
        ],
    )
    .map_err(|error| {
        AppError::Internal(format!(
            "retire reclaimable route candidates failed: {error}"
        ))
    })?;
    Ok(())
}

fn verify_issue_lease_request(
    conn: &Connection,
    public_key: &str,
    input: &IssueLeaseRequest,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    ensure_tunnel_protocol_epoch(&input.protocol_epoch)?;
    if signed_request_timestamp_is_stale(now, input.timestamp_ms) {
        return Err(AppError::Unauthorized("stale lease request".into()));
    }
    verify_issue_lease_signature(public_key, input)?;
    consume_authenticated_installation_nonce(
        conn,
        &input.installation_id,
        "tunnel_lease_issue",
        &input.nonce,
        now,
    )
}

fn verify_issue_lease_signature(
    public_key: &str,
    input: &IssueLeaseRequest,
) -> Result<(), AppError> {
    validate_request_nonce(&input.nonce)?;
    let payload = IssueLeaseSignaturePayload {
        protocol_epoch: &input.protocol_epoch,
        router_id: &input.router_id,
        route_id: &input.route_id,
        rotation_id: &input.rotation_id,
        generation: input.generation,
        expected_generation: input.expected_generation,
        requested_subdomain: &input.requested_subdomain,
        tunnel_type: &input.tunnel_type,
        share: issue_lease_signature_share(input),
    };
    verify_tunnel_signed_payload(
        public_key,
        &input.installation_id,
        "tunnel_lease_issue",
        &payload,
        input.timestamp_ms,
        &input.nonce,
        &input.signature,
    )
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct IssueLeaseSignaturePayload<'a> {
    protocol_epoch: &'a str,
    router_id: &'a str,
    route_id: &'a str,
    rotation_id: &'a str,
    generation: u64,
    expected_generation: u64,
    requested_subdomain: &'a str,
    tunnel_type: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    share: Option<IssueLeaseSignatureShare<'a>>,
}

#[derive(Serialize)]
#[serde(untagged)]
enum IssueLeaseSignatureShare<'a> {
    Raw(&'a serde_json::value::RawValue),
    Parsed(&'a ShareDescriptor),
}

fn issue_lease_signature_share(input: &IssueLeaseRequest) -> Option<IssueLeaseSignatureShare<'_>> {
    input
        .signed_share
        .as_deref()
        .map(IssueLeaseSignatureShare::Raw)
        .or_else(|| input.share.as_ref().map(IssueLeaseSignatureShare::Parsed))
}

fn ensure_tunnel_protocol_epoch(protocol_epoch: &str) -> Result<(), AppError> {
    if protocol_epoch != PROTOCOL_EPOCH {
        return Err(AppError::BadRequest(format!(
            "unsupported protocolEpoch; expected {PROTOCOL_EPOCH}"
        )));
    }
    Ok(())
}

fn tunnel_router_id(config: &Config) -> Result<String, AppError> {
    tunnel_domain_host(&config.tunnel_domain)
        .ok_or_else(|| AppError::Internal("tunnel domain does not contain a router host".into()))
}

fn ensure_tunnel_router_id(config: &Config, router_id: &str) -> Result<(), AppError> {
    let expected = tunnel_router_id(config)?;
    if router_id != expected {
        return Err(AppError::BadRequest(format!(
            "routerId does not match this Router; expected {expected}"
        )));
    }
    Ok(())
}

fn validate_tunnel_route_id(route_id: &str) -> Result<String, AppError> {
    let original = route_id;
    let route_id = original.trim();
    if route_id.is_empty()
        || route_id != original
        || route_id.len() > 128
        || !route_id.is_ascii()
        || !route_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b':' | b'_' | b'-'))
    {
        return Err(AppError::BadRequest(
            "routeId must be 1-128 ASCII letters, digits, ':', '_' or '-'".into(),
        ));
    }
    Ok(route_id.to_string())
}

fn verify_detached_signature(
    public_key: &str,
    payload: &[u8],
    signature: &str,
) -> Result<(), AppError> {
    let key_bytes = base64::engine::general_purpose::STANDARD
        .decode(public_key)
        .map_err(|_| AppError::Unauthorized("invalid stored public key".into()))?;
    let key_array: [u8; 32] = key_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid public key length".into()))?;
    let verifying_key = VerifyingKey::from_bytes(&key_array)
        .map_err(|_| AppError::Unauthorized("invalid public key".into()))?;

    let sig_bytes = base64::engine::general_purpose::STANDARD
        .decode(signature)
        .map_err(|_| AppError::Unauthorized("invalid signature".into()))?;
    let sig_array: [u8; 64] = sig_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid signature length".into()))?;
    let signature = Signature::from_bytes(&sig_array);

    verifying_key
        .verify(payload, &signature)
        .map_err(|_| AppError::Unauthorized("signature verification failed".into()))
}

fn verify_signed_share_request<T: Serialize>(
    conn: &Connection,
    public_key: &str,
    installation_id: &str,
    action: &str,
    payload: &T,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let now = Utc::now();
    if signed_request_timestamp_is_stale(now, timestamp_ms) {
        return Err(AppError::Unauthorized("stale signed request".into()));
    }

    verify_signed_payload(
        public_key,
        installation_id,
        action,
        payload,
        timestamp_ms,
        nonce,
        signature,
    )?;
    consume_authenticated_installation_nonce(conn, installation_id, action, nonce, now)
}

fn verify_signed_tunnel_request<T: Serialize>(
    conn: &Connection,
    public_key: &str,
    installation_id: &str,
    action: &str,
    payload: &T,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let now = Utc::now();
    if signed_request_timestamp_is_stale(now, timestamp_ms) {
        return Err(AppError::Unauthorized("stale signed tunnel request".into()));
    }
    verify_tunnel_signed_payload(
        public_key,
        installation_id,
        action,
        payload,
        timestamp_ms,
        nonce,
        signature,
    )?;
    consume_authenticated_installation_nonce(conn, installation_id, action, nonce, now)
}

fn verify_signed_gateway_request(
    conn: &Connection,
    public_key: &str,
    gateway_id: &str,
    action: &str,
    body_sha256_hex: &str,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let now = Utc::now();
    if signed_request_timestamp_is_stale(now, timestamp_ms) {
        return Err(AppError::Unauthorized(
            "stale signed gateway request".into(),
        ));
    }
    verify_gateway_signature(
        public_key,
        gateway_id,
        action,
        body_sha256_hex,
        timestamp_ms,
        nonce,
        signature,
    )?;
    consume_request_nonce(conn, gateway_id, action, nonce, now)
}

fn verify_share_claim_request(
    conn: &Connection,
    public_key: &str,
    installation_id: &str,
    share: &ShareDescriptor,
    claim: Option<&ShareClaimPayload>,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let now = Utc::now();
    if signed_request_timestamp_is_stale(now, timestamp_ms) {
        return Err(AppError::Unauthorized("stale signed request".into()));
    }

    let derived_claim = share_claim_payload(share);
    if let Some(claim) = claim {
        if claim.share_id != derived_claim.share_id
            || claim.subdomain != derived_claim.subdomain
            || claim.owner_email != derived_claim.owner_email
        {
            return Err(AppError::BadRequest(
                "share claim does not match share metadata".into(),
            ));
        }
    }

    let claim_payload = claim.unwrap_or(&derived_claim);
    let new_result = verify_signed_payload(
        public_key,
        installation_id,
        "share_claim_subdomain",
        claim_payload,
        timestamp_ms,
        nonce,
        signature,
    );
    if let Err(new_err) = new_result {
        verify_signed_payload(
            public_key,
            installation_id,
            "share_claim_subdomain",
            share,
            timestamp_ms,
            nonce,
            signature,
        )
        .map_err(|_| new_err)?;
    }

    consume_authenticated_installation_nonce(
        conn,
        installation_id,
        "share_claim_subdomain",
        nonce,
        now,
    )
}

fn consume_authenticated_installation_nonce(
    conn: &Connection,
    installation_id: &str,
    action: &str,
    nonce: &str,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    conn.execute_batch("SAVEPOINT authenticated_installation_request")
        .map_err(|error| {
            AppError::Internal(format!(
                "begin authenticated presence savepoint failed: {error}"
            ))
        })?;
    let result = (|| {
        consume_request_nonce(conn, installation_id, action, nonce, now)?;
        let updated = conn
            .execute(
                "UPDATE installations SET last_seen_at = ?2
                 WHERE id = ?1 AND lifecycle = 'active'",
                params![installation_id, now.to_rfc3339()],
            )
            .map_err(|error| {
                AppError::Internal(format!(
                    "update authenticated installation activity failed: {error}"
                ))
            })?;
        if updated != 1 {
            return Err(AppError::Unauthorized("installation not found".into()));
        }
        Ok(())
    })();
    match result {
        Ok(()) => conn
            .execute_batch("RELEASE authenticated_installation_request")
            .map_err(|error| {
                AppError::Internal(format!(
                    "commit authenticated presence savepoint failed: {error}"
                ))
            }),
        Err(error) => {
            let _ = conn.execute_batch(
                "ROLLBACK TO authenticated_installation_request; RELEASE authenticated_installation_request",
            );
            Err(error)
        }
    }
}

fn share_claim_payload(share: &ShareDescriptor) -> ShareClaimPayload {
    ShareClaimPayload {
        share_id: share.share_id.clone(),
        subdomain: share.subdomain.clone(),
        owner_email: share.owner_email.clone(),
    }
}

fn consume_request_nonce(
    conn: &Connection,
    installation_id: &str,
    action: &str,
    nonce: &str,
    now: DateTime<Utc>,
) -> Result<(), AppError> {
    conn.execute(
        "INSERT INTO request_nonces (installation_id, action, nonce, created_at)
         VALUES (?1, ?2, ?3, ?4)",
        params![installation_id, action, nonce, now.to_rfc3339()],
    )
    .map_err(|err| {
        let text = err.to_string();
        if text.contains("UNIQUE constraint failed")
            || text.contains("request_nonces.installation_id")
        {
            AppError::Unauthorized("nonce already used".into())
        } else {
            AppError::Internal(format!("store request nonce failed: {text}"))
        }
    })?;
    Ok(())
}

fn verify_signed_payload<T: Serialize>(
    public_key: &str,
    installation_id: &str,
    action: &str,
    payload: &T,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let payload_json = serde_json::to_string(payload)
        .map_err(|_| AppError::Unauthorized("invalid signed payload".into()))?;
    verify_signed_payload_json(
        public_key,
        installation_id,
        action,
        &payload_json,
        timestamp_ms,
        nonce,
        signature,
    )
}

fn verify_signed_payload_json(
    public_key: &str,
    installation_id: &str,
    action: &str,
    payload_json: &str,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let key_bytes = base64::engine::general_purpose::STANDARD
        .decode(public_key)
        .map_err(|_| AppError::Unauthorized("invalid stored public key".into()))?;
    let key_array: [u8; 32] = key_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid public key length".into()))?;
    let verifying_key = VerifyingKey::from_bytes(&key_array)
        .map_err(|_| AppError::Unauthorized("invalid public key".into()))?;

    let sig_bytes = base64::engine::general_purpose::STANDARD
        .decode(signature)
        .map_err(|_| AppError::Unauthorized("invalid signature".into()))?;
    let sig_array: [u8; 64] = sig_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid signature length".into()))?;
    let signature = Signature::from_bytes(&sig_array);

    let payload = format!(
        "{PROTOCOL_EPOCH}\n{}\n{}\n{}\n{}\n{}",
        installation_id, action, payload_json, timestamp_ms, nonce
    );
    verifying_key
        .verify(payload.as_bytes(), &signature)
        .map_err(|_| AppError::Unauthorized("signature verification failed".into()))
}

fn installation_upgrade_task_report_payload_json(
    payload: &InstallationUpgradeTaskReportPayload,
) -> Result<String, AppError> {
    serde_json::to_string(&CanonicalInstallationUpgradeTaskReportPayload(payload))
        .map_err(|_| AppError::Unauthorized("invalid signed upgrade payload".into()))
}

struct CanonicalInstallationUpgradeTaskReportPayload<'a>(&'a InstallationUpgradeTaskReportPayload);

impl Serialize for CanonicalInstallationUpgradeTaskReportPayload<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let payload = self.0;
        let mut state = serializer.serialize_struct("InstallationUpgradeTaskReportPayload", 7)?;
        state.serialize_field("taskId", &payload.task_id)?;
        state.serialize_field("status", &payload.status)?;
        state.serialize_field("restartPending", &payload.restart_pending)?;
        state.serialize_field("logs", &payload.logs)?;
        state.serialize_field("targetCommitId", &payload.target_commit_id)?;
        state.serialize_field("restartAfter", &payload.restart_after)?;
        state.serialize_field("updatedAt", &payload.updated_at)?;
        state.end()
    }
}

fn verify_signed_installation_upgrade_task_report(
    conn: &Connection,
    public_key: &str,
    installation_id: &str,
    payload: &InstallationUpgradeTaskReportPayload,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let now = Utc::now();
    if signed_request_timestamp_is_stale(now, timestamp_ms) {
        return Err(AppError::Unauthorized("stale signed request".into()));
    }
    let payload_json = installation_upgrade_task_report_payload_json(payload)?;
    verify_signed_payload_json(
        public_key,
        installation_id,
        INSTALLATION_UPGRADE_TASK_REPORT_ACTION,
        &payload_json,
        timestamp_ms,
        nonce,
        signature,
    )?;
    consume_authenticated_installation_nonce(
        conn,
        installation_id,
        INSTALLATION_UPGRADE_TASK_REPORT_ACTION,
        nonce,
        now,
    )
}

fn verify_tunnel_signed_payload<T: Serialize>(
    public_key: &str,
    installation_id: &str,
    action: &str,
    payload: &T,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let key_bytes = base64::engine::general_purpose::STANDARD
        .decode(public_key)
        .map_err(|_| AppError::Unauthorized("invalid stored public key".into()))?;
    let key_array: [u8; 32] = key_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid public key length".into()))?;
    let verifying_key = VerifyingKey::from_bytes(&key_array)
        .map_err(|_| AppError::Unauthorized("invalid public key".into()))?;
    let sig_bytes = base64::engine::general_purpose::STANDARD
        .decode(signature)
        .map_err(|_| AppError::Unauthorized("invalid signature".into()))?;
    let sig_array: [u8; 64] = sig_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid signature length".into()))?;
    let signature = Signature::from_bytes(&sig_array);
    let payload_json = serde_json::to_string(payload)
        .map_err(|_| AppError::Unauthorized("invalid signed tunnel payload".into()))?;
    let canonical = format!(
        "{PROTOCOL_EPOCH}\n{installation_id}\n{action}\n{payload_json}\n{timestamp_ms}\n{nonce}"
    );
    verifying_key
        .verify(canonical.as_bytes(), &signature)
        .map_err(|_| AppError::Unauthorized("signature verification failed".into()))
}

fn verify_gateway_signature(
    public_key: &str,
    gateway_id: &str,
    action: &str,
    body_sha256_hex: &str,
    timestamp_ms: i64,
    nonce: &str,
    signature: &str,
) -> Result<(), AppError> {
    let verifying_key = ed25519_verifying_key(public_key)?;
    let sig_bytes = base64::engine::general_purpose::STANDARD
        .decode(signature)
        .map_err(|_| AppError::Unauthorized("invalid gateway signature".into()))?;
    let sig_array: [u8; 64] = sig_bytes
        .try_into()
        .map_err(|_| AppError::Unauthorized("invalid gateway signature length".into()))?;
    let signature = Signature::from_bytes(&sig_array);
    let payload = format!(
        "{}\n{}\n{}\n{}\n{}",
        gateway_id, action, body_sha256_hex, timestamp_ms, nonce
    );
    verifying_key
        .verify(payload.as_bytes(), &signature)
        .map_err(|_| AppError::Unauthorized("gateway signature verification failed".into()))
}

fn validate_ed25519_public_key(public_key: &str) -> Result<(), AppError> {
    ed25519_verifying_key(public_key).map(|_| ())
}

fn ed25519_verifying_key(public_key: &str) -> Result<VerifyingKey, AppError> {
    let key_bytes = base64::engine::general_purpose::STANDARD
        .decode(public_key)
        .map_err(|_| AppError::BadRequest("invalid public key".into()))?;
    let key_array: [u8; 32] = key_bytes
        .try_into()
        .map_err(|_| AppError::BadRequest("invalid public key length".into()))?;
    VerifyingKey::from_bytes(&key_array)
        .map_err(|_| AppError::BadRequest("invalid public key".into()))
}

async fn redeem_verification_token(
    config: &Config,
    verification_token: &str,
) -> Result<VerificationRedeemResponse, AppError> {
    let url = format!(
        "{}/v1/verification/email/redeem",
        config.verification_service_base_url.trim_end_matches('/')
    );
    let client = reqwest::Client::builder()
        .timeout(StdDuration::from_secs(20))
        .build()
        .map_err(|e| AppError::Internal(format!("create verification client failed: {e}")))?;
    let mut request = client.post(&url).json(&serde_json::json!({
        "verificationToken": verification_token,
        "purpose": AUTH_PURPOSE_LOGIN,
    }));
    if let Some(api_key) = config.verification_service_api_key.as_deref() {
        request = request.bearer_auth(api_key);
    }
    let response = request.send().await.map_err(|e| {
        AppError::Internal(format!("redeem verification token request failed: {e}"))
    })?;
    if !response.status().is_success() {
        let status = response.status();
        let body = response
            .text()
            .await
            .unwrap_or_else(|_| format!("HTTP {status}"));
        return Err(AppError::Unauthorized(format!(
            "redeem verification token failed: {body}"
        )));
    }
    response
        .json::<VerificationRedeemResponse>()
        .await
        .map_err(|e| AppError::Internal(format!("parse verification redeem response failed: {e}")))
}

#[derive(Debug, Clone)]
struct EmailLoginChallenge {
    id: String,
    code_hash: String,
    attempt_count: i64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EmailVerificationRejectionReason {
    Expired,
    Consumed,
    SourceMismatch,
    NotFound,
    InvalidCode,
    AttemptLimit,
}

impl EmailVerificationRejectionReason {
    fn as_str(self) -> &'static str {
        match self {
            Self::Expired => "expired",
            Self::Consumed => "consumed",
            Self::SourceMismatch => "source_mismatch",
            Self::NotFound => "not_found",
            Self::InvalidCode => "invalid_code",
            Self::AttemptLimit => "attempt_limit",
        }
    }
}

fn log_email_verification_rejection(reason: EmailVerificationRejectionReason) {
    tracing::warn!(
        reason = reason.as_str(),
        "email verification challenge rejected"
    );
}

fn normalize_email(value: &str) -> Result<String, AppError> {
    let email = value.trim().to_ascii_lowercase();
    let Some((local, domain)) = email.split_once('@') else {
        return Err(AppError::BadRequest("invalid email".into()));
    };
    if local.is_empty() || domain.is_empty() || !domain.contains('.') {
        return Err(AppError::BadRequest("invalid email".into()));
    }
    if email.len() > 254 {
        return Err(AppError::BadRequest("invalid email".into()));
    }
    Ok(email)
}

fn mask_email(email: &str) -> String {
    let Some((local, domain)) = email.split_once('@') else {
        return "***".into();
    };
    let mut chars = local.chars();
    let first = chars.next().unwrap_or('*');
    let last = local.chars().last().unwrap_or(first);
    format!("{first}***{last}@{domain}")
}

fn hash_token(value: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(value.as_bytes());
    base64::engine::general_purpose::STANDARD.encode(hasher.finalize())
}

fn truncate_error(value: &str, max_chars: usize) -> String {
    let mut output = value.chars().take(max_chars).collect::<String>();
    if value.chars().count() > max_chars {
        output.push_str("...");
    }
    output
}

fn generate_secret(len: usize) -> String {
    Alphanumeric.sample_string(&mut rand::thread_rng(), len)
}

fn generate_numeric_code(len: usize) -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    (0..len)
        .map(|_| char::from(b'0' + rng.gen_range(0..10)))
        .collect()
}

fn parse_string_vec(value: Option<String>) -> Result<Vec<String>, crate::db::Error> {
    let Some(value) = value else {
        return Ok(Vec::new());
    };
    if value.trim().is_empty() {
        return Ok(Vec::new());
    }
    serde_json::from_str(&value).map_err(|err| {
        crate::db::Error::FromSqlConversionFailure(0, crate::db::types::Type::Text, Box::new(err))
    })
}

async fn send_login_code_email(
    resend: &Resend,
    config: &Config,
    email: &str,
    code: &str,
    ttl_secs: i64,
) -> Result<Option<String>, AppError> {
    let from = resend_from_address(config)?;
    let ttl_minutes = (ttl_secs / 60).max(1);
    let body = format!(
        "<p style=\"margin:0 0 18px;color:#475569;font-size:15px;line-height:1.6\">Use this code to finish signing in to <span translate=\"no\">TokenSwitch</span>.</p>\
         {}\
         <p style=\"margin:0;color:#64748b;font-size:14px;line-height:1.6\">This code expires in {} minutes. If you did not request it, you can safely ignore this email.</p>",
        render_verification_code_block(code),
        ttl_minutes
    );
    let html = render_email_layout(
        "Your verification code",
        "Use this code to finish signing in.",
        &body,
    );
    let mut message =
        CreateEmailBaseOptions::new(&from, [email], "Your TokenSwitch verification code")
            .with_html(&html);
    if let Some(reply_to) = config.resend_reply_to.as_deref() {
        message = message.with_reply(reply_to);
    }
    let response = resend
        .emails
        .send(message)
        .await
        .map_err(|e| AppError::Internal(format!("send verification email failed: {e}")))?;
    Ok(Some(response.id.to_string()))
}

fn resend_from_address(config: &Config) -> Result<String, AppError> {
    let from = config
        .resend_from
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| AppError::Internal("resend from address is not configured".into()))?;
    let from = from
        .chars()
        .filter(|ch| !matches!(ch, '\r' | '\n'))
        .collect::<String>();
    let from = from.trim();

    if from.contains('<') && from.contains('>') {
        return Ok(from.to_string());
    }

    if !from.contains('@') {
        return Err(AppError::Internal(
            "resend from address must be an email address".into(),
        ));
    }

    let name = config
        .resend_from_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("TokenSwitch");
    Ok(format!("{} <{}>", sanitize_email_display_name(name), from))
}

fn sanitize_email_display_name(value: &str) -> String {
    let sanitized = value
        .chars()
        .filter(|ch| !matches!(ch, '\r' | '\n' | '<' | '>' | '"'))
        .collect::<String>()
        .trim()
        .to_string();
    if sanitized.is_empty() {
        "TokenSwitch".to_string()
    } else {
        sanitized
    }
}

fn render_verification_code_block(code: &str) -> String {
    format!(
        "<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"margin:22px 0;border-collapse:separate\">\
           <tr>\
             <td align=\"center\" translate=\"no\" style=\"padding:18px 20px;border-radius:12px;background:#0f172a;color:#ffffff;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,'Liberation Mono','Courier New',monospace;font-size:32px;line-height:1.15;font-weight:700;letter-spacing:8px;text-align:center;white-space:nowrap\">{}</td>\
           </tr>\
         </table>",
        escape_html(code)
    )
}

