    #[test]
    fn share_support_can_disable_a_bound_app_but_not_all() {
        let bindings = BTreeMap::from([
            ("claude".to_string(), "provider-claude".to_string()),
            ("codex".to_string(), "provider-codex".to_string()),
        ]);
        let normalized = normalize_share_settings_patch(
            ShareSettingsPatch {
                support: Some(ShareSupport {
                    claude: true,
                    codex: false,
                    gemini: false,
                }),
                ..Default::default()
            },
            Some("owner@example.com"),
            Some(&bindings),
            None,
            None,
        )
        .expect("disable one bound app");
        assert_eq!(
            normalized.support,
            Some(ShareSupport {
                claude: true,
                codex: false,
                gemini: false,
            })
        );

        let rejected = normalize_share_settings_patch(
            ShareSettingsPatch {
                support: Some(ShareSupport {
                    claude: false,
                    codex: false,
                    gemini: false,
                }),
                ..Default::default()
            },
            Some("owner@example.com"),
            Some(&bindings),
            None,
            None,
        );
        assert!(matches!(rejected, Err(AppError::BadRequest(_))));

        let rebound = normalize_share_settings_patch(
            ShareSettingsPatch {
                support: Some(ShareSupport {
                    claude: true,
                    codex: true,
                    gemini: false,
                }),
                ..Default::default()
            },
            Some("owner@example.com"),
            Some(&BTreeMap::from([(
                "claude".to_string(),
                "provider-claude".to_string(),
            )])),
            None,
            Some(&["claude".to_string(), "codex".to_string()]),
        )
        .expect("re-enable a family-supported unbound app");
        assert_eq!(
            rebound.support,
            Some(ShareSupport {
                claude: true,
                codex: true,
                gemini: false,
            })
        );
    }

