    const TEST_CLIENT_SUBDOMAIN: &str = "client-alpha";
    const TEST_CLIENT_SUBDOMAIN_BETA: &str = "client-beta";

    fn test_share_host(slug: &str) -> String {
        let mut slug = slug.to_string();
        while slug.len() < crate::namespace::PUBLIC_SLUG_MIN_LEN {
            slug.push('x');
        }
        format!("{slug}--{TEST_CLIENT_SUBDOMAIN}")
    }

    async fn insert_share(
        store: &AppStore,
        installation_id: &str,
        share_id: &str,
        subdomain: &str,
        share_status: &str,
    ) {
        // Default to all 3 apps bound so existing tests (which were written
        // before the per-binding model_health filter landed) keep getting
        // their snapshot intakes accepted. Tests that exercise the filter
        // call `set_share_bindings` afterwards to narrow this.
        let default_bindings = serde_json::json!({
            "claude": "provider-test",
            "codex": "provider-test",
            "gemini": "provider-test",
        })
        .to_string();
        let now = Utc::now();
        let expires = now + Duration::hours(1);
        let conn = store.conn.lock().await;
        conn.execute(
            "INSERT INTO shares (
                share_id, capacity_pool_id, installation_id, share_name, owner_email,
                description, subdomain, app_type, provider_id,
                enabled_claude, enabled_codex, enabled_gemini, token_limit, parallel_limit,
                tokens_used, requests_count, share_status, created_at, expires_at, bindings_json, updated_at
             ) VALUES (?1, ?1, ?2, ?3, ?4, NULL, ?5, 'proxy', NULL, 1, 1, 1, 1000, 3, 0, 0, ?6, ?7, ?8, ?9, ?7)",
            params![
                share_id,
                installation_id,
                format!("share-{share_id}"),
                "owner@example.com",
                subdomain,
                share_status,
                now.to_rfc3339(),
                expires.to_rfc3339(),
                default_bindings,
            ],
        )
        .expect("insert share");
        for app in ["claude", "codex", "gemini"] {
            conn.execute(
                "INSERT INTO share_bindings (share_id, app_type, provider_id) VALUES (?1, ?2, 'provider-test')",
                params![share_id, app],
            )
            .expect("insert share binding");
        }
        conn.execute(
            "INSERT OR IGNORE INTO public_hosts (
                label, route_id, kind, subject_id, installation_id, target_lane_id,
                lifecycle, revision, created_at, updated_at
             ) VALUES (?1, ?2, 'share', ?3, ?4, ?4, 'active', 1, ?5, ?5)",
            params![
                subdomain,
                format!("share:{share_id}"),
                share_id,
                installation_id,
                now.to_rfc3339(),
            ],
        )
        .expect("insert share public host");
    }

    /// Override the bindings_json on an existing test share. Use for tests
    /// that need a specific subset of apps bound (e.g. share with only
    /// claude bound, to verify the model_health filter drops codex entries).
    async fn set_share_bindings(store: &AppStore, share_id: &str, apps: &[&str]) {
        let map: serde_json::Map<String, serde_json::Value> = apps
            .iter()
            .map(|app| {
                (
                    app.to_string(),
                    serde_json::Value::String("provider-test".into()),
                )
            })
            .collect();
        let bindings = serde_json::Value::Object(map).to_string();
        let conn = store.conn.lock().await;
        conn.execute(
            "UPDATE shares SET bindings_json = ?2 WHERE share_id = ?1",
            params![share_id, bindings],
        )
        .expect("update share bindings_json");
        conn.execute(
            "DELETE FROM share_bindings WHERE share_id = ?1",
            params![share_id],
        )
        .expect("delete previous share bindings");
        for app in apps {
            conn.execute(
                "INSERT INTO share_bindings (share_id, app_type, provider_id) VALUES (?1, ?2, 'provider-test')",
                params![share_id, app],
            )
            .expect("insert replacement share binding");
        }
    }

    async fn set_shareto_users(store: &AppStore, share_id: &str, emails: &[&str]) {
        let conn = store.conn.lock().await;
        let owner_email: String = conn
            .query_row(
                "SELECT owner_email FROM shares WHERE share_id = ?1",
                params![share_id],
                |row| row.get(0),
            )
            .expect("read Share owner");
        let owner_email = owner_email.to_ascii_lowercase();
        let mut grants = BTreeMap::from([(
            owner_email.clone(),
            test_share_user_grant(&owner_email, "owner", 1_000),
        )]);
        for email in emails {
            let email = email.to_ascii_lowercase();
            grants.insert(
                email.clone(),
                test_share_user_grant(&email, "shareto", 1_000),
            );
        }
        conn.execute(
            "UPDATE shares
             SET user_grants_json = ?2, shared_with_emails_json = '[]'
             WHERE share_id = ?1",
            params![
                share_id,
                serde_json::to_string(&grants).expect("serialize Share grants")
            ],
        )
        .expect("update canonical Share grants");
    }

    #[tokio::test]
    async fn default_user_api_token_is_unique_resolvable_and_resettable() {
        let (store, config) = setup_store("user-api-token-lifecycle").await;
        let now = Utc::now();
        let user_id = {
            let conn = store.conn.lock().await;
            let user = upsert_user_by_email(&conn, "owner@example.com", now).expect("upsert user");
            let (first_raw, first_record) =
                ensure_default_user_api_token(&conn, &user.id, now).expect("create api token");
            let first_raw = first_raw.expect("first creation returns raw token");
            assert!(first_raw.starts_with("ccrt_"));
            assert_eq!(first_record.raw_token.as_deref(), Some(first_raw.as_str()));
            assert_eq!(
                first_record.prefix,
                first_raw.chars().take(14).collect::<String>()
            );
            assert_eq!(
                first_record.scopes,
                vec![
                    "share:read".to_string(),
                    "share:write".to_string(),
                    "share:invoke".to_string(),
                    "market:access:read".to_string(),
                    "market:access:write".to_string(),
                    "market:billing:settlement".to_string()
                ]
            );

            let (second_raw, second_record) =
                ensure_default_user_api_token(&conn, &user.id, now).expect("reuse api token");
            assert!(second_raw.is_none());
            assert_eq!(second_record.raw_token.as_deref(), Some(first_raw.as_str()));
            assert_eq!(second_record.prefix, first_record.prefix);

            (user.id, first_raw)
        };
        let old_token = user_id.1;
        let user_id = user_id.0;

        let principal = store
            .resolve_user_api_token(&old_token, "share:invoke")
            .await
            .expect("resolve old token")
            .expect("old token principal");
        assert_eq!(principal.user_id, user_id);
        assert_eq!(principal.email, "owner@example.com");

        let forbidden_scope = store
            .resolve_user_api_token(&old_token, "admin:write")
            .await;
        assert!(matches!(forbidden_scope, Err(AppError::Unauthorized(_))));

        let reset = store
            .reset_default_api_token("Owner@Example.com")
            .await
            .expect("reset default api token");
        assert!(reset.api_token.starts_with("ccrt_"));
        assert_ne!(reset.api_token, old_token);
        assert_eq!(
            reset.token.prefix,
            reset.api_token.chars().take(14).collect::<String>()
        );
        let current = store
            .get_default_api_token("Owner@Example.com")
            .await
            .expect("get default api token");
        assert_eq!(current.api_token.as_deref(), Some(reset.api_token.as_str()));

        assert!(
            store
                .resolve_user_api_token(&old_token, "share:invoke")
                .await
                .expect("old token lookup after reset")
                .is_none()
        );
        assert_eq!(
            store
                .resolve_user_api_token(&reset.api_token, "share:invoke")
                .await
                .expect("new token lookup")
                .expect("new token principal")
                .email,
            "owner@example.com"
        );

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn user_api_token_share_invoke_allows_owner_and_shareto() {
        let (store, config) = setup_store("user-api-token-share-acl").await;
        insert_installation(&store, "inst-1").await;
        insert_share(&store, "inst-1", "share-acl", "acl-sub", "active").await;
        set_shareto_users(&store, "share-acl", &["Shared@Example.com"]).await;

        assert!(
            store
                .user_can_invoke_share("OWNER@example.com", "share-acl", Some("codex"))
                .await
                .expect("owner access")
        );
        assert!(
            store
                .user_can_invoke_share("shared@example.com", "share-acl", Some("codex"))
                .await
                .expect("ShareTo access")
        );
        assert!(
            !store
                .user_can_invoke_share("other@example.com", "share-acl", Some("codex"))
                .await
                .expect("other access")
        );
        assert!(
            !store
                .user_can_invoke_share("owner@example.com", "missing-share", Some("codex"))
                .await
                .expect("missing Share access")
        );
        assert!(
            !store
                .user_can_invoke_share("owner@example.com", "share-acl", None)
                .await
                .expect("missing app is denied")
        );

        let _ = std::fs::remove_file(&config.database.path);
    }

