    #[test]
    fn share_settings_patch_normalizes_user_grants_as_untrusted_input() {
        let owner = test_share_user_grant("OWNER@example.com", "shareto", 1000);
        let user = test_share_user_grant("User@example.com", "owner", 500);
        let normalized = normalize_share_settings_patch(
            ShareSettingsPatch {
                user_grants: Some(BTreeMap::from([
                    ("OWNER@example.com".to_string(), owner),
                    ("User@example.com".to_string(), user),
                ])),
                ..Default::default()
            },
            Some("owner@example.com"),
            Some(&BTreeMap::from([(
                "codex".to_string(),
                "provider-codex".to_string(),
            )])),
            None,
            None,
        )
        .expect("normalize user grants");
        let grants = normalized.user_grants.expect("normalized grants");
        let owner = &grants["owner@example.com"];
        let user = &grants["user@example.com"];

        assert_eq!(owner.role, "owner");
        assert_eq!(user.role, "shareto");
        for grant in [owner, user] {
            assert_eq!(grant.usage, Default::default());
            assert_eq!(grant.created_at_ms, 0);
            assert_eq!(grant.updated_at_ms, 0);
            assert_eq!(grant.revision, 0);
        }
    }

    #[test]
    fn share_settings_patch_preserves_existing_user_grant_usage() {
        let mut existing_owner = test_share_user_grant("owner@example.com", "owner", 1000);
        existing_owner.created_at_ms = 42;
        existing_owner.revision = 7;
        let existing_user = test_share_user_grant("user@example.com", "shareto", 500);
        let existing = BTreeMap::from([
            (existing_owner.email.clone(), existing_owner.clone()),
            (existing_user.email.clone(), existing_user.clone()),
        ]);
        let patch_owner = test_share_user_grant("owner@example.com", "owner", 2000);
        let patch_user = test_share_user_grant("user@example.com", "shareto", 800);
        let normalized = normalize_share_settings_patch(
            ShareSettingsPatch {
                user_grants: Some(BTreeMap::from([
                    (patch_owner.email.clone(), patch_owner),
                    (patch_user.email.clone(), patch_user),
                ])),
                ..Default::default()
            },
            Some("owner@example.com"),
            Some(&BTreeMap::from([(
                "codex".to_string(),
                "provider-codex".to_string(),
            )])),
            Some(&existing),
            None,
        )
        .expect("normalize user grants with existing");
        let grants = normalized.user_grants.expect("normalized grants");
        let owner = &grants["owner@example.com"];
        let user = &grants["user@example.com"];
        assert_eq!(owner.policy.token_limit, Some(2000));
        assert_eq!(owner.usage, existing_owner.usage);
        assert_eq!(owner.created_at_ms, 42);
        assert_eq!(owner.revision, 7);
        assert_eq!(user.usage, existing_user.usage);
        assert_eq!(user.created_at_ms, existing_user.created_at_ms);
        assert_eq!(user.revision, existing_user.revision);
    }

    #[test]
    fn share_settings_patch_cannot_reactivate_revoked_market_grant() {
        let owner = test_share_user_grant("owner@example.com", "owner", 1000);
        let mut revoked = test_share_user_grant("renter@example.com", "shareto", 500);
        revoked.active = false;
        revoked.manager = crate::models::ShareGrantManager::RouterShareMarket;
        revoked.entitlement_id = Some("entitlement-revoked".to_string());
        let existing = BTreeMap::from([
            (owner.email.clone(), owner.clone()),
            (revoked.email.clone(), revoked.clone()),
        ]);
        let mut reactivated = revoked;
        reactivated.active = true;

        let error = normalize_share_settings_patch(
            ShareSettingsPatch {
                user_grants: Some(BTreeMap::from([
                    (owner.email.clone(), owner),
                    (reactivated.email.clone(), reactivated),
                ])),
                ..Default::default()
            },
            Some("owner@example.com"),
            Some(&BTreeMap::from([(
                "codex".to_string(),
                "provider-codex".to_string(),
            )])),
            Some(&existing),
            None,
        )
        .expect_err("ordinary edit must not reactivate revoked market grant");

        assert!(error.to_string().contains("managed users are read-only"));
    }

    #[test]
    fn returned_descriptor_must_exactly_apply_user_grants() {
        let owner = test_share_user_grant("owner@example.com", "owner", 1000);
        let user = test_share_user_grant("user@example.com", "shareto", 500);
        let expected_grants = BTreeMap::from([
            (owner.email.clone(), owner.clone()),
            (user.email.clone(), user.clone()),
        ]);
        let patch = ShareSettingsPatch {
            user_grants: Some(expected_grants.clone()),
            ..Default::default()
        };
        let mut returned = test_share_descriptor("exact-patch", "exact-patch-sub");
        returned.user_grants = expected_grants;

        assert!(validate_returned_share_against_patch(&patch, &returned).is_ok());

        returned.user_grants.remove("user@example.com");
        assert_eq!(
            validate_returned_share_against_patch(&patch, &returned),
            Err("userGrants")
        );
        returned
            .user_grants
            .insert("user@example.com".to_string(), user.clone());
        returned
            .user_grants
            .get_mut("user@example.com")
            .unwrap()
            .policy
            .token_limit = Some(999);
        assert_eq!(
            validate_returned_share_against_patch(&patch, &returned),
            Err("userGrants")
        );
    }

