    #[tokio::test]
    async fn account_usage_consumer_provider_and_global_aggregate_tokens() {
        let (store, config) = setup_store("account-usage-consumer-provider-global").await;
        insert_installation(&store, "inst-account-usage").await;
        insert_share(
            &store,
            "inst-account-usage",
            "share-account-usage",
            "account-usage-sub",
            "active",
        )
        .await;
        {
            let conn = store.conn.lock().await;
            let now = Utc::now().timestamp();
            let mut log = test_share_request_log_entry(
                "req-account-usage",
                "share-account-usage",
                now - 3600,
            );
            log.user_email = Some("caller@example.com".into());
            log.model = "gpt-5".into();
            log.input_tokens = 100;
            log.output_tokens = 40;
            log.cache_read_tokens = 10;
            log.cache_creation_tokens = 0;
            upsert_share_request_log_tx(&conn, "inst-account-usage", log).expect("insert log");
        }

        let consumer = store
            .usage_consumer("caller@example.com", "7d")
            .await
            .expect("consumer usage");
        assert_eq!(consumer.period, "7d");
        assert_eq!(consumer.total_tokens, 150);
        assert_eq!(consumer.models.len(), 1);
        assert_eq!(consumer.models[0].model, "gpt-5");
        assert!(consumer.daily.len() >= 7);

        let provider = store
            .usage_provider("owner@example.com", "7d")
            .await
            .expect("provider usage");
        assert_eq!(provider.total_tokens, 150);
        assert!(!provider.installations.is_empty());
        assert_eq!(
            provider.installations[0].shares[0].share_id,
            "share-account-usage"
        );

        let global = store.usage_global("7d").await.expect("global usage");
        assert_eq!(global.total_tokens, 150);
        assert_eq!(global.models[0].model, "gpt-5");
        let global_json = serde_json::to_value(&global).expect("serialize");
        assert!(global_json.get("cost").is_none());

        // `/v1/public/usage/global` serves this value to anonymous callers, so
        // the payload has to stay aggregate. The caller email and the share are
        // both present in the rows it was built from; neither may survive into
        // the response, under any key.
        let global_text = serde_json::to_string(&global_json).expect("serialize global usage");
        for leaked in [
            "caller@example.com",
            "owner@example.com",
            "share-account-usage",
            "account-usage-sub",
            "inst-account-usage",
        ] {
            assert!(
                !global_text.contains(leaked),
                "global usage payload leaked {leaked}"
            );
        }
        for key in ["email", "userId", "shareId", "installationId", "callers"] {
            assert!(
                !global_text.contains(key),
                "global usage payload exposes identity field {key}"
            );
        }

        let svg = crate::embed_usage::render_global_usage_svg(
            &global,
            &crate::embed_usage::EmbedRenderOptions {
                theme: "dark".into(),
                period: "7d".into(),
                ..Default::default()
            },
            "ustokenswitch.cc",
        );
        assert!(svg.contains("TokenSwitch · ustokenswitch.cc"));
        assert!(svg.contains("?period=24h"));
        assert!(svg.contains("gpt-5"));

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn share_usage_by_email_defaults_to_rolling_24h() {
        let (store, config) = setup_store("share-usage-by-email-24h").await;
        insert_installation(&store, "inst-1").await;
        insert_share(&store, "inst-1", "share-usage", "usage-sub", "active").await;
        {
            let conn = store.conn.lock().await;
            let now = Utc::now().timestamp();

            let mut recent_log =
                test_share_request_log_entry("req-usage-recent", "share-usage", now - 23 * 3600);
            recent_log.app_type = "codex".into();
            recent_log.user_email = Some("owner@example.com".into());
            recent_log.input_tokens = 20;
            recent_log.output_tokens = 5;
            upsert_share_request_log_tx(&conn, "inst-1", recent_log).expect("insert recent log");

            let mut old_log =
                test_share_request_log_entry("req-usage-old", "share-usage", now - 25 * 3600);
            old_log.app_type = "codex".into();
            old_log.user_email = Some("owner@example.com".into());
            old_log.input_tokens = 900;
            old_log.output_tokens = 100;
            upsert_share_request_log_tx(&conn, "inst-1", old_log).expect("insert old log");
        }

        let usage = store
            .share_usage_by_email("share-usage", "")
            .await
            .expect("usage");
        assert_eq!(usage.period, "24h");
        assert_eq!(usage.bucket_granularity, "hour");
        assert!((1..=2).contains(&usage.days));
        assert_eq!(usage.total_tokens, 25);
        let owner = usage
            .rows
            .iter()
            .find(|row| row.email == "owner@example.com")
            .expect("owner row");
        assert_eq!(owner.total_tokens, 25);
        assert!(owner.daily.len() >= 24);
        assert!(owner.daily.iter().all(|bucket| bucket.date.contains('T')));
        assert_eq!(
            owner
                .daily
                .iter()
                .map(|bucket| bucket.total_tokens)
                .sum::<u64>(),
            25
        );

        let _ = std::fs::remove_file(&config.database.path);
    }

    async fn insert_signed_installation(store: &AppStore, installation_id: &str) -> SigningKey {
        let signing_key = SigningKey::generate(&mut OsRng);
        let public_key = base64::engine::general_purpose::STANDARD
            .encode(signing_key.verifying_key().to_bytes());
        let now = Utc::now().to_rfc3339();
        let conn = store.conn.lock().await;
        conn.execute(
            "INSERT INTO installations (
                id, public_key, platform, app_version, owner_email, owner_verified_at,
                created_at, last_seen_at, client_activated_at, control_secret_b64
             ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?8, ?9)",
            params![
                installation_id,
                public_key,
                "macOS",
                "1.0.0",
                "owner@example.com",
                now,
                now,
                now,
                format!("control-{installation_id}"),
            ],
        )
        .expect("insert signed installation");
        signing_key
    }

    async fn insert_setup_client_tunnel(store: &AppStore, installation_id: &str, subdomain: &str) {
        let now = Utc::now().to_rfc3339();
        let conn = store.conn.lock().await;
        conn.execute(
            "INSERT INTO installation_client_tunnels (
                installation_id, owner_email, subdomain, enabled, created_at, updated_at
             ) VALUES (?1, 'owner@example.com', ?2, 1, ?3, ?3)",
            params![installation_id, subdomain, now],
        )
        .expect("insert setup client tunnel");
    }

    async fn claim_setup_client_tunnel(
        store: &AppStore,
        config: &Config,
        signing_key: &SigningKey,
        installation_id: &str,
        subdomain: &str,
    ) {
        let tunnel = ClientTunnelConfig {
            owner_email: "owner@example.com".into(),
            subdomain: subdomain.into(),
            enabled: true,
        };
        let timestamp_ms = Utc::now().timestamp_millis();
        let nonce = Uuid::new_v4().to_string();
        let signature = sign_test_payload(
            signing_key,
            installation_id,
            "client_tunnel_claim",
            &tunnel,
            timestamp_ms,
            &nonce,
        );
        store
            .claim_client_tunnel(
                config,
                ClientTunnelClaimRequest {
                    installation_id: installation_id.into(),
                    timestamp_ms,
                    nonce,
                    signature,
                    tunnel,
                },
                ClientMetadata {
                    ip: None,
                    country_code: None,
                },
            )
            .await
            .expect("claim setup client tunnel");
    }

    fn setup_completed_payload(
        setup_id: &str,
        password_hint: &str,
    ) -> InstallationSetupCompletedPayload {
        InstallationSetupCompletedPayload {
            protocol_version: 1,
            setup_id: setup_id.into(),
            password_hint: password_hint.into(),
        }
    }

    fn signed_setup_completed_request(
        signing_key: &SigningKey,
        installation_id: &str,
        setup: InstallationSetupCompletedPayload,
        timestamp_ms: i64,
        nonce: &str,
    ) -> InstallationSetupCompletedRequest {
        let signature = sign_test_payload(
            signing_key,
            installation_id,
            "installation_setup_completed_v1",
            &setup,
            timestamp_ms,
            nonce,
        );
        InstallationSetupCompletedRequest {
            protocol_epoch: PROTOCOL_EPOCH.into(),
            installation_id: installation_id.into(),
            timestamp_ms,
            nonce: nonce.into(),
            signature,
            setup,
        }
    }

    fn sign_test_payload<T: Serialize>(
        signing_key: &SigningKey,
        installation_id: &str,
        action: &str,
        payload: &T,
        timestamp_ms: i64,
        nonce: &str,
    ) -> String {
        let payload_json = serde_json::to_string(payload).expect("serialize test payload");
        let body = format!(
            "{PROTOCOL_EPOCH}\n{installation_id}\n{action}\n{payload_json}\n{timestamp_ms}\n{nonce}"
        );
        let signature = signing_key.sign(body.as_bytes());
        base64::engine::general_purpose::STANDARD.encode(signature.to_bytes())
    }

    fn signed_upgrade_task_report_request(
        signing_key: &SigningKey,
        installation_id: &str,
        payload: InstallationUpgradeTaskReportPayload,
        nonce: &str,
    ) -> InstallationUpgradeTaskReportRequest {
        signed_upgrade_task_report_request_at(
            signing_key,
            installation_id,
            payload,
            nonce,
            Utc::now().timestamp_millis(),
        )
    }

    fn signed_upgrade_task_report_request_at(
        signing_key: &SigningKey,
        installation_id: &str,
        payload: InstallationUpgradeTaskReportPayload,
        nonce: &str,
        timestamp_ms: i64,
    ) -> InstallationUpgradeTaskReportRequest {
        let signature = sign_test_payload(
            signing_key,
            installation_id,
            INSTALLATION_UPGRADE_TASK_REPORT_ACTION,
            &payload,
            timestamp_ms,
            nonce,
        );
        InstallationUpgradeTaskReportRequest {
            protocol_epoch: PROTOCOL_EPOCH.into(),
            installation_id: installation_id.into(),
            timestamp_ms,
            nonce: nonce.into(),
            signature,
            payload,
        }
    }

    fn upgrade_task_report_payload(
        task_id: &str,
        status: &str,
        level: &str,
        message: &str,
    ) -> InstallationUpgradeTaskReportPayload {
        let updated_at = Utc::now().to_rfc3339();
        InstallationUpgradeTaskReportPayload {
            task_id: task_id.into(),
            status: status.into(),
            restart_pending: status == "success",
            target_commit_id: Some("aabbccddeeff".into()),
            logs: vec![InstallationUpgradeLogEntry {
                task_id: task_id.into(),
                step: 7,
                total_steps: 7,
                level: level.into(),
                message: message.into(),
                progress: (status == "success").then_some(100),
                at: updated_at.clone(),
            }],
            restart_after: true,
            updated_at,
        }
    }

    fn sign_tunnel_test_payload<T: Serialize>(
        signing_key: &SigningKey,
        installation_id: &str,
        action: &str,
        payload: &T,
        timestamp_ms: i64,
        nonce: &str,
    ) -> String {
        let payload_json = serde_json::to_string(payload).expect("serialize tunnel test payload");
        let body = format!(
            "{PROTOCOL_EPOCH}\n{installation_id}\n{action}\n{payload_json}\n{timestamp_ms}\n{nonce}"
        );
        let signature = signing_key.sign(body.as_bytes());
        base64::engine::general_purpose::STANDARD.encode(signature.to_bytes())
    }

    #[test]
    fn setup_completed_payload_validation_is_strict() {
        let valid = setup_completed_payload("123e4567-e89b-42d3-a456-426614174000", "p******w");
        validate_installation_setup_completed_payload(&valid).expect("valid setup payload");

        for (setup_id, hint) in [
            ("123e4567-e89b-12d3-a456-426614174000", "p******w"),
            ("123E4567-E89B-42D3-A456-426614174000", "p******w"),
            ("not-a-uuid", "p******w"),
            ("123e4567-e89b-42d3-a456-426614174000", "password"),
            ("123e4567-e89b-42d3-a456-426614174000", "p*****w"),
            ("123e4567-e89b-42d3-a456-426614174000", "p******!"),
        ] {
            let invalid = setup_completed_payload(setup_id, hint);
            assert!(validate_installation_setup_completed_payload(&invalid).is_err());
        }

        let mut wrong_version = valid;
        wrong_version.protocol_version = 2;
        assert!(validate_installation_setup_completed_payload(&wrong_version).is_err());
        assert!(validate_request_nonce("short").is_err());
        assert!(validate_request_nonce("invalid nonce value").is_err());
    }

    #[test]
    fn setup_completed_request_rejects_unknown_envelope_and_payload_fields() {
        let base = serde_json::json!({
            "protocolEpoch": PROTOCOL_EPOCH,
            "installationId": "fixture-installation",
            "timestampMs": 1_700_000_000_789_i64,
            "nonce": "fixture-setup-123",
            "signature": "fixture-signature",
            "setup": {
                "protocolVersion": 1,
                "setupId": "123e4567-e89b-42d3-a456-426614174000",
                "passwordHint": "p******w"
            }
        });
        serde_json::from_value::<InstallationSetupCompletedRequest>(base.clone())
            .expect("strict request without extras");

        let mut extra_envelope = base.clone();
        extra_envelope["unexpected"] = serde_json::json!(true);
        assert!(
            serde_json::from_value::<InstallationSetupCompletedRequest>(extra_envelope).is_err()
        );

        let mut extra_payload = base;
        extra_payload["setup"]["unexpected"] = serde_json::json!(true);
        assert!(
            serde_json::from_value::<InstallationSetupCompletedRequest>(extra_payload).is_err()
        );
    }

    #[test]
    fn setup_completed_signature_fixture_matches_server_contract() {
        let signing_key = SigningKey::from_bytes(&[7_u8; 32]);
        let public_key = base64::engine::general_purpose::STANDARD
            .encode(signing_key.verifying_key().to_bytes());
        assert_eq!(public_key, "6kpsY+KcUgq+9VB7Ey7F+ZVHdq6+vnuSQh7qaRRG0iw=");
        let payload = setup_completed_payload("123e4567-e89b-42d3-a456-426614174000", "p******w");
        let signature = sign_test_payload(
            &signing_key,
            "fixture-installation",
            "installation_setup_completed_v1",
            &payload,
            1_700_000_000_789,
            "fixture-setup-123",
        );
        assert_eq!(
            signature,
            "q48WYcP91n3DWTvRyw9WysgC9AN5T3GM/2DyaDz18x2yKzyz/4iBkbXD+DYup6MtBtSGi+vEuaWhtO8kC4znCg=="
        );
    }

    #[test]
    fn setup_completed_response_statuses_are_stable() {
        for (status, expected) in [
            (InstallationSetupCompletedStatus::Queued, "queued"),
            (
                InstallationSetupCompletedStatus::AlreadyRecorded,
                "already_recorded",
            ),
            (
                InstallationSetupCompletedStatus::SuppressedDisabled,
                "suppressed_disabled",
            ),
        ] {
            let value = serde_json::to_value(InstallationSetupCompletedResponse {
                ok: true,
                setup_id: "123e4567-e89b-42d3-a456-426614174000".into(),
                status,
            })
            .expect("serialize setup completion response");
            assert_eq!(value["status"], expected);
            assert_eq!(value["setupId"], "123e4567-e89b-42d3-a456-426614174000");
        }
    }

    #[tokio::test]
    async fn client_becomes_visible_only_after_setup_completion() {
        let (store, config) = setup_store("client-activation-boundary").await;
        let signing_key = SigningKey::generate(&mut OsRng);
        let registered = register_with_key(&store, &signing_key, "1.0.0").await;
        let installation_id = registered.installation_id;
        let email = "owner@example.com";
        let payload = BindOwnerEmailSignaturePayload {
            email,
            verification_token: None,
        };

        assert!(store.list_all_installation_ids().await.unwrap().is_empty());
        assert_eq!(
            store
                .client_metrics_snapshot(Utc::now())
                .await
                .expect("metrics before Client activation")
                .total,
            0
        );

        for attempt in 0..2_i64 {
            let timestamp_ms = Utc::now().timestamp_millis() + attempt;
            let nonce = format!("activation-owner-bind-{attempt}");
            let signature = sign_test_payload(
                &signing_key,
                &installation_id,
                "bind_installation_owner_email",
                &payload,
                timestamp_ms,
                &nonce,
            );
            let bound = store
                .bind_installation_owner_email(
                    &config,
                    BindInstallationOwnerEmailRequest {
                        installation_id: installation_id.clone(),
                        email: email.into(),
                        verification_token: None,
                        timestamp_ms,
                        nonce,
                        signature,
                    },
                    None,
                )
                .await
                .expect("bind pre-activation owner idempotently");
            assert_eq!(bound.already_bound, attempt != 0);
            assert!(bound.owner_verified);
        }

        claim_setup_client_tunnel(
            &store,
            &config,
            &signing_key,
            &installation_id,
            "activationclient",
        )
        .await;
        {
            let conn = store.conn.lock().await;
            let state: (Option<String>, i64) = conn
                .query_row(
                    "SELECT client_activated_at,
                            (SELECT COUNT(*) FROM chat_rooms WHERE installation_id = ?1)
                     FROM installations WHERE id = ?1",
                    params![installation_id],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
                .expect("read pre-activation state");
            assert_eq!(state, (None, 0));
        }

        store
            .complete_installation_setup(signed_setup_completed_request(
                &signing_key,
                &installation_id,
                setup_completed_payload(&Uuid::new_v4().to_string(), "p******w"),
                Utc::now().timestamp_millis(),
                "activation-setup-complete",
            ))
            .await
            .expect("complete Client setup");

        assert_eq!(
            store.list_all_installation_ids().await.unwrap(),
            vec![installation_id.clone()]
        );
        assert_eq!(
            store
                .client_metrics_snapshot(Utc::now())
                .await
                .expect("metrics after Client activation")
                .total,
            1
        );
        let conn = store.conn.lock().await;
        let state: (bool, i64) = conn
            .query_row(
                "SELECT client_activated_at IS NOT NULL,
                        (SELECT COUNT(*) FROM chat_rooms WHERE installation_id = ?1)
                 FROM installations WHERE id = ?1",
                params![installation_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("read activated Client state");
        assert_eq!(state, (true, 1));

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn setup_completed_queues_one_redacted_notification_and_freezes_hint() {
        let config = enabled_notification_config("setup-completed-notification");
        let store = AppStore::new(&config).expect("create store");
        let installation_id = "inst-setup-completed";
        let signing_key = insert_signed_installation(&store, installation_id).await;
        insert_setup_client_tunnel(&store, installation_id, "setupclient").await;
        let setup_id = Uuid::new_v4().to_string();
        let timestamp_ms = Utc::now().timestamp_millis();
        let request = signed_setup_completed_request(
            &signing_key,
            installation_id,
            setup_completed_payload(&setup_id, "p******w"),
            timestamp_ms,
            "setup-notification-1",
        );
        let response = store
            .complete_installation_setup(request)
            .await
            .expect("complete setup");
        assert!(response.ok);
        assert_eq!(response.setup_id, setup_id);
        assert_eq!(response.status, InstallationSetupCompletedStatus::Queued);

        {
            let conn = store.conn.lock().await;
            let (dedupe_key, status, snapshot, password_hint): (
                String,
                String,
                String,
                Option<String>,
            ) = conn
                .query_row(
                    "SELECT e.dedupe_key, e.status, e.snapshot_json, isc.password_hint
                     FROM client_notification_events e
                     INNER JOIN installation_setup_completions isc ON isc.event_id = e.id
                     WHERE e.installation_id = ?1",
                    params![installation_id],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
                )
                .expect("read queued setup event");
            assert_eq!(dedupe_key, format!("setup:{installation_id}"));
            assert_eq!(status, "pending");
            assert_eq!(password_hint.as_deref(), Some("p******w"));
            assert!(!snapshot.contains("p******w"));
            assert!(!snapshot.contains("passwordHint"));
            assert!(snapshot.contains("setupCompletedAt"));
        }

        let duplicate_nonce = "setup-notification-2";
        let duplicate = signed_setup_completed_request(
            &signing_key,
            installation_id,
            setup_completed_payload(&Uuid::new_v4().to_string(), "x******y"),
            Utc::now().timestamp_millis(),
            duplicate_nonce,
        );
        let duplicate_response = store
            .complete_installation_setup(duplicate)
            .await
            .expect("duplicate completion remains idempotent");
        assert_eq!(
            duplicate_response.status,
            InstallationSetupCompletedStatus::AlreadyRecorded
        );
        assert_eq!(duplicate_response.setup_id, setup_id);

        let policy = notification_policy(&config);
        let delivery_at = Utc::now() + Duration::seconds(6);
        store
            .aggregate_client_notification_batches(&policy, &notification_template(), delivery_at)
            .await
            .expect("aggregate setup completion");
        let conn = store.conn.lock().await;
        let (html, text): (String, String) = conn
            .query_row(
                "SELECT html_body, text_body FROM notification_deliveries LIMIT 1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("read frozen setup email");
        for body in [&html, &text] {
            assert!(body.contains("https://setupclient.router.example.com/"));
            assert!(body.contains("Web password hint"));
            assert!(body.contains("p******w"));
            assert!(body.contains("This is not the complete password"));
            assert!(!body.contains("这不是完整密码"));
            assert!(!body.contains("Web 密码提示"));
        }
        let retained_hint: Option<String> = conn
            .query_row(
                "SELECT password_hint FROM installation_setup_completions
                 WHERE installation_id = ?1",
                params![installation_id],
                |row| row.get(0),
            )
            .expect("read retained setup hint");
        assert_eq!(retained_hint.as_deref(), Some("p******w"));
        drop(conn);

        let batch = expect_notification_batch(
            store
                .claim_client_notification_batch("setup-worker", delivery_at, 30)
                .await
                .expect("claim setup notification"),
            "setup notification batch",
        );
        assert!(
            store
                .validate_client_notification_batch(
                    &batch.id,
                    "setup-worker",
                    &policy,
                    delivery_at,
                )
                .await
                .expect("validate setup notification")
        );
        store
            .mark_client_notification_batch_sent(
                &batch.id,
                "setup-worker",
                "resend-setup-message",
                delivery_at,
            )
            .await
            .expect("mark setup notification sent");
        let conn = store.conn.lock().await;
        let cleared_hint: Option<String> = conn
            .query_row(
                "SELECT password_hint FROM installation_setup_completions
                 WHERE installation_id = ?1",
                params![installation_id],
                |row| row.get(0),
            )
            .expect("read cleared setup hint");
        assert!(cleared_hint.is_none());
        drop(conn);

        let deliveries = store
            .list_client_notification_deliveries(100)
            .await
            .expect("list setup deliveries");
        let admin_json = serde_json::to_string(&deliveries).expect("serialize admin deliveries");
        assert!(!admin_json.contains("p******w"));
        assert!(!admin_json.contains("htmlBody"));
        assert!(!admin_json.contains("textBody"));

        let _ = std::fs::remove_file(&config.database.path);
    }

