    #[derive(Clone)]
    struct MockGeoState {
        hits: Arc<AtomicUsize>,
        status: StatusCode,
        body: String,
    }

    async fn mock_geo_handler(State(state): State<MockGeoState>) -> impl IntoResponse {
        state.hits.fetch_add(1, AtomicOrdering::SeqCst);
        (state.status, state.body)
    }

    async fn start_mock_geo(
        status: StatusCode,
        body: &str,
    ) -> (String, Arc<AtomicUsize>, tokio::task::JoinHandle<()>) {
        let hits = Arc::new(AtomicUsize::new(0));
        let app = Router::new()
            .route("/*path", get(mock_geo_handler))
            .with_state(MockGeoState {
                hits: hits.clone(),
                status,
                body: body.to_string(),
            });
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let task = tokio::spawn(async move {
            axum::serve(listener, app).await.unwrap();
        });
        (format!("http://{address}"), hits, task)
    }

    #[tokio::test]
    async fn upgrade_status_uses_router_persistence_and_enforces_owner() {
        let (store, config) = setup_store("upgrade-status-route").await;
        insert_installation(&store, "inst-upgrade-status").await;
        insert_client_tunnel(
            &store,
            "inst-upgrade-status",
            "owner@example.com",
            "upgrade-status-sub",
        )
        .await;
        store
            .record_installation_upgrade_started(
                "inst-upgrade-status",
                "task-running",
                "owner@example.com",
                true,
            )
            .await
            .expect("record accepted upgrade before the client tunnel disappears");
        let conn = store.conn.lock().await;
        conn.execute(
            "UPDATE installations
             SET delegate_upgrade_to_router_owner = 0, upgrade_capable = 0
             WHERE id = 'inst-upgrade-status'",
            [],
        )
        .expect("disable future upgrades");
        drop(conn);

        let status = store
            .installation_upgrade_status_for_owner(
                "inst-upgrade-status",
                Some("task-running"),
                "owner@example.com",
            )
            .await
            .expect("owner should read persisted status without a client tunnel");
        assert_eq!(status.task_id, "task-running");
        assert_eq!(status.status, "running");

        let latest_running = store
            .installation_upgrade_status_for_owner("inst-upgrade-status", None, "owner@example.com")
            .await
            .expect("latest persisted task should be discoverable after refresh");
        assert_eq!(latest_running.task_id, "task-running");

        let start_error = store
            .prepare_installation_upgrade(&config, "inst-upgrade-status", "owner@example.com")
            .await
            .expect_err("new upgrade must still honor delegation");
        assert!(start_error.to_string().contains("delegation is disabled"));

        let owner_error = store
            .installation_upgrade_status_for_owner(
                "inst-upgrade-status",
                Some("task-running"),
                "other@example.com",
            )
            .await
            .expect_err("other users cannot inspect upgrade state");
        assert!(owner_error.to_string().contains("only installation owner"));

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn upgrade_status_becomes_lost_after_confirmation_deadline() {
        let (store, config) = setup_store("upgrade-status-lost").await;
        let installation_id = "inst-upgrade-lost";
        insert_installation(&store, installation_id).await;
        store
            .record_installation_upgrade_started(
                installation_id,
                "task-running",
                "owner@example.com",
                true,
            )
            .await
            .expect("record running upgrade");

        let pending = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-running"),
                "owner@example.com",
            )
            .await
            .expect("read fresh running upgrade");
        assert_eq!(pending.status_sync, "pending");

        let stale_at = (Utc::now() - Duration::seconds(INSTALLATION_UPGRADE_STATUS_LOST_SECS + 1))
            .to_rfc3339();
        let conn = store.conn.lock().await;
        conn.execute(
            "UPDATE installation_upgrade_tasks
             SET created_at = ?3, updated_at = ?3
             WHERE installation_id = ?1 AND task_id = ?2",
            params![installation_id, "task-running", stale_at],
        )
        .expect("age running upgrade beyond confirmation deadline");
        drop(conn);

        let lost = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-running"),
                "owner@example.com",
            )
            .await
            .expect("read stale running upgrade");
        assert_eq!(lost.status, "running");
        assert_eq!(lost.status_sync, "lost");

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn client_status_reconciliation_requires_the_expected_task() {
        let (store, config) = setup_store("upgrade-status-reconcile").await;
        let installation_id = "inst-upgrade-reconcile";
        insert_installation(&store, installation_id).await;
        store
            .record_installation_upgrade_started(
                installation_id,
                "task-current",
                "owner@example.com",
                true,
            )
            .await
            .expect("record current upgrade");

        let mismatch = store
            .reconcile_installation_upgrade_status_from_client(
                installation_id,
                "task-current",
                upgrade_task_report_payload(
                    "task-other",
                    "success",
                    "success",
                    "wrong task completed",
                ),
            )
            .await
            .expect_err("a different client task must not overwrite the current task");
        assert!(mismatch.to_string().contains("does not match Router task"));

        let still_running = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-current"),
                "owner@example.com",
            )
            .await
            .expect("read current task after rejected reconciliation");
        assert_eq!(still_running.status, "running");
        assert_eq!(still_running.status_sync, "pending");

        store
            .reconcile_installation_upgrade_status_from_client(
                installation_id,
                "task-current",
                upgrade_task_report_payload(
                    "task-current",
                    "success",
                    "success",
                    "client confirmed the replacement process",
                ),
            )
            .await
            .expect("reconcile matching client task");
        let completed = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-current"),
                "owner@example.com",
            )
            .await
            .expect("read reconciled task");
        assert_eq!(completed.status, "success");
        assert_eq!(completed.status_sync, "reported");
        assert_eq!(
            completed.logs[0].message,
            "client confirmed the replacement process"
        );

        let mut stale_running = upgrade_task_report_payload(
            "task-current",
            "running",
            "progress",
            "stale running snapshot",
        );
        stale_running.updated_at = (Utc::now() - Duration::minutes(1)).to_rfc3339();
        stale_running.logs[0].at = stale_running.updated_at.clone();
        store
            .reconcile_installation_upgrade_status_from_client(
                installation_id,
                "task-current",
                stale_running,
            )
            .await
            .expect("ignore a stale client status snapshot");
        let still_completed = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-current"),
                "owner@example.com",
            )
            .await
            .expect("read task after stale reconciliation");
        assert_eq!(still_completed.status, "success");
        assert_eq!(
            still_completed.logs[0].message,
            "client confirmed the replacement process"
        );

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn signed_upgrade_reports_update_tasks_without_terminal_regression() {
        let (store, config) = setup_store("signed-upgrade-task-report").await;
        let installation_id = "inst-upgrade-report";
        let signing_key = insert_signed_installation(&store, installation_id).await;
        store
            .record_installation_upgrade_started(
                installation_id,
                "task-failed",
                "owner@example.com",
                true,
            )
            .await
            .expect("record failed task start");

        let failed_payload = upgrade_task_report_payload(
            "task-failed",
            "failed",
            "error",
            "replacement process failed health checks",
        );
        store
            .report_installation_upgrade_task(signed_upgrade_task_report_request(
                &signing_key,
                installation_id,
                failed_payload,
                "upgrade-report-failed",
            ))
            .await
            .expect("accept signed failed report");

        let delayed_running = upgrade_task_report_payload(
            "task-failed",
            "running",
            "progress",
            "delayed running report",
        );
        store
            .report_installation_upgrade_task(signed_upgrade_task_report_request(
                &signing_key,
                installation_id,
                delayed_running,
                "upgrade-report-delayed-running",
            ))
            .await
            .expect("accept delayed report without regressing terminal state");

        let failed = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-failed"),
                "owner@example.com",
            )
            .await
            .expect("read failed task from router database");
        assert_eq!(failed.status, "failed");
        assert_eq!(failed.logs.len(), 1);
        assert_eq!(
            failed.logs[0].message,
            "replacement process failed health checks"
        );

        store
            .record_installation_upgrade_started(
                installation_id,
                "task-success",
                "owner@example.com",
                true,
            )
            .await
            .expect("record second task start");
        let success_payload = upgrade_task_report_payload(
            "task-success",
            "success",
            "success",
            "replacement process passed health and version checks",
        );
        let success_reported_at_ms = Utc::now().timestamp_millis() + 1_000;
        store
            .report_installation_upgrade_task(signed_upgrade_task_report_request_at(
                &signing_key,
                installation_id,
                success_payload.clone(),
                "upgrade-report-success",
                success_reported_at_ms,
            ))
            .await
            .expect("accept signed success report");

        let stale_failed =
            upgrade_task_report_payload("task-success", "failed", "error", "stale failure report");
        store
            .report_installation_upgrade_task(signed_upgrade_task_report_request_at(
                &signing_key,
                installation_id,
                stale_failed,
                "upgrade-report-stale-failed",
                success_reported_at_ms - 1,
            ))
            .await
            .expect("accept but ignore stale signed report");

        let delayed_old_task = upgrade_task_report_payload(
            "task-failed",
            "running",
            "progress",
            "old task reported after the newer task",
        );
        store
            .report_installation_upgrade_task(signed_upgrade_task_report_request(
                &signing_key,
                installation_id,
                delayed_old_task,
                "upgrade-report-old-task-late",
            ))
            .await
            .expect("accept late report for older task");

        let replay = store
            .report_installation_upgrade_task(signed_upgrade_task_report_request_at(
                &signing_key,
                installation_id,
                success_payload,
                "upgrade-report-success",
                success_reported_at_ms,
            ))
            .await
            .expect_err("signed report nonce must not be replayable");
        assert!(replay.to_string().contains("nonce"));

        let latest = store
            .installation_upgrade_status_for_owner(
                installation_id,
                Some("task-success"),
                "owner@example.com",
            )
            .await
            .expect("read successful task by id");
        assert_eq!(latest.task_id, "task-success");
        assert_eq!(latest.status, "success");
        assert!(latest.restart_pending);
        assert_eq!(
            latest.logs[0].message,
            "replacement process passed health and version checks"
        );
        let no_running_task = store
            .installation_upgrade_status_for_owner(installation_id, None, "owner@example.com")
            .await
            .expect_err("terminal tasks must not be restored as active upgrades");
        assert!(no_running_task.to_string().contains("not found"));

        let _ = std::fs::remove_file(&config.database.path);
    }

