    #[tokio::test]
    async fn renew_lease_extends_active_connection_without_replacing_route() {
        let (store, mut config) = setup_store("renew-active-lease").await;
        config.lease_ttl_secs = 300;
        let signing_key = insert_signed_installation(&store, "inst-active-renew").await;
        insert_share(
            &store,
            "inst-active-renew",
            "share-active-renew",
            "active-renew-sub",
            "active",
        )
        .await;
        let proxy = ProxyRegistry::default();
        let issued_at_ms = Utc::now().timestamp_millis();
        let issue_nonce = Uuid::new_v4().to_string();
        let mut issue_request = IssueLeaseRequest {
            protocol_epoch: PROTOCOL_EPOCH.into(),
            router_id: "127.0.0.1".into(),
            installation_id: "inst-active-renew".into(),
            route_id: "share:share-active-renew".into(),
            rotation_id: Uuid::new_v4().to_string(),
            generation: 1,
            expected_generation: 0,
            requested_subdomain: "active-renew-sub".into(),
            tunnel_type: "http".into(),
            timestamp_ms: issued_at_ms,
            nonce: issue_nonce,
            signature: String::new(),
            share: Some(test_share_descriptor(
                "share-active-renew",
                "active-renew-sub",
            )),
            signed_share: None,
        };
        issue_request.signature = sign_issue_lease_request(&signing_key, &issue_request);
        let lease = store
            .issue_lease(
                &config,
                &proxy,
                issue_request,
                ClientMetadata {
                    ip: Some("127.0.0.1".into()),
                    country_code: None,
                },
                None,
            )
            .await
            .expect("issue active lease");
        store
            .consume_lease(&lease.ssh_username, &lease.ssh_password)
            .await
            .expect("consume active lease");
        store
            .mark_lease_ready(&lease.connection_id, &lease.route_id, lease.generation)
            .await
            .expect("mark lease ready");
        proxy
            .register_candidate_with_kind(
                "active-renew-sub".into(),
                "127.0.0.1:65530".into(),
                RouteKind::Share,
                Some("inst-active-renew".into()),
                Some(lease.connection_id.clone()),
                Some("share-active-renew".into()),
                Some("Active Renew".into()),
                false,
                -1,
                None,
                lease.generation,
                lease.rotation_id.clone(),
            )
            .await
            .expect("register active test candidate");
        proxy
            .promote_candidate(
                "active-renew-sub",
                &lease.connection_id,
                &lease.rotation_id,
                lease.generation,
                lease.expected_generation,
            )
            .await
            .expect("promote active test candidate");
        {
            let conn = store.conn.lock().await;
            conn.execute(
                "UPDATE leases SET state = 'active' WHERE id = ?1",
                params![lease.lease_id],
            )
            .expect("mark test lease active");
            conn.execute(
                "INSERT INTO tunnel_route_heads (
                    router_id, route_id, subdomain, active_generation,
                    active_connection_id, active_rotation_id, updated_at
                 ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                params![
                    lease.router_id,
                    lease.route_id,
                    lease.subdomain,
                    lease.generation as i64,
                    lease.connection_id,
                    lease.rotation_id,
                    Utc::now().to_rfc3339(),
                ],
            )
            .expect("seed active route head");
        }

        let renewal = RenewLeasePayload {
            protocol_epoch: lease.protocol_epoch.clone(),
            router_id: lease.router_id.clone(),
            lease_id: lease.lease_id.clone(),
            connection_id: lease.connection_id.clone(),
            route_id: lease.route_id.clone(),
            rotation_id: lease.rotation_id.clone(),
            generation: lease.generation,
            expected_generation: lease.expected_generation,
        };
        let timestamp_ms = Utc::now().timestamp_millis();
        let nonce = Uuid::new_v4().to_string();
        let request = RenewLeaseRequest {
            installation_id: "inst-active-renew".into(),
            timestamp_ms,
            nonce: nonce.clone(),
            signature: sign_tunnel_test_payload(
                &signing_key,
                "inst-active-renew",
                "tunnel_lease_renew",
                &renewal,
                timestamp_ms,
                &nonce,
            ),
            renewal,
        };
        let renewed = store
            .renew_lease(
                &config,
                &proxy,
                request.clone(),
                ClientMetadata {
                    ip: Some("127.0.0.1".into()),
                    country_code: None,
                },
            )
            .await
            .expect("renew active lease");

        assert!(renewed.expires_at >= lease.expires_at);
        let route = proxy
            .backend_for_host(
                &format!("active-renew-sub.{}", config.tunnel_domain),
                &config.tunnel_domain,
            )
            .await
            .expect("active route remains registered");
        assert_eq!(route.connection_id(), Some(lease.connection_id.as_str()));
        let replay = store
            .renew_lease(
                &config,
                &proxy,
                request,
                ClientMetadata {
                    ip: None,
                    country_code: None,
                },
            )
            .await
            .expect_err("renewal nonce replay must fail");
        assert!(replay.to_string().contains("nonce already used"));

        let _ = std::fs::remove_file(&config.database.path);
    }

