    #[tokio::test]
    async fn batch_sync_shares_requires_valid_signature() {
        let (store, config) = setup_store("signed-share-batch").await;
        let signing_key = insert_signed_installation(&store, "inst-batch").await;
        insert_client_tunnel(
            &store,
            "inst-batch",
            "owner@example.com",
            TEST_CLIENT_SUBDOMAIN,
        )
        .await;

        let share = ShareDescriptor {
            contract_version: SHARE_CONTRACT_VERSION,
            share_id: "share-batch-1".into(),
            capacity_pool_id: "pool-share-batch-1".into(),
            share_name: "Batch Share".into(),
            owner_email: Some("owner@example.com".into()),
            description: Some("signed batch sync".into()),
            free_access: false,
            subdomain: test_share_host("batch-sub"),
            app_type: "codex".into(),
            provider_id: Some("provider-batch".into()),
            bindings: BTreeMap::from([("codex".into(), "provider-batch".into())]),
            token_limit: 2048,
            parallel_limit: 3,
            tokens_used: 12,
            requests_count: 3,
            share_status: "active".into(),
            created_at: Utc::now().to_rfc3339(),
            expires_at: (Utc::now() + Duration::hours(2)).to_rfc3339(),
            support: ShareSupport {
                // Only APIs with a provider binding can be enabled.  The
                // multi-app descriptor validator intentionally rejects an
                // enabled app that is absent from `bindings`.
                claude: false,
                codex: true,
                gemini: false,
            },
            upstream_provider: None,
            app_runtimes: ShareAppRuntimes::default(),
            app_providers: ShareAppProviders::default(),
            app_availability: ShareAppAvailability::default(),
            model_health: ShareModelHealthSummary::default(),
            auto_start: false,
            allow_personal_credits: false,
            auto_consume_banked_reset: false,
            banked_reset_expiry_lead_minutes:
                crate::models::DEFAULT_BANKED_RESET_EXPIRY_LEAD_MINUTES,
            previous_response_cache_enabled: false,
            config_revision: 0,
            descriptor_generation: 0,
            descriptor_fingerprint: String::new(),
            user_grants: BTreeMap::new(),
            supported_user_token_periods: legacy_supported_user_token_periods(),
        };
        let ops = vec![ShareSyncOperation {
            kind: "upsert".into(),
            share: Some(share.clone()),
            share_id: None,
        }];

        let timestamp_ms = Utc::now().timestamp_millis();
        let nonce = Uuid::new_v4().to_string();
        let signature = sign_test_payload(
            &signing_key,
            "inst-batch",
            "share_batch_sync",
            &ops,
            timestamp_ms,
            &nonce,
        );

        store
            .batch_sync_shares(
                ShareBatchSyncRequest {
                    installation_id: "inst-batch".into(),
                    timestamp_ms,
                    nonce,
                    signature,
                    ops,
                },
                ClientMetadata {
                    ip: Some("127.0.0.1".into()),
                    country_code: None,
                },
                "owner@example.com",
            )
            .await
            .expect("valid signed batch sync");

        let conn = store.conn.lock().await;
        let synced: (String, String, i64, Option<String>, i64) = conn
            .query_row(
                "SELECT share_name, subdomain, token_limit, description, free_access FROM shares
                 WHERE installation_id = ?1 AND share_id = ?2",
                params!["inst-batch", "share-batch-1"],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                    ))
                },
            )
            .expect("query synced share");
        drop(conn);
        assert_eq!(synced.0, "owner@example.com");
        assert_eq!(synced.1, test_share_host("batch-sub"));
        assert_eq!(synced.2, 2048);
        assert_eq!(synced.3.as_deref(), Some("signed batch sync"));
        assert_eq!(synced.4, 0);

        let tampered_ops = vec![ShareSyncOperation {
            kind: "upsert".into(),
            share: Some(ShareDescriptor {
                share_name: "Batch Share Tampered".into(),
                ..share
            }),
            share_id: None,
        }];
        let tampered_err = store
            .batch_sync_shares(
                ShareBatchSyncRequest {
                    installation_id: "inst-batch".into(),
                    timestamp_ms: Utc::now().timestamp_millis(),
                    nonce: Uuid::new_v4().to_string(),
                    signature: sign_test_payload(
                        &signing_key,
                        "inst-batch",
                        "share_batch_sync",
                        &vec![ShareSyncOperation {
                            kind: "upsert".into(),
                            share: Some(ShareDescriptor {
                                share_name: "Different".into(),
                                ..tampered_ops[0].share.clone().expect("share")
                            }),
                            share_id: None,
                        }],
                        Utc::now().timestamp_millis(),
                        &Uuid::new_v4().to_string(),
                    ),
                    ops: tampered_ops,
                },
                ClientMetadata {
                    ip: Some("127.0.0.1".into()),
                    country_code: None,
                },
                "owner@example.com",
            )
            .await
            .expect_err("tampered batch sync should fail");
        assert!(
            tampered_err
                .to_string()
                .contains("signature verification failed")
        );

        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn strict_share_descriptor_sync_is_monotonic_and_blocks_legacy_overwrite() {
        let (store, config) = setup_store("strict-share-descriptor-sync").await;
        let installation_id = "inst-strict-descriptor";
        let signing_key = insert_signed_installation(&store, installation_id).await;
        insert_client_tunnel(
            &store,
            installation_id,
            "owner@example.com",
            TEST_CLIENT_SUBDOMAIN,
        )
        .await;

        let make_request = |share: ShareDescriptor, action: &str| {
            let ops = vec![ShareSyncOperation {
                kind: "upsert".into(),
                share: Some(share),
                share_id: None,
            }];
            let timestamp_ms = Utc::now().timestamp_millis();
            let nonce = Uuid::new_v4().to_string();
            let signature = sign_test_payload(
                &signing_key,
                installation_id,
                action,
                &ops,
                timestamp_ms,
                &nonce,
            );
            ShareBatchSyncRequest {
                installation_id: installation_id.into(),
                timestamp_ms,
                nonce,
                signature,
                ops,
            }
        };
        let metadata = || ClientMetadata {
            ip: Some("127.0.0.1".into()),
            country_code: None,
        };

        let mut descriptor = test_share_descriptor(
            "share-strict-descriptor",
            &test_share_host("strict-descriptor"),
        );
        descriptor.share_name = "strict descriptor".into();
        descriptor.config_revision = 4;
        descriptor.descriptor_generation = 2;
        descriptor.descriptor_fingerprint = "a".repeat(64);

        let first = store
            .batch_sync_share_descriptors(
                make_request(descriptor.clone(), "share_descriptor_batch_sync"),
                metadata(),
            )
            .await
            .expect("accept first strict descriptor");
        assert_eq!(first.len(), 1);
        assert!(first[0].applied);
        assert_eq!(first[0].descriptor_generation, 2);

        let replay = store
            .batch_sync_share_descriptors(
                make_request(descriptor.clone(), "share_descriptor_batch_sync"),
                metadata(),
            )
            .await
            .expect("accept exact descriptor replay");
        assert!(!replay[0].applied);

        let mut regressed = descriptor.clone();
        regressed.descriptor_generation = 1;
        let regression_error = store
            .batch_sync_share_descriptors(
                make_request(regressed, "share_descriptor_batch_sync"),
                metadata(),
            )
            .await
            .expect_err("reject descriptor generation regression");
        assert!(regression_error.to_string().contains("regressed"));

        let mut changed_without_generation = descriptor.clone();
        changed_without_generation.descriptor_fingerprint = "b".repeat(64);
        let fingerprint_error = store
            .batch_sync_share_descriptors(
                make_request(changed_without_generation, "share_descriptor_batch_sync"),
                metadata(),
            )
            .await
            .expect_err("reject fingerprint change without generation");
        assert!(
            fingerprint_error
                .to_string()
                .contains("fingerprint changed")
        );

        let mut legacy = descriptor;
        legacy.share_name = "legacy overwrite".into();
        legacy.config_revision = 999;
        legacy.descriptor_generation = 0;
        legacy.descriptor_fingerprint.clear();
        store
            .batch_sync_shares(
                make_request(legacy, "share_batch_sync"),
                metadata(),
                "owner@example.com",
            )
            .await
            .expect("legacy sync remains accepted as a no-op");

        let conn = store.conn.lock().await;
        let persisted = conn
            .query_row(
                "SELECT share_name, descriptor_generation, descriptor_fingerprint
                 FROM shares WHERE share_id = 'share-strict-descriptor'",
                [],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, i64>(1)?,
                        row.get::<_, String>(2)?,
                    ))
                },
            )
            .expect("read persisted strict descriptor");
        assert_eq!(persisted, ("owner@example.com".into(), 2, "a".repeat(64)));

        let _ = std::fs::remove_file(&config.database.path);
    }

