    #[tokio::test]
    async fn upsert_share_validates_and_persists_multiple_provider_bindings() {
        let (store, config) = setup_store("share-multi-binding-validation").await;
        insert_installation(&store, "inst-binding").await;
        let conn = store.conn.lock().await;

        let mut missing = test_share_descriptor("share-missing", "missing-sub");
        missing.bindings.clear();
        let missing_error = upsert_share_tx(&conn, "inst-binding", missing).unwrap_err();
        assert!(
            missing_error
                .to_string()
                .contains("between one and three app bindings")
        );

        let mut multiple = test_share_descriptor("share-multiple", "multiple-sub");
        multiple
            .bindings
            .insert("claude".into(), "provider-claude".into());
        multiple.support.claude = true;
        upsert_share_tx(&conn, "inst-binding", multiple).expect("store multi-app share");
        let stored_bindings = conn
            .prepare(
                "SELECT app_type, provider_id FROM share_bindings WHERE share_id = ?1 ORDER BY app_type",
            )
            .expect("prepare stored bindings")
            .query_map(params!["share-multiple"], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .expect("query stored bindings")
            .collect::<Result<Vec<_>, _>>()
            .expect("read stored bindings");
        assert_eq!(
            stored_bindings,
            vec![
                ("claude".to_string(), "provider-claude".to_string()),
                ("codex".to_string(), "provider-test".to_string()),
            ]
        );
        let (_, persisted) = list_shares(&conn)
            .expect("list persisted shares")
            .into_iter()
            .find(|(_, share)| share.share_id == "share-multiple")
            .expect("persisted multi-app share");
        assert_eq!(persisted.contract_version, SHARE_CONTRACT_VERSION);
        assert!(!persisted.free_access);

        let mut mismatched = test_share_descriptor("share-mismatch", "mismatch-sub");
        mismatched.provider_id = Some("different-provider".into());
        let mismatch_error = upsert_share_tx(&conn, "inst-binding", mismatched).unwrap_err();
        assert!(
            mismatch_error
                .to_string()
                .contains("must match one of its bindings")
        );

        drop(conn);
        let _ = std::fs::remove_file(&config.database.path);
    }

    #[tokio::test]
    async fn upsert_share_rejects_stale_config_revision_and_preserves_settings() {
        let (store, config) = setup_store("share-config-revision").await;
        insert_installation(&store, "inst-revision").await;
        let mut newest = test_share_descriptor("share-revision", "revision-sub");
        newest.config_revision = 2;
        newest.description = Some("new description".into());
        newest.user_grants = BTreeMap::from([
            (
                "owner@example.com".to_string(),
                test_share_user_grant("owner@example.com", "owner", 1_000),
            ),
            (
                "buyer@example.com".to_string(),
                test_share_user_grant("buyer@example.com", "shareto", 500),
            ),
        ]);
        newest.token_limit = 50_000;
        newest.parallel_limit = 7;
        newest.expires_at = "2030-01-01T00:00:00Z".into();
        {
            let conn = store.conn.lock().await;
            upsert_share_tx(&conn, "inst-revision", newest).expect("write newest revision");
        }

        let mut stale = test_share_descriptor("share-revision", "revision-sub");
        stale.config_revision = 1;
        stale.description = Some("stale description".into());
        stale.token_limit = 100;
        stale.parallel_limit = 3;
        {
            let conn = store.conn.lock().await;
            upsert_share_tx(&conn, "inst-revision", stale).expect("stale write is idempotent");
            let (_, stored) = list_shares(&conn)
                .expect("list shares")
                .into_iter()
                .find(|(_, share)| share.share_id == "share-revision")
                .expect("stored share");
            assert_eq!(stored.config_revision, 2);
            assert_eq!(stored.description.as_deref(), Some("new description"));
            assert!(stored.user_grants.contains_key("buyer@example.com"));
            assert_eq!(stored.token_limit, 50_000);
            assert_eq!(stored.parallel_limit, 7);
            assert_eq!(stored.expires_at, "2030-01-01T00:00:00Z");
        }

        let _ = std::fs::remove_file(&config.database.path);
    }

