        let now = Utc::now().to_rfc3339();
        let conn = store.conn.lock().await;
        conn.execute(
            "INSERT OR IGNORE INTO users (id, email_normalized, status, created_at, last_login_at)
             VALUES (?1, lower(?2), 'active', ?3, ?3)",
            params![user_id, email, now],
        )
